const std = @import("std");
const types = @import("blob_encoder").presentation_types;
const cell_font_metrics = @import("font_scale.zig");

pub const Scope = u64;
/// Null means unknown; an empty ID proves parsed attribute absence. This context
/// is build-only and never inherited as the identity of another element.
fn positivePageAncestorClass(root: *const TextElement, name: []const u8) bool {
    var cursor: ?*const TextElement = root;
    var remaining: usize = 64;
    while (cursor) |node| : (cursor = node.parent) {
        if (remaining == 0) return false;
        remaining -= 1;
        if (Profile.hasClass(node.classes, name)) return true;
    }
    return false;
}

pub const ElementContext = struct {
    page_style_root: ?*const TextElement = null,
    // Only the ordinary HTML font compiler may certify this projection.
    font_size_consumed: bool = false,
    // Same-profile own TD weight was applied to the emitted cell formatting.
    font_weight_consumed: bool = false,
    custom_environment: ?CustomEnvironment = null,
    // Producer has applied this same element/profile text-color cascade.
    text_color_consumed: bool = false,
    absent_own_attribute: ?[]const u8 = null,
    computed_border_collapse: ?BorderCollapseState = null,
    // Own HTML presentational hint, lower priority than all author CSS.
    legacy_vertical_align: ?[]const u8 = null,
    // Own preferred cell-width HTML hint, never an intrinsic minimum.
    legacy_cell_width: ?[]const u8 = null,
    ancestor_classes: ?[]const u8 = null,
    own_id: ?[]const u8 = null,
    // Null means unknown ancestry. A nonnull list overapproximates all IDs
    // through an independently proved original content root; build-only.
    complete_font_ancestor_ids: ?[]const []const u8 = null,
    // Complete original DOM ancestry, issued by a source-bound Table callback.
    complete_table_ancestor_ids: ?[]const []const u8 = null,
    // Single wiki TD/TH query. Source and logical ancestry can exclude a
    // required ID, but its presence in the page cannot establish a CSS match.
    cell_ancestor_id_superset: ?[]const u8 = null,
    // Union across every selected head: negative evidence only.
    complete_table_ancestor_classes: ?[]const u8 = null,
    // Complete original ancestor tag inventory; null retains uncertainty.
    complete_font_ancestor_tags: ?[]const []const u8 = null,
};
pub const TableResolution = struct { resolved_legacy_border: bool = false, float_viewport: ?types.TableFloatViewport = null, block_viewport: ?*const types.TableBlockViewport = null, style: ?types.TableStyle, scope: Scope, unresolved: bool, margin_basis_unresolved: bool = false, background_specified: bool = false, descendant_style_unresolved: bool = false, width_specified: bool = false, line_height_em: ?f32 = null };
pub const CellSourceScopeHazards = struct { height: bool = false, font_context: bool = false };
pub const CellResolution = struct { style: ?types.CellStyle, background: ?[]const u8, background_specified: bool, unresolved: bool, padding_basis_unresolved: bool = false, alignment_specified: bool = false, line_height: ?cell_font_metrics.CellLineHeightSpecified = null, line_height_refused: bool = false };
const max_css_bytes = 1024 * 1024;
const max_rules = 4096;
const Target = enum { element, table, cell, th, td, other };
const Property = enum { background, border, corner_radii, collapse, margins, margin_top, margin_right, margin_bottom, margin_left, padding, text_align, float_side, width, min_width, clear, box_sizing, layout_reset, display, vertical_align, line_height, list_style, font_size, text_color, cell_opacity, other };
const Value = union(enum) {
    color: []const u8,
    no_background,
    border: types.StyleBorder,
    corner_radii: types.TableCornerRadii,
    collapse: types.BorderCollapse,
    edges: types.StyleEdges,
    margin_values: types.ContainerMargins,
    margin_edge: types.ContainerMargin,
    align_value: types.CellTextAlign,
    float_value: types.TableFloatSide,
    no_float,
    width_value: types.StyleWidth,
    auto_width,
    border_box,
    clear_value: types.FigureClear,
    length_value: types.StyleLength,
    display_value: types.TableDisplay,
    vertical_align_value: types.InlineBoxVerticalAlign,
    cell_vertical_align_value: types.CellVerticalAlign,
    line_height_em: f32,
    cell_line_height: cell_font_metrics.CellLineHeightSpecified,
    opacity: f32,
    list_style_none,
    font_size_consumed,
    unsupported,
};
const Declaration = struct { consumable_font_weight: bool = false, cell_source_hazards: CellSourceScopeHazards = .{}, cell_context_property: bool = false, cell_line_height_raw: ?[]const u8 = null, border_update: ?BorderUpdate = null, border_raw: ?struct { name: []const u8, value: []const u8 } = null, property: Property, value: Value, important: bool, order: u32, affects_font_basis: bool = false, may_name_min_width: bool = false, custom_paint: ?[]const u8 = null };
const Selector = struct {
    complete_own_attribute: ?[]const u8 = null,
    target: Target,
    mask: Scope,
    ancestor_mask: Scope = 0,
    ancestor_class: ?[]const u8 = null,
    own_classes: []const []const u8 = &.{},
    own_ids: []const []const u8 = &.{},
    own_tag: ?[]const u8 = null,
    necessary_classes: []const []const u8 = &.{},
    necessary_ancestor_ids: []const []const u8 = &.{},
    specificity: u64,
    unsupported: bool,
};
const Rule = struct { selector: Selector, declarations: []const Declaration, number: u32 };
const Priority = struct {
    important: bool = false,
    specificity: u64 = 0,
    order: u32 = 0,
    inline_style: bool = false,
    fn wins(self: Priority, prior: Priority) bool {
        if (self.important != prior.important) return self.important;
        if (self.inline_style != prior.inline_style) return self.inline_style;
        if (self.specificity != prior.specificity) return self.specificity > prior.specificity;
        return self.order >= prior.order;
    }
};
const Winner = struct { value: Value, priority: Priority };
const Winners = struct {
    borders: BorderCascade = .{},
    slots: [@typeInfo(Property).@"enum".field_names.len]?Winner = @splat(null),
    selector_unresolved: bool = false,
    font_basis_unresolved: bool = false,
    fn add(self: *Winners, declaration: Declaration, specificity: u64, conditional: bool, inline_style: bool) void {
        if (declaration.may_name_min_width) {
            // An escaped property name may be min-width. Keep its original
            // unsupported slot too; no other property gains escape support.
            var possible = declaration;
            possible.property = .min_width;
            possible.value = .unsupported;
            possible.may_name_min_width = false;
            self.add(possible, specificity, conditional, inline_style);
        }
        if (declaration.affects_font_basis) self.font_basis_unresolved = true;
        const index = @backingInt(declaration.property);
        const next: Priority = .{ .important = declaration.important, .specificity = specificity, .order = declaration.order, .inline_style = inline_style };
        if (declaration.border_update) |update| {
            self.borders.add(update, next, conditional);
            return;
        }
        if (self.slots[index]) |prior| if (!next.wins(prior.priority)) return;
        self.slots[index] = .{ .value = if (conditional) .unsupported else declaration.value, .priority = next };
    }
    fn value(self: Winners, property: Property) ?Value {
        if (property == .border) {
            const border = self.borders.result();
            if (border.unresolved) return .unsupported;
            if (border.value) |known| return if (styleBorderFromContainer(known)) |style| .{ .border = style } else .unsupported;
        }
        var selected = self.slots[@backingInt(property)];
        if (property == .corner_radii or property == .float_side or property == .text_align or property == .width or property == .min_width or property == .clear or property == .padding or property == .box_sizing or property == .display or property == .vertical_align or property == .line_height or property == .list_style or property == .font_size or property == .cell_opacity) if (self.slots[@backingInt(Property.layout_reset)]) |reset| {
            if (selected == null or reset.priority.wins(selected.?.priority)) selected = reset;
        };
        return if (selected) |winner| winner.value else null;
    }
    fn unresolved(self: Winners) bool { return self.unresolvedWithFont(false); }
    fn unresolvedWithFont(self: Winners, font_size_consumed: bool) bool {
        if (self.selector_unresolved) return true;
        if (self.value(.border)) |border| if (border == .unsupported) return true;
        for (self.slots, 0..) |slot, index| {
            const property: Property = @enumFromInt(index);
            if (property == .margins or marginEdge(property) != null) continue;
            if (slot) |winner| {
                if (winner.value == .unsupported) return true;
                if (property == .font_size and !font_size_consumed) return true;
            }
        }
        return resolvedMargins(self).unresolved;
    }
};


fn marginEdge(property: Property) ?usize {
    return switch (property) { .margin_top => 0, .margin_right => 1, .margin_bottom => 2, .margin_left => 3, else => null };
}
const MarginResolution = struct { value: ?types.StyleEdges = null, automatic: ?types.ContainerMargins = null, unresolved: bool = false };
fn resolvedMargins(winners: Winners) MarginResolution {
    var values: [4]types.ContainerMargin = @splat(.{ .length = .{ .unit = .px, .value = 0 } });
    var seen = false;
    inline for (.{ Property.margin_top, Property.margin_right, Property.margin_bottom, Property.margin_left }, 0..) |property, index| {
        var selected = winners.slots[@backingInt(Property.margins)];
        if (winners.slots[@backingInt(property)]) |edge| {
            if (selected == null or edge.priority.wins(selected.?.priority)) selected = edge;
        }
        if (winners.slots[@backingInt(Property.layout_reset)]) |reset| {
            if (selected == null or reset.priority.wins(selected.?.priority)) selected = reset;
        }
        if (selected) |winner| {
            seen = true;
            switch (winner.value) {
                .length_value => |value| values[index] = .{ .length = value },
                .margin_edge => |value| values[index] = value,
                .margin_values => |edges_value| values[index] = switch (index) { 0 => edges_value.top, 1 => edges_value.right, 2 => edges_value.bottom, 3 => edges_value.left, else => unreachable },
                .edges => |edges_value| values[index] = .{ .length = switch (index) { 0 => edges_value.top, 1 => edges_value.right, 2 => edges_value.bottom, 3 => edges_value.left, else => unreachable } },
                else => return .{ .unresolved = true },
            }
        }
    }
    if (!seen) return .{};
    const selected: types.ContainerMargins = .{ .top = values[0], .right = values[1], .bottom = values[2], .left = values[3] };
    if (values[0] == .auto or values[1] == .auto or values[2] == .auto or values[3] == .auto)
        return if (types.validTableMarginValues(selected)) .{ .automatic = selected } else .{ .unresolved = true };
    return .{ .value = .{ .top = values[0].length, .right = values[1].length,
        .bottom = values[2].length, .left = values[3].length } };
}

// Build-only computed inheritance. Null is unobserved, not a guessed initial
// value. Readers receive the existing concrete TableStyle.collapse enum only.
pub const BorderCollapseState = enum { separate, collapse, unknown };
const BorderCollapseCascade = struct {
    value: ?BorderCollapseState = null,
    priority: Priority = .{},
    seen: bool = false,
    parent: ?BorderCollapseState,

    fn declarations(self: *@This(), a: std.mem.Allocator, css: []const u8, specificity: u64, order: u32, uncertain: bool, inline_style: bool) !void {
        var pos: usize = 0;
        var next_order = order;
        while (try nextDeclarationAlloc(a, css, &pos)) |raw| {
            defer a.free(raw);
            next_order += 1;
            const colon = std.mem.indexOfScalar(u8, raw, ':') orelse continue;
            const name = trim(raw[0..colon]);
            const escaped = std.mem.indexOfScalar(u8, name, '\\') != null;
            const reset = std.ascii.eqlIgnoreCase(name, "all");
            if (!escaped and !reset and !std.ascii.eqlIgnoreCase(name, "border-collapse")) continue;
            const parsed = customPriority(raw[colon + 1 ..]);
            const value = trim(parsed.value);
            if (value.len == 0) continue;
            const selected: BorderCollapseState = if (escaped or parsed.unknown) .unknown
                else if (std.ascii.eqlIgnoreCase(value, "initial")) .separate
                else if (std.ascii.eqlIgnoreCase(value, "inherit") or std.ascii.eqlIgnoreCase(value, "unset")) self.parent orelse .unknown
                else if (!reset and std.ascii.eqlIgnoreCase(value, "collapse")) .collapse
                else if (!reset and std.ascii.eqlIgnoreCase(value, "separate")) .separate
                else if (dynamicValue(value)) .unknown
                else continue;
            const priority: Priority = .{ .important = parsed.important, .specificity = specificity,
                .order = next_order, .inline_style = inline_style };
            if (self.seen and !priority.wins(self.priority)) continue;
            self.seen = true;
            self.priority = priority;
            self.value = if (uncertain) .unknown else selected;
        }
    }
    fn result(self: @This()) ?BorderCollapseState { return if (self.seen) self.value else self.parent; }
};

pub fn hasBorderCollapseDeclarationsAlloc(a: std.mem.Allocator, css: []const u8) std.mem.Allocator.Error!bool {
    if (css.len > max_css_bytes) return false;
    var pos: usize = 0;
    while (try nextDeclarationAlloc(a, css, &pos)) |raw| {
        defer a.free(raw);
        const colon = std.mem.indexOfScalar(u8, raw, ':') orelse continue;
        const name = trim(raw[0..colon]);
        if (std.ascii.eqlIgnoreCase(name, "border-collapse") or std.ascii.eqlIgnoreCase(name, "all") or std.mem.indexOfScalar(u8, name, '\\') != null) return true;
    }
    return false;
}
pub fn resolveInlineBorderCollapseAlloc(a: std.mem.Allocator, css: []const u8, parent: ?BorderCollapseState) std.mem.Allocator.Error!?BorderCollapseState {
    if (css.len > max_css_bytes) return .unknown;
    var cascade_value: BorderCollapseCascade = .{ .parent = parent };
    try cascade_value.declarations(a, css, 0, max_rules * 1024, false, true);
    return cascade_value.result();
}

fn computedTableCollapse(winners: *Winners, value: ?BorderCollapseState) void {
    const selected = value orelse return;
    // The ordinary producer already cascaded this exact table and its parent
    // chain. Keep every other winner/refusal; replace only this computed slot.
    winners.slots[@intFromEnum(Property.collapse)] = .{ .priority = .{}, .value = switch (selected) {
        .separate => .{ .collapse = .separate }, .collapse => .{ .collapse = .collapse }, .unknown => .unsupported,
    } };
}

pub const AlignmentResolution = struct { value: ?types.CellTextAlign = null, specified: bool = false, unresolved: bool = false };
const AlignmentCascade = struct {
    resolution: AlignmentResolution = .{},
    priority: Priority = .{},
    inline_style: bool = false,
    fn consider(self: *AlignmentCascade, declaration: Declaration, specificity: u64, conditional: bool, inline_style: bool) void {
        const next: Priority = .{ .important = declaration.important, .specificity = specificity, .order = declaration.order };
        if (self.resolution.specified) {
            if (next.important == self.priority.important and inline_style != self.inline_style) {
                if (!inline_style) return;
            } else if (!next.wins(self.priority)) return;
        }
        const known = !conditional and declaration.value == .align_value;
        self.* = .{ .resolution = .{ .value = if (known) declaration.value.align_value else null, .specified = true, .unresolved = !known }, .priority = next, .inline_style = inline_style };
    }
    fn declarations(self: *AlignmentCascade, a: std.mem.Allocator, css: []const u8, specificity: u64, order: u32, conditional: bool, inline_style: bool) !void {
        var pos: usize = 0;
        var next_order = order;
        while (try nextDeclarationAlloc(a, css, &pos)) |raw| {
            defer a.free(raw);
            next_order += 1;
            const colon = std.mem.indexOfScalar(u8, raw, ':') orelse continue;
            const name = trim(raw[0..colon]);
            if (std.ascii.eqlIgnoreCase(name, "all") or std.mem.indexOfScalar(u8, name, '\\') != null) {
                if (try declarationAlloc(a, raw, next_order)) |declaration| self.consider(declaration, specificity, true, inline_style);
            } else if (try declarationAlloc(a, raw, next_order)) |declaration| {
                if (declaration.property == .text_align) self.consider(declaration, specificity, conditional, inline_style);
            }
        }
    }
};

pub fn presentationalTextAlign(raw: ?[]const u8) ?types.CellTextAlign {
    const value = trim(raw orelse return null);
    inline for (.{ "left", "center", "right" }, .{ types.CellTextAlign.left, .center, .right }) |name, alignment| if (std.ascii.eqlIgnoreCase(value, name)) return alignment;
    return null;
}
fn emptyProfile(a: std.mem.Allocator) Profile {
    return .{ .arena = std.heap.ArenaAllocator.init(a), .rules = &.{}, .classes = &.{}, .admitted_rule_numbers = &.{}, .has_unsupported_rules = false };
}
// This direct inline API has no inherited custom-property or current-color
// context. Reuse the same background components/cascade as the observed path,
// retaining unknown variables instead of guessing their environment.
// A single bare identifier can only name a color or a background keyword.
// Unsupported compound/function/escaped syntax remains a possible declaration.
fn invalidInlineTableBackgroundIdentifier(a: std.mem.Allocator, raw: []const u8) std.mem.Allocator.Error!bool {
    const value = trim(raw);
    if (value.len == 0) return false;
    for (value) |byte| if (!std.ascii.isAlphabetic(byte)) return false;
    if (try canonicalColorAlloc(a, value) != null or unrepresentedColorValue(value)) return false;
    inline for (.{ "repeat", "space", "round", "scroll", "fixed", "local", "left", "center", "right", "top", "bottom", "text", "contain", "cover", "normal",
        // Deprecated system colors remain valid CSS, with contextual paint.
        "activeborder", "activecaption", "appworkspace", "background", "buttonhighlight", "buttonshadow", "captiontext", "inactiveborder", "inactivecaption", "inactivecaptiontext", "infobackground", "infotext", "menu", "menutext", "scrollbar", "threeddarkshadow", "threedface", "threedhighlight", "threedlightshadow", "threedshadow", "window", "windowframe", "windowtext" }) |keyword|
        if (std.ascii.eqlIgnoreCase(value, keyword)) return false;
    return true;
}

fn inlineTableNoImageBackground(a: std.mem.Allocator, css: []const u8) std.mem.Allocator.Error!ObservedFigureColor {
    var scratch = std.heap.ArenaAllocator.init(a); defer scratch.deinit();
    const temporary = scratch.allocator();
    var declarations: std.ArrayList(ObservedFigureDeclaration) = .empty;
    appendObservedFigureDeclarations(temporary, &declarations, css,
        .{ .inline_style = true, .order = max_rules * 1024 }, false, false, null, 0) catch |err| switch (err) {
        error.OutOfMemory => return error.OutOfMemory,
        error.StyleProfileLimit => return .{ .unresolved = true },
    };
    // Invalid declarations do not enter the cascade or erase an earlier
    // color. Preserve unsupported valid syntax and every non-background field.
    var retained: usize = 0;
    for (declarations.items) |declaration| {
        if (!declaration.syntax_unknown and std.ascii.eqlIgnoreCase(declaration.name, "background") and
            try invalidInlineTableBackgroundIdentifier(temporary, declaration.raw)) continue;
        declarations.items[retained] = declaration;
        retained += 1;
    }
    declarations.items.len = retained;
    var resolved = try observedTableNoImageBackground(temporary, declarations.items, .{ .complete = false }, null, null);
    // No scratch color slice may escape into the caller's published style.
    if (resolved.value) |*paint| {
        if (paint.value) |color| paint.value = try a.dupe(u8, color);
    }
    return resolved;
}

pub fn resolveInlineTableAlloc(a: std.mem.Allocator, css: []const u8) !TableResolution {
    return resolveInlineTableWithCollapseAlloc(a, css, null);
}
pub fn resolveInlineTableWithCollapseAlloc(a: std.mem.Allocator, css: []const u8, collapse: ?BorderCollapseState) !TableResolution {
    return resolveInlineTableWithLegacyBorderAlloc(a, css, collapse, null);
}
pub fn resolveInlineTableWithLegacyBorderAlloc(a: std.mem.Allocator, css: []const u8, collapse: ?BorderCollapseState, legacy_border: ?u16) !TableResolution {
    return resolveInlineTableWithLegacyBorderBasisAlloc(a, css, collapse, legacy_border, null);
}
// The basis is the complete native legacy border for this TABLE owner only.
// Null retains the conservative historical path. This does not authorize a
// profile-backed, floating, inline, viewport, or rounded TABLE conversion.
pub fn resolveInlineTableWithLegacyBorderBasisAlloc(a: std.mem.Allocator, css: []const u8, collapse: ?BorderCollapseState, legacy_border: ?u16, legacy_basis: ?types.ResolvedStyleBorderEdges) !TableResolution {
    if (css.len > max_css_bytes) return .{ .style = null, .scope = 0, .unresolved = true, .margin_basis_unresolved = true };
    const profile = emptyProfile(a);
    var winners = try profile.cascade(a, .table, 0, 0, "", .{ .ancestor_classes = "", .own_id = "" }, null, null, css);
    const use_legacy_basis = legacy_basis != null and (legacy_border orelse 0) > 0 and inlineBorderMissingLine(winners.borders);
    // A positive legacy border has a separate reader geometry contract. A
    // partial CSS declaration cannot replace its absent line-style components
    // with CSS initial none. Preserve that unresolved origin without guessing
    // its style, width, color, or the cell borders it supplies.
    if (!use_legacy_basis and (legacy_border orelse 0) > 0 and winners.borders.seen) {
        for (0..4) |side| {
            const index = side * 3 + 1;
            if (winners.borders.atoms[index] == null)
                winners.borders.atoms[index] = .{ .atom = .unknown, .priority = .{} };
        }
    }
    computedTableCollapse(&winners, collapse);
    const background = try inlineTableNoImageBackground(a, css);
    if (winners.slots[@intFromEnum(Property.background)]) |*winner| {
        // The legacy flat slot cannot distinguish color from image/clip/blend.
        // Replace only its final projection after the independent component
        // cascade; keep all priorities and every non-background winner intact.
        winner.value = if (background.unresolved or background.value == null) .unsupported
            else if (background.value.?.kind == .rgb) .{ .color = background.value.?.value.? }
            else if (background.value.?.kind == .transparent) .no_background else .unsupported;
    }
    const margins = resolvedMargins(winners);
    var style: types.TableStyle = .{ .margins = margins.value, .margin_values = margins.automatic };
    var unresolved = margins.unresolved or background.unresolved or background.value == null;
    if (winners.value(.float_side)) |value| {
        if (value == .float_value) style.float_side = value.float_value;
        unresolved = unresolved or value == .unsupported;
    }
    projectTableBox(&style, winners);
    if (use_legacy_basis) {
        // This source-only component is confined to ordinary direct TABLEs.
        // Other geometry and any reset/unknown authority retain refusal.
        const ordinary = (style.display == null or style.display == .table) and style.float_side == null and
            winners.value(.corner_radii) == null and winners.value(.layout_reset) == null and winners.value(.other) == null;
        const border = if (ordinary) inlineBorderWithLegacyBasis(winners.borders, legacy_basis.?)
            else InlineLegacyBorderResolution{ .unresolved = true };
        style.border = border.value;
        unresolved = unresolved or border.unresolved;
    }
    inline for (.{ Property.background, .border, .width, .min_width, .padding, .clear, .box_sizing, .collapse, .display, .vertical_align, .line_height, .list_style }) |property| if (winners.value(property)) |value| {
        if (property != .border or !use_legacy_basis) unresolved = unresolved or value == .unsupported;
    };
    const corner_conflict = projectTableCorners(&style, winners);
    const flow_conflict = tableFlowFloatConflict(&style);
    const valid_style = types.validUnboundTableStyle(style);
    const final_unresolved = unresolved or flow_conflict or corner_conflict or (use_legacy_basis and !valid_style);
    return .{ .resolved_legacy_border = use_legacy_basis and !final_unresolved, .style = if (valid_style) style else null, .scope = 0, .unresolved = final_unresolved, .margin_basis_unresolved = winners.font_basis_unresolved, .width_specified = winners.value(.width) != null or unresolvedTableWidthBox(winners), .line_height_em = selectedLineHeight(winners) };
}
fn addCellWidthHint(winners: *Winners, raw: ?[]const u8) void {
    const value = raw orelse return;
    // HTML dimension hints use unsigned decimal lengths or percentages.
    // Keep other spellings unresolved rather than applying CSS number syntax.
    var parsed: Value = .unsupported;
    if (value.len != 0 and value.len <= 64) {
        const percent = value[value.len - 1] == '%';
        const digits = if (percent) value[0 .. value.len - 1] else value;
        if (digits.len != 0 and std.ascii.isDigit(digits[0]) and
            std.mem.indexOfAny(u8, digits, "eE") == null and widthNumberSyntax(digits))
        {
            const number: ?f32 = std.fmt.parseFloat(f32, digits) catch null;
            if (number) |scalar| {
                // HTML cell dimension hints ignore zero. This does not apply
                // to a real CSS width:0 winner, which remains present data.
                if (scalar == 0 and widthNumberIsZero(digits)) return;
                const width: types.StyleWidth = .{ .unit = if (percent) .percent else .px, .value = scalar };
                if (types.validStyleWidth(width)) parsed = .{ .width_value = width };
            }
        }
    }
    winners.add(.{ .property = .width, .value = parsed, .important = false, .order = 0 }, 0, false, false);
}
fn selectedCellWidth(winners: Winners) ?types.StyleWidth {
    if (winners.value(.box_sizing) != null) return null;
    const value = winners.value(.width) orelse return null;
    return if (value == .width_value) value.width_value else null;
}
fn cellWidthUnresolved(winners: Winners) bool {
    const value = winners.value(.width) orelse return false;
    return switch (value) { .auto_width => false, .width_value => winners.value(.box_sizing) != null, else => true };
}

fn addCellVerticalHint(winners: *Winners, raw: ?[]const u8) void {
    const value = raw orelse return;
    const alignment: Value = if (std.ascii.eqlIgnoreCase(value, "top"))
        .{ .cell_vertical_align_value = .top } else .unsupported;
    winners.add(.{ .property = .vertical_align, .value = alignment, .important = false, .order = 0 }, 0, false, false);
}

pub fn resolveInlineCellAlloc(a: std.mem.Allocator, legacy_align: ?[]const u8, css: []const u8) !CellResolution {
    return resolveInlineCellWithVerticalHintAlloc(a, legacy_align, null, css);
}
pub fn resolveInlineCellWithVerticalHintAlloc(a: std.mem.Allocator, legacy_align: ?[]const u8, legacy_vertical_align: ?[]const u8, css: []const u8) !CellResolution {
    return resolveInlineCellWithLegacyHintsAlloc(a, legacy_align, legacy_vertical_align, null, css);
}
pub fn resolveInlineCellWithLegacyHintsAlloc(a: std.mem.Allocator, legacy_align: ?[]const u8, legacy_vertical_align: ?[]const u8, legacy_width: ?[]const u8, css: []const u8) !CellResolution {
    return resolveInlineCellWithLegacyBorderBasisAlloc(a, legacy_align, legacy_vertical_align, legacy_width, css, null);
}
// Only the owning Compiler's selected ordinary TABLE scope supplies a CELL
// basis. It belongs to this cell (including its paint owner), never its TABLE.
pub fn resolveInlineCellWithLegacyBorderBasisAlloc(a: std.mem.Allocator, legacy_align: ?[]const u8, legacy_vertical_align: ?[]const u8, legacy_width: ?[]const u8, css: []const u8, legacy_basis: ?types.ResolvedStyleBorderEdges) !CellResolution {
    const profile = emptyProfile(a);
    const alignment = try profile.resolveAlignment(a, "", "", "", legacy_align, css);
    if (css.len > max_css_bytes) return .{ .style = null, .background = null, .background_specified = false, .unresolved = true, .alignment_specified = alignment.specified };
    // Null-basis callers retain the historical alignment/width-only path.
    // In the selected scope, collect border components in this same pass.
    var winners: Winners = .{};
    addCellVerticalHint(&winners, legacy_vertical_align);
    addCellWidthHint(&winners, legacy_width);
    var pos: usize = 0;
    var order: u32 = 0;
    var border_context_unknown = false;
    while (try nextDeclarationAlloc(a, css, &pos)) |raw| {
        defer a.free(raw);
        order += 1;
        const colon = std.mem.indexOfScalar(u8, raw, ':') orelse continue;
        const name = trim(raw[0..colon]);
        const property = propertyFor(name) orelse continue;
        const escaped = std.mem.indexOfScalar(u8, name, '\\') != null;
        if (legacy_basis != null and (property == .layout_reset or property == .corner_radii or property == .other or property == .display or property == .float_side or property == .clear or escaped)) border_context_unknown = true;
        if (property != .width and property != .min_width and property != .box_sizing and property != .layout_reset and property != .vertical_align and property != .line_height and property != .cell_opacity and !(legacy_basis != null and property == .border) and !escaped) continue;
        if (try declarationAlloc(a, raw, order)) |declaration| if (try cellLineHeightDeclarationAlloc(a, declaration, .cell, null)) |selected| winners.add(selected, 0, !representedDeclaration(.cell, selected), true);
    }
    const minimum = winners.value(.min_width);
    const minimum_unknown = if (minimum) |value| value != .length_value or winners.value(.box_sizing) != null else false;
    var style: types.CellStyle = .{ .text_align = alignment.value, .min_width = selectedCellMinimumWidth(winners), .width = selectedCellWidth(winners) };
    if (winners.value(.vertical_align)) |value| if (value == .cell_vertical_align_value) { style.vertical_align = value.cell_vertical_align_value; };
    if (winners.value(.cell_opacity)) |value| if (value == .opacity) { style.opacity = value.opacity; };
    const opacity_unknown = if (winners.value(.cell_opacity)) |value| value != .opacity else false;
    const vertical_unknown = if (winners.value(.vertical_align)) |value| value != .cell_vertical_align_value else false;
    var border_unknown = false;
    if (legacy_basis) |basis| {
        const border = if (!border_context_unknown) inlineBorderWithLegacyBasis(winners.borders, basis)
            else InlineLegacyBorderResolution{ .unresolved = true };
        style.border = border.value;
        border_unknown = border.unresolved;
    }
    const valid_style = types.validCellStyle(style);
    return .{ .style = if (valid_style) style else null, .background = null, .background_specified = false, .unresolved = alignment.unresolved or minimum_unknown or vertical_unknown or opacity_unknown or cellWidthUnresolved(winners) or border_unknown or (legacy_basis != null and !valid_style) or (if (winners.value(.line_height)) |height| height != .cell_line_height else false), .alignment_specified = alignment.specified, .line_height = selectedCellLineHeight(winners) };
}
pub fn resolveInlineAlignmentAlloc(a: std.mem.Allocator, legacy_align: ?[]const u8, css: []const u8) !AlignmentResolution {
    const profile = emptyProfile(a);
    return profile.resolveAlignment(a, "", "", "", legacy_align, css);
}

pub const FontSizeValue = union(enum) {
    inherit,
    absolute: f32,
    relative: f32,
    step: @import("font_scale.zig").RelativeKeyword,
    unknown,
};

pub const ObservedFontSizeValue = union(enum) {
    inherit,
    absolute: f32,
    css_px: f32,
    root_relative: f32,
    relative: f32,
    step: @import("font_scale.zig").RelativeKeyword,
    unknown,
};

fn fontSizeValue(property: []const u8, raw: []const u8) ?FontSizeValue {
    return fontSizeValueIn(false, property, raw);
}

fn fontSizeValueIn(comptime observed_lengths: bool, property: []const u8, raw: []const u8) ?(if (observed_lengths) ObservedFontSizeValue else FontSizeValue) {
    const value = trim(raw);
    if (std.ascii.eqlIgnoreCase(value, "inherit") or std.ascii.eqlIgnoreCase(value, "unset")) return .inherit;
    if (std.ascii.eqlIgnoreCase(value, "initial")) return .{ .absolute = 1 };
    if (!std.ascii.eqlIgnoreCase(property, "font-size")) return if (value.len != 0) .unknown else null;
    const font = @import("font_scale.zig");
    if (observed_lengths) {
        if (font.parseCssPixels(value)) |pixels| return .{ .css_px = pixels };
    }
    if (font.absoluteKeyword(value)) |size| return .{ .absolute = size };
    if (font.relativeKeyword(value)) |step| return .{ .step = step };
    if (font.parseRelative(value)) |factor| return .{ .relative = factor };
    if (observed_lengths) {
        if (value.len > 3 and std.ascii.endsWithIgnoreCase(value, "rem")) {
            const number = value[0 .. value.len - 3];
            if (widthNumberSyntax(number)) {
                if (widthNumberIsZero(number)) return .{ .root_relative = 0 };
                if (number[0] == '-') return null;
                const parsed = std.fmt.parseFloat(f64, number) catch return .unknown;
                if (parsed < 0) return null;
                if (!std.math.isFinite(parsed) or parsed == 0 or parsed > std.math.floatMax(f32)) return .unknown;
                const factor: f32 = @floatCast(parsed);
                if (factor == 0) return .unknown;
                return .{ .root_relative = factor };
            }
        }
    }
    if (std.ascii.eqlIgnoreCase(value, "revert") or std.ascii.eqlIgnoreCase(value, "revert-layer") or
        std.mem.indexOfScalar(u8, value, '(') != null or std.mem.indexOfScalar(u8, value, '\\') != null) return .unknown;
    // Valid but unsupported lengths must invalidate parent authority. Invalid
    // identifiers/negative lengths do not replace a valid earlier declaration.
    for ([_][]const u8{ "px", "pt", "pc", "in", "cm", "mm", "q", "rem", "ex", "ch", "cap", "ic", "lh", "rlh", "vw", "vh", "vi", "vb", "vmin", "vmax", "svw", "svh", "lvw", "lvh", "dvw", "dvh" }) |unit| {
        if (value.len > unit.len and std.ascii.eqlIgnoreCase(value[value.len - unit.len ..], unit)) {
            const number = value[0 .. value.len - unit.len];
            if (observed_lengths and std.ascii.eqlIgnoreCase(unit, "px") and widthNumberSyntax(number) and
                (number.len == 0 or number[0] != '-')) return .unknown;
            const size = std.fmt.parseFloat(f64, number) catch continue;
            if (std.math.isFinite(size) and size >= 0) return .unknown;
        }
    }
    return null;
}

const FontCascade = FontCascadeFor(false);

fn FontCascadeFor(comptime observed_lengths: bool) type {
    return struct {
        const Self = @This();
        const ValueType = if (observed_lengths) ObservedFontSizeValue else FontSizeValue;
    value: ?ValueType = null,
    priority: Priority = .{},
    fn declarations(self: *Self, a: std.mem.Allocator, css: []const u8, specificity: u64, order: u32, uncertain: bool, inline_style: bool) !void {
        var pos: usize = 0;
        var next_order = order;
        while (try nextDeclarationAlloc(a, css, &pos)) |raw| {
            defer a.free(raw);
            next_order += 1;
            const colon = std.mem.indexOfScalar(u8, raw, ':') orelse continue;
            const property = trim(raw[0..colon]);
            const escaped = std.mem.indexOfScalar(u8, property, '\\') != null;
            if (!escaped and !std.ascii.eqlIgnoreCase(property, "font-size") and !std.ascii.eqlIgnoreCase(property, "font") and !std.ascii.eqlIgnoreCase(property, "all")) continue;
            const parsed_priority = customPriority(raw[colon + 1 ..]);
            const selected = if (escaped or parsed_priority.unknown) ValueType.unknown else fontSizeValueIn(observed_lengths, property, parsed_priority.value) orelse continue;
            const next: Priority = .{ .important = parsed_priority.important, .specificity = specificity, .order = next_order, .inline_style = inline_style };
            if (self.value != null and !next.wins(self.priority)) continue;
            self.value = if (uncertain) .unknown else selected;
            self.priority = next;
        }
    }
};
}

pub fn resolveInlineFontSizeAlloc(a: std.mem.Allocator, css: []const u8) !?FontSizeValue {
    if (css.len > max_css_bytes) return .unknown;
    var cascade_value: FontCascade = .{};
    try cascade_value.declarations(a, css, 0, max_rules * 1024, false, true);
    return cascade_value.value;
}

pub fn resolveObservedCellInlineFontSizeAlloc(a: std.mem.Allocator, css: []const u8) !?ObservedFontSizeValue {
    if (css.len > max_css_bytes) return .unknown;
    var cascade_value: FontCascadeFor(true) = .{};
    try cascade_value.declarations(a, css, 0, max_rules * 1024, false, true);
    return cascade_value.value;
}

// Build-only identity and lifetime of a source-bound class inventory.
pub const SourceRootTableProof = struct { opening_start: usize, opening_end: usize, anchor_start: usize, anchor_end: usize, cell_ordinal: usize };
// A closed ordinary opening plus its literal bold-label operation has the
// same complete candidate census in the observed DOM. This issues no mapping,
// physical parent, ordinal, or sibling fact.
pub const SourceCustomElementProof = struct { range: SourceRootChildProof, candidate_count: u32 };

pub const ClosedReadyFigureProof = struct {
    styles: *const Profile,
    source: []const u8,
    root: *const TextElement,
    operations: usize,
};
pub const ClosedMissingFigureProof = struct {
    styles: *const Profile,
    source: []const u8,
    root: *const TextElement,
    operations: usize,
};

pub const EmptyMissingCaptionOperation = struct { start: usize, end: usize };

pub const EmptyMissingFigureCaptionProof = struct {
    styles: *const Profile,
    source: []const u8,
    root: *const TextElement,
    operations: []const EmptyMissingCaptionOperation,
};

// A complete ordinary source-link label is text, not an attribute-name input.
// The Book additionally qualifies every token through the ordinary destination
// resolver; the consuming census replays these bounded source offsets.
pub const SourcePlainLinkLabel = struct { start: usize, end: usize, label_start: usize, label_end: usize };
pub const SourcePlainLinkLabelNamespace = struct {
    catalog: *const @import("namespace_registry").Registry,
    sha256: [32]u8,
};
pub const SourcePlainLinkLabels = struct {
    source: []const u8,
    namespace_catalog: *const @import("namespace_registry").Registry,
    namespace_sha256: [32]u8,
    interwiki_rows: @FieldType(@import("namespace_registry").Registry, "interwiki_rows"),
    interwiki_magic: ?bool,
    labels: []const SourcePlainLinkLabel,
};

fn sourcePlainLinkLabelNamespaceMatches(labels: ?*const SourcePlainLinkLabels, identity: ?SourcePlainLinkLabelNamespace) bool {
    const proof = labels orelse return identity == null;
    const selected = identity orelse return false;
    return selected.catalog == proof.namespace_catalog and std.mem.eql(u8, &selected.sha256, &proof.namespace_sha256);
}

fn sourcePlainLabelEntityText(raw: []const u8) bool {
    if (raw.len == 0 or raw.len > 4096 or std.mem.indexOfAny(u8, raw, "<>[]{}|='\"\\\r\n\t\x00") != null) return false;
    var at: usize = 0;
    while (at < raw.len) : (at += 1) {
        if (raw[at] != '&') continue;
        const limit = at + @min(raw.len - at, 66);
        const relative = std.mem.indexOfScalar(u8, raw[at + 1..limit], ';') orelse return false;
        const end = at + 1 + relative;
        const name = raw[at + 1..end];
        if (name.len == 0) return false;
        if (name[0] == '#') {
            const hex = name.len > 1 and (name[1] == 'x' or name[1] == 'X');
            const digits = name[if (hex) @as(usize, 2) else 1..];
            const cp = std.fmt.parseInt(u21, digits, if (hex) 16 else 10) catch return false;
            if (cp == 0 or cp == 0xfffd or cp > 0x10ffff or (cp >= 0xd800 and cp <= 0xdfff) or
                (cp < 128 and (cp < 0x20 or std.mem.indexOfScalar(u8, "<>[]{}|='\"\\", @intCast(cp)) != null))) return false;
        } else {
            const decoded = @import("shared_xml_decode").html_entities.lookupHtmlNamedEntity(name) orelse return false;
            for (decoded) |byte| if (byte < 0x20 or std.mem.indexOfScalar(u8, "<>[]{}|='\"\\", byte) != null) return false;
        }
        at = end;
    }
    return true;
}

// Cell delimiters run before inline links. Only an attributed physical cell's
// actual body may lend this role; its attribute prefix remains outside the map.
fn sourcePlainLabelWikiCellBody(source: []const u8, start: usize, end: usize) bool {
    const syntax = @import("blob_encoder").wikitext_syntax;
    const line_start = if (std.mem.lastIndexOfScalar(u8, source[0..start], '\n')) |at| at + 1 else 0;
    const line_end = std.mem.indexOfScalarPos(u8, source, start, '\n') orelse source.len;
    const line = std.mem.trim(u8, source[line_start..line_end], " \t\r\n");
    if (line.len == 0 or (line[0] != '|' and line[0] != '!')) return true;
    if (std.mem.startsWith(u8, line, "|-") or std.mem.startsWith(u8, line, "|+") or std.mem.startsWith(u8, line, "|}")) return false;
    const relative_start = start - (@intFromPtr(line.ptr) - @intFromPtr(source.ptr));
    const relative_end = end - (@intFromPtr(line.ptr) - @intFromPtr(source.ptr));
    const header = line[0] == '!';
    var offset: usize = 1;
    var scan: syntax.OpaqueScan = .{};
    var no_more_close = false;
    while (offset <= line.len) {
        const split_at = if (header)
            @min(syntax.wikiCellDelimiterWithScan(line, "!!", offset, &scan, &no_more_close) orelse line.len,
                syntax.wikiCellDelimiterWithScan(line, "||", offset, &scan, &no_more_close) orelse line.len)
        else syntax.wikiCellDelimiterWithScan(line, "||", offset, &scan, &no_more_close) orelse line.len;
        if (relative_start >= offset and relative_start < split_at) {
            if (relative_end > split_at) return false;
            const raw = line[offset..split_at];
            const pipe = syntax.cellAttributePipe(raw) orelse return false;
            // Preserve the previous refusal for token-looking attribute input,
            // including the ordinary parser's no-attributes fallback at [[.
            if (std.mem.indexOfAny(u8, raw[0..pipe], "[]{}<>\r\n\x00") != null) return false;
            var quote: ?u8 = null;
            for (raw[0..pipe]) |byte| {
                if (quote) |held| { if (byte == held) quote = null; }
                else if (byte == '\'' or byte == '"') quote = byte;
            }
            if (quote != null) return false;
            return relative_start >= offset + pipe + 1;
        }
        if (split_at == line.len) break;
        offset = split_at + 2;
    }
    return false;
}

// This scanner reuses source token/tag boundaries, not returned-HTML boundaries.
// It never qualifies link-looking bytes in a tag, opaque body, comment or wiki
// table attribute line. Unsupported boundaries stop further label issuance.
pub fn nextSourcePlainLinkLabel(source: []const u8, ns: *const @import("namespace_registry").Registry,
    cursor: *usize) ?SourcePlainLinkLabel
{
    const syntax = @import("blob_encoder").wikitext_syntax;
    const ir = @import("blob_encoder").document_ir;
    if (source.len > 4 * 1024 * 1024) { cursor.* = source.len; return null; }
    while (cursor.* < source.len) {
        const at = cursor.*;
        if (at == 0 or source[at - 1] == '\n') {
            const end = std.mem.indexOfScalarPos(u8, source, at, '\n') orelse source.len;
            const line = std.mem.trimStart(u8, source[at..end], " \t");
            if (std.mem.startsWith(u8, line, "{|") or std.mem.startsWith(u8, line, "|-") or
                std.mem.startsWith(u8, line, "|+") or std.mem.startsWith(u8, line, "|}")) {
                cursor.* = if (end < source.len) end + 1 else end; continue;
            }
        }
        if (std.mem.startsWith(u8, source[at..], "<!--")) {
            const end = std.mem.indexOfPos(u8, source, at + 4, "-->") orelse { cursor.* = source.len + 1; return null; };
            cursor.* = end + 3; continue;
        }
        if (source[at] == '<') {
            const tag = syntax.tagAt(source, at) orelse { cursor.* = source.len + 1; return null; };
            // Do not publish a later text role after an unfinished attribute
            // quote, even though the source tokenizer ends at the first '>'.
            var quote: ?u8 = null;
            for (tag.attrs) |byte| {
                if (quote) |held| { if (byte == held) quote = null; }
                else if (byte == '\'' or byte == '"') quote = byte;
            }
            if (quote != null) { cursor.* = source.len + 1; return null; }
            if (!tag.closing and (syntax.isOpaqueTag(tag.name) or tag.is("style") or tag.is("script") or tag.is("textarea") or tag.is("title") or
                tag.is("includeonly") or tag.is("a") or tag.is("select") or tag.is("option") or tag.is("button") or tag.is("form") or tag.is("iframe") or tag.is("xmp") or tag.is("plaintext"))) {
                cursor.* = if (tag.self_closing) tag.end else (syntax.matchingTag(source, tag) orelse { cursor.* = source.len + 1; return null; }).end;
            } else cursor.* = tag.end;
            continue;
        }
        if (source[at] == '[' and !std.mem.startsWith(u8, source[at..], "[[") and ir.hasExternalProtocol(source[at + 1..])) {
            var external_iterator: ir.InlineIterator = .{ .input = source, .cursor = at, .renderer_boundaries = true };
            const external = external_iterator.next() orelse { cursor.* = source.len + 1; return null; };
            if (external.kind != .external_link or external_iterator.cursor <= at or external_iterator.cursor > source.len) {
                cursor.* = source.len + 1; return null;
            }
            // Its URL and complete label belong to the external producer. An
            // internal-looking child cannot borrow this ordinary source-A role.
            cursor.* = external_iterator.cursor; continue;
        }
        if (ir.doubleOpeningExternalToken(source, at)) {
            var external_iterator: ir.InlineIterator = .{ .input = source, .cursor = at + 1, .renderer_boundaries = true };
            const external = external_iterator.next() orelse { cursor.* = source.len + 1; return null; };
            if (external.kind != .external_link or external_iterator.cursor <= at + 1 or external_iterator.cursor > source.len) {
                cursor.* = source.len + 1; return null;
            }
            cursor.* = external_iterator.cursor; continue;
        }
        if (ir.hasExternalProtocol(source[at..])) {
            var external_iterator: ir.InlineIterator = .{ .input = source, .cursor = at, .renderer_boundaries = true };
            if (external_iterator.next()) |external| {
                if (external.kind == .external_link and external.target.ptr == source[at..].ptr and
                    external_iterator.cursor > at and external_iterator.cursor <= source.len) {
                    cursor.* = external_iterator.cursor; continue;
                }
                if (external.kind == .text and external.text.ptr == source[at..].ptr and
                    external_iterator.cursor > at and external_iterator.cursor <= source.len) {
                    // A refused free protocol remains the maintained text
                    // token; do not rescan its whole suffix at every byte.
                    cursor.* = external_iterator.cursor; continue;
                }
            }
        }
        if (!std.mem.startsWith(u8, source[at..], "[[")) { cursor.* += 1; continue; }
        const pair = syntax.balanced(source, at) orelse { cursor.* = source.len + 1; return null; };
        cursor.* = pair.end;
        if (pair.end - at > 8192) continue;
        var iterator: ir.InlineIterator = .{ .input = source[at..pair.end], .renderer_boundaries = true };
        const node = iterator.next() orelse continue;
        if (node.kind != .link or !node.link_has_pipe or node.link_empty_label or node.link_label_restored_close or
            node.trail.len != 0 or iterator.cursor != pair.end - at or node.target.len == 0 or
            std.mem.trim(u8, node.target, " \t\r\n").len != node.target.len or
            std.mem.indexOfAny(u8, node.target, "<>[]{}|&%#'\"\\\r\n\t\x00") != null or
            node.target.ptr != source[at + 2..].ptr or at + 2 + node.target.len >= pair.inner_end or
            source[at + 2 + node.target.len] != '|' or
            node.text.ptr != source[at + 3 + node.target.len..].ptr or
            node.text.len != pair.inner_end - (at + 3 + node.target.len) or
            std.mem.indexOfScalar(u8, node.text, '&') == null or !sourcePlainLabelEntityText(node.text)) continue;
        // No File/Media/Category option or metadata token receives a text role.
        const title = if (node.target[0] == ':') node.target[1..] else node.target;
        if (title.len == 0 or title[0] == ':') continue;
        const id = ns.ofTitle(title).id;
        if (id < 0 or id == 6 or id == 14) continue;
        if (std.mem.indexOfScalar(u8, title, ':')) |colon| {
            if (std.mem.trim(u8, title[0..colon], " \t").len != colon) continue;
            var special = false;
            for (ns.interwiki_rows) |row| if (std.ascii.eqlIgnoreCase(row.prefix, title[0..colon]) and (row.is_interlanguage or row.is_current_wiki)) { special = true; break; };
            if (special) continue;
        }
        if (!sourcePlainLabelWikiCellBody(source, at, pair.end)) continue;
        return .{ .start = at, .end = pair.end, .label_start = at + 3 + node.target.len, .label_end = pair.inner_end };
    }
    return null;
}

pub fn sourcePlainLinkLabelsCurrent(proof: *const SourcePlainLinkLabels, source: []const u8) bool {
    if (source.len == 0 or source.len > 4 * 1024 * 1024 or !std.unicode.utf8ValidateSlice(source) or std.mem.indexOfScalar(u8, source, 0) != null or
        proof.source.ptr != source.ptr or proof.source.len != source.len or proof.labels.len == 0 or proof.labels.len > 64 or
        !std.mem.eql(u8, &proof.namespace_sha256, &proof.namespace_catalog.source_sha256) or
        proof.interwiki_rows.ptr != proof.namespace_catalog.interwiki_rows.ptr or proof.interwiki_rows.len != proof.namespace_catalog.interwiki_rows.len or
        proof.interwiki_magic != proof.namespace_catalog.interwiki_magic) return false;
    var cursor: usize = 0;
    for (proof.labels) |expected| {
        const actual = nextSourcePlainLinkLabel(source, proof.namespace_catalog, &cursor) orelse return false;
        if (!std.meta.eql(actual, expected)) return false;
    }
    return nextSourcePlainLinkLabel(source, proof.namespace_catalog, &cursor) == null and cursor <= source.len;
}

pub const RowColorOwner = struct { attrs_start: usize, attrs_end: usize };
pub const ClosedRowColorProof = struct {
    plain_link_labels: ?*const SourcePlainLinkLabels = null,
    plain_link_namespace: ?SourcePlainLinkLabelNamespace = null,
    // Only the complete zero-owner variant owns this immutable source snapshot.
    // Ordinary positive-owner proofs keep their existing consumption obligation.
    absent_source: ?[]const u8 = null,
    styles: *const Profile, source: []const u8, root: *const TextElement,
    attribute: []const u8, owners: []const RowColorOwner,
};

pub const RowColorAbsenceValidationCounts = struct {
    validation_calls: u64 = 0, validation_input_bytes: u64 = 0,
    snapshot_comparison_calls: u64 = 0, snapshot_input_bytes: u64 = 0,
    lexical_calls: u64 = 0, lexical_input_bytes: u64 = 0,
};
// Only the explicitly opted-in whole-Mai test enables these counters. Normal
// products have no counter state or atomic operations after comptime pruning.
const RowColorAbsenceTraceState = if (@import("builtin").is_test) struct {
    var enabled: std.atomic.Value(bool) = .init(false);
    var validation_calls: std.atomic.Value(u64) = .init(0);
    var validation_input_bytes: std.atomic.Value(u64) = .init(0);
    var snapshot_comparison_calls: std.atomic.Value(u64) = .init(0);
    var snapshot_input_bytes: std.atomic.Value(u64) = .init(0);
    var lexical_calls: std.atomic.Value(u64) = .init(0);
    var lexical_input_bytes: std.atomic.Value(u64) = .init(0);
} else struct {};

pub fn rowColorAbsenceValidationTrace(enabled: bool) void {
    if (comptime @import("builtin").is_test) {
        RowColorAbsenceTraceState.enabled.store(false, .monotonic);
        inline for (@typeInfo(RowColorAbsenceValidationCounts).@"struct".field_names) |name|
            @field(RowColorAbsenceTraceState, name).store(0, .monotonic);
        RowColorAbsenceTraceState.enabled.store(enabled, .monotonic);
    }
}
pub fn rowColorAbsenceValidationCounts() RowColorAbsenceValidationCounts {
    if (comptime @import("builtin").is_test) {
        var result: RowColorAbsenceValidationCounts = .{};
        inline for (@typeInfo(RowColorAbsenceValidationCounts).@"struct".field_names) |name|
            @field(result, name) = @field(RowColorAbsenceTraceState, name).load(.monotonic);
        return result;
    }
    return .{};
}

// A deliberately negative lexical census, not a new source renderer. Keep
// encoded ASCII-name construction and unresolved inclusion/conversion opaque.
// Named references use the maintained HTML entity table; numeric references use
// the same std integer grammar as the source attribute decoder.
pub fn rowColorSourceAbsent(source: []const u8) bool {
    return rowColorSourceAbsentWithLabels(source, null);
}

pub fn rowColorSourceAbsentWithLabels(source: []const u8, labels: ?*const SourcePlainLinkLabels) bool {
    if (comptime @import("builtin").is_test) if (RowColorAbsenceTraceState.enabled.load(.monotonic)) {
        _ = RowColorAbsenceTraceState.lexical_calls.fetchAdd(1, .monotonic);
        _ = RowColorAbsenceTraceState.lexical_input_bytes.fetchAdd(@intCast(source.len), .monotonic);
    };
    return sourceAttributeNameConstructionClosedWithLabels(source, "bgcolor", labels);
}

fn sourceAttributeNameConstructionClosed(source: []const u8, comptime forbidden_attribute: ?[]const u8) bool {
    return sourceAttributeNameConstructionClosedWithLabels(source, forbidden_attribute, null);
}
fn sourceAttributeNameConstructionClosedWithLabels(source: []const u8, comptime forbidden_attribute: ?[]const u8,
    labels: ?*const SourcePlainLinkLabels) bool
{
    if (labels) |proof| if (!sourcePlainLinkLabelsCurrent(proof, source)) return false;
    if (source.len == 0 or source.len > 4 * 1024 * 1024 or !std.unicode.utf8ValidateSlice(source) or
        std.mem.indexOfScalar(u8, source, 0) != null or std.mem.indexOf(u8, source, "{{") != null or
        std.mem.indexOf(u8, source, "}}") != null or std.mem.indexOf(u8, source, "-{") != null) return false;
    var at: usize = 0;
    while (at < source.len) : (at += 1) {
        if (forbidden_attribute) |name| if (source.len - at >= name.len and
            std.ascii.eqlIgnoreCase(source[at..][0..name.len], name)) return false;
        if (source[at] != '&' or at + 1 == source.len) continue;
        if (labels) |proof| {
            var text_label = false;
            for (proof.labels) |label| if (at >= label.label_start and at < label.label_end) { text_label = true; break; };
            if (text_label) continue;
        }
        // Every ampersand examines at most a supported 64-byte name plus
        // its terminator. Bare ampersands never rescan the remaining source.
        const look_end = at + @min(source.len - at, 66);
        const relative_end = std.mem.indexOfScalar(u8, source[at + 1..look_end], ';') orelse {
            if (source[at + 1] == '#') return false;
            continue;
        };
        const end = at + 1 + relative_end;
        if (source[at + 1] == '#') {
            const raw = source[at + 2..end];
            const hex = raw.len != 0 and (raw[0] == 'x' or raw[0] == 'X');
            const digits = raw[if (hex) @as(usize, 1) else 0..];
            const point = std.fmt.parseInt(u21, digits, if (hex) 16 else 10) catch return false;
            if (point == 0 or point == 0xfffd or point > 0x10ffff or (point >= 0xd800 and point <= 0xdfff) or
                point == '&' or (point <= 0x7f and std.ascii.isAlphabetic(@intCast(point)))) return false;
        } else if (end - at <= 64) {
            const entity = @import("shared_xml_decode").html_entities.lookupHtmlNamedEntity(source[at + 1..end]) orelse continue;
            for (entity) |byte| if (std.ascii.isAlphabetic(byte) or byte == '&') return false;
        }
    }
    return true;
}

pub fn closedRowColorAbsenceValid(proof: *const ClosedRowColorProof) bool {
    if (comptime @import("builtin").is_test) if (RowColorAbsenceTraceState.enabled.load(.monotonic)) {
        _ = RowColorAbsenceTraceState.validation_calls.fetchAdd(1, .monotonic);
        _ = RowColorAbsenceTraceState.validation_input_bytes.fetchAdd(@intCast(proof.source.len), .monotonic);
    };
    if (!sourcePlainLinkLabelNamespaceMatches(proof.plain_link_labels, proof.plain_link_namespace)) return false;
    const snapshot = proof.absent_source orelse return false;
    // An owned independent copy detects mutation of either side. It cannot be
    // replaced with the current borrowed slice to manufacture an empty census.
    const current_start = @intFromPtr(proof.source.ptr);
    const snapshot_start = @intFromPtr(snapshot.ptr);
    if (proof.owners.len != 0 or snapshot.len != proof.source.len or
        (snapshot_start <= current_start and current_start - snapshot_start < snapshot.len) or
        (current_start <= snapshot_start and snapshot_start - current_start < proof.source.len)) return false;
    if (comptime @import("builtin").is_test) if (RowColorAbsenceTraceState.enabled.load(.monotonic)) {
        _ = RowColorAbsenceTraceState.snapshot_comparison_calls.fetchAdd(1, .monotonic);
        _ = RowColorAbsenceTraceState.snapshot_input_bytes.fetchAdd(@intCast(proof.source.len), .monotonic);
    };
    if (!std.mem.eql(u8, snapshot, proof.source)) return false;
    return rowColorSourceAbsentWithLabels(proof.source, proof.plain_link_labels);
}

// The Book retains this independent complete page image before caller-side
// preparation. It proves current bytes, not row colors or any CSS property.
pub const PageSourceImage = struct {
    plain_link_labels: ?*const SourcePlainLinkLabels = null,
    plain_link_namespace: ?SourcePlainLinkLabelNamespace = null,
    styles: *const Profile,
    root: *const TextElement,
    source: []const u8,
    snapshot: []const u8,
};

pub fn pageSourceImageCurrent(image: *const PageSourceImage) bool {
    if (image.source.len == 0 or image.source.len != image.snapshot.len) return false;
    const current = @intFromPtr(image.source.ptr);
    const snapshot = @intFromPtr(image.snapshot.ptr);
    if ((snapshot <= current and current - snapshot < image.snapshot.len) or
        (current <= snapshot and snapshot - current < image.source.len)) return false;
    if (!std.mem.eql(u8, image.source, image.snapshot) or
        !sourcePlainLinkLabelNamespaceMatches(image.plain_link_labels, image.plain_link_namespace)) return false;
    if (image.plain_link_labels) |labels| if (!sourcePlainLinkLabelsCurrent(labels, image.source)) return false;
    return true;
}

pub fn unobservedCounterSourceCurrent(proof: *const UnobservedCounterResetProof) bool {
    const image = proof.source_image;
    return proof.styles == image.styles and proof.root == image.root and
        proof.source.ptr == image.source.ptr and proof.source.len == image.source.len and
        proof.source_snapshot.ptr == image.snapshot.ptr and proof.source_snapshot.len == image.snapshot.len and
        pageSourceImageCurrent(image);
}

pub const UnobservedCounterResetProof = struct {
    // Issued once from both retained roles. Current source bytes are pinned
    // independently of positive or empty row-color consumption obligations.
    source_image: *const PageSourceImage,
    styles: *const Profile,
    source: []const u8,
    source_snapshot: []const u8,
    root: *const TextElement,
    rules: []const ContainerRule,
    resets: []const UnobservedCounterReset,
};
const UnobservedCounterReset = struct { rule: usize, name: []const u8 };

pub fn counterDeclarationStreamClosed(css: []const u8) bool {
    if (css.len > 65536 or !std.unicode.utf8ValidateSlice(css)) return false;
    var stack: [32]u8 = undefined; var depth: usize = 0;
    var quote: u8 = 0; var at: usize = 0;
    while (at < css.len) : (at += 1) {
        const byte = css[at];
        if (byte == 0) return false;
        if (quote != 0) {
            if (byte == '\\') { at += 1; if (at == css.len or css[at] == 0) return false; continue; }
            if (byte == quote) { quote = 0; }
            else if (byte == '\n' or byte == '\r' or byte == '\x0c') { return false; }
            continue;
        }
        if (byte == '\\') return false;
        if (byte == '\'' or byte == '"') { quote = byte; continue; }
        if (byte == '/' and at + 1 < css.len and css[at + 1] == '*') {
            const end = std.mem.indexOfPos(u8, css, at + 2, "*/") orelse return false;
            at = end + 1; continue;
        }
        if (byte == '(' or byte == '[' or byte == '{') {
            if (depth == stack.len) return false;
            stack[depth] = byte; depth += 1;
        } else if (byte == ')' or byte == ']' or byte == '}') {
            if (depth == 0) return false;
            depth -= 1;
            const expected: u8 = switch (byte) { ')' => '(', ']' => '[', else => '{' };
            if (stack[depth] != expected) return false;
        }
    }
    return quote == 0 and depth == 0;
}

fn counterName(raw: []const u8) bool {
    if (raw.len == 0 or raw.len > 64 or !std.ascii.isAlphabetic(raw[0])) return false;
    for (raw) |byte| if (!std.ascii.isAlphanumeric(byte) and byte != '-' and byte != '_') return false;
    return !std.ascii.eqlIgnoreCase(raw, "none") and !std.ascii.eqlIgnoreCase(raw, "initial") and
        !std.ascii.eqlIgnoreCase(raw, "inherit") and !std.ascii.eqlIgnoreCase(raw, "unset") and
        !std.ascii.eqlIgnoreCase(raw, "revert") and !std.ascii.eqlIgnoreCase(raw, "revert-layer") and
        !std.ascii.eqlIgnoreCase(raw, "list-item");
}
fn singleCounterReset(raw: []const u8) ?[]const u8 {
    var tokens = std.mem.tokenizeAny(u8, trim(raw), " \t\r\n\x0c");
    const name = tokens.next() orelse return null;
    if (!counterName(name)) return null;
    if (tokens.next()) |value| if (!std.mem.eql(u8, value, "0")) return null;
    if (tokens.next() != null) return null;
    return name;
}
fn counterOperationMayName(raw: []const u8, name: []const u8) bool {
    var tokens = std.mem.tokenizeAny(u8, raw, " \t\r\n\x0c");
    var count: usize = 0;
    while (tokens.next()) |token| {
        count += 1; if (count > 128) return true;
        if (std.mem.eql(u8, token, name)) return true;
        if (std.ascii.eqlIgnoreCase(token, "none") or std.mem.eql(u8, token, "list-item")) continue;
        if (std.fmt.parseInt(i32, token, 10)) |_| continue else |_| {}
        if (!counterName(token)) return true;
    }
    return count == 0;
}
// A quoted string is literal content. A counter's first argument is its name;
// substitutions in its optional style cannot change that argument. Unknown
// content producers remain potential observers, including empty pseudo nodes.
fn counterContentMayRead(raw: []const u8, name: []const u8) bool {
    return counterContentMayReadWithStrings(raw, name, "", 0);
}
fn counterContentMayReadWithStrings(raw: []const u8, name: []const u8, safe_strings: []const u8, recursion: usize) bool {
    if (raw.len > 65536 or recursion > 32) return true;
    var at: usize = 0;
    var count: usize = 0;
    while (at < raw.len) {
        const byte = raw[at];
        if (std.ascii.isWhitespace(byte) or byte == '/') { at += 1; continue; }
        if (byte == '\'' or byte == '"') {
            const quote = byte; at += 1;
            var closed = false;
            while (at < raw.len) : (at += 1) {
                if (raw[at] == '\\') { at += 1; if (at == raw.len) return true; continue; }
                if (raw[at] == quote) { at += 1; closed = true; break; }
                if (raw[at] == '\n' or raw[at] == '\r' or raw[at] == 0) return true;
            }
            if (!closed) return true;
            continue;
        }
        if (!std.ascii.isAlphabetic(byte) and byte != '-') return true;
        const begin = at;
        while (at < raw.len and (std.ascii.isAlphanumeric(raw[at]) or raw[at] == '-' or raw[at] == '_')) : (at += 1) {}
        const word = raw[begin..at];
        count += 1; if (count > 128) return true;
        if (at == raw.len or raw[at] != '(') {
            if (!std.ascii.eqlIgnoreCase(word, "none") and !std.ascii.eqlIgnoreCase(word, "normal") and
                !std.ascii.eqlIgnoreCase(word, "open-quote") and !std.ascii.eqlIgnoreCase(word, "close-quote") and
                !std.ascii.eqlIgnoreCase(word, "no-open-quote") and !std.ascii.eqlIgnoreCase(word, "no-close-quote")) return true;
            continue;
        }
        const function_start = at; at += 1;
        if (std.ascii.eqlIgnoreCase(word, "counter") or std.ascii.eqlIgnoreCase(word, "counters")) {
            while (at < raw.len and std.ascii.isWhitespace(raw[at])) : (at += 1) {}
            const first = at;
            while (at < raw.len and (std.ascii.isAlphanumeric(raw[at]) or raw[at] == '-' or raw[at] == '_')) : (at += 1) {}
            const selected = raw[first..at];
            if (!counterName(selected) or std.mem.eql(u8, selected, name)) return true;
            while (at < raw.len and std.ascii.isWhitespace(raw[at])) : (at += 1) {}
            if (at == raw.len or (raw[at] != ')' and raw[at] != ',')) return true;
        } else if (std.ascii.eqlIgnoreCase(word, "attr")) {
            while (at < raw.len and std.ascii.isWhitespace(raw[at])) : (at += 1) {}
            const first = at;
            while (at < raw.len and (std.ascii.isAlphanumeric(raw[at]) or raw[at] == '-' or raw[at] == '_')) : (at += 1) {}
            if (first == at) return true;
            while (at < raw.len and std.ascii.isWhitespace(raw[at])) : (at += 1) {}
            if (at == raw.len or raw[at] != ')') return true;
        } else if (!std.ascii.eqlIgnoreCase(word, "url") and !std.ascii.eqlIgnoreCase(word, "var")) return true;
        // Skip this bounded balanced function, including quoted style/separator
        // strings. Escaped structural tokens outside strings are unsupported.
        at = function_start;
        var depth: usize = 0; var quote: u8 = 0;
        while (at < raw.len) : (at += 1) {
            const current = raw[at];
            if (quote != 0) {
                if (current == '\\') { at += 1; if (at == raw.len) return true; }
                else if (current == quote) quote = 0;
                continue;
            }
            if (current == '\\' or current == 0 or (current == '/' and at + 1 < raw.len and raw[at + 1] == '*')) return true;
            if (current == '\'' or current == '"') { quote = current; continue; }
            if (current == '(') { depth += 1; if (depth > 32) return true; }
            else if (current == ')') {
                if (depth == 0) return true;
                depth -= 1; if (depth == 0) { at += 1; break; }
            }
        }
        if (depth != 0 or quote != 0) return true;
        if (std.ascii.eqlIgnoreCase(word, "var")) {
            const call = customCall(raw[begin..at]) orelse return true;
            if (!Profile.hasClass(safe_strings, call.name)) return true;
            if (call.fallback) |fallback| if (counterContentMayReadWithStrings(fallback, name, safe_strings, recursion + 1)) return true;
        }
    }
    return false;
}
fn counterDeclarationMayUse(declaration: ObservedFigureDeclaration, name: []const u8, safe_strings: []const u8) bool {
    if (declaration.syntax_unknown) return true;
    if (std.ascii.eqlIgnoreCase(declaration.name, "counter-reset") or std.ascii.eqlIgnoreCase(declaration.name, "counter-set") or
        std.ascii.eqlIgnoreCase(declaration.name, "counter-increment")) return counterOperationMayName(declaration.raw, name);
    if (std.ascii.eqlIgnoreCase(declaration.name, "content")) return counterContentMayReadWithStrings(declaration.raw, name, safe_strings, 0);
    return std.ascii.eqlIgnoreCase(declaration.name, "all");
}
fn counterLiteralStrings(raw: []const u8) bool {
    var at: usize = 0;
    while (at < raw.len) {
        while (at < raw.len and std.ascii.isWhitespace(raw[at])) : (at += 1) {}
        if (at == raw.len) return true;
        if (raw[at] != '\'' and raw[at] != '"') return false;
        const quote = raw[at]; at += 1;
        var closed = false;
        while (at < raw.len) : (at += 1) {
            if (raw[at] == '\\') { at += 1; if (at == raw.len) return false; continue; }
            if (raw[at] == quote) { at += 1; closed = true; break; }
            if (raw[at] == '\n' or raw[at] == '\r' or raw[at] == 0) return false;
        }
        if (!closed) return false;
    }
    return true;
}
fn counterSourceClosed(source: []const u8) bool {
    return counterSourceClosedWithLabels(source, null);
}
fn counterSourceClosedWithLabels(source: []const u8, labels: ?*const SourcePlainLinkLabels) bool {
    if (!sourceAttributeNameConstructionClosedWithLabels(source, null, labels)) return false;
    // Exact captured inline inventories are checked separately. Conservative
    // source candidates also cover omitted/protected literal CSS and prevent
    // an unresolved construction from enrolling a new counter operation.
    if (source.len == 0 or source.len > 4 * 1024 * 1024 or !std.unicode.utf8ValidateSlice(source)) return false;
    for (source, 0..) |byte, at| {
        if (byte == 0 or byte == '\\') return false;
        for ([_][]const u8{ "counter", "<style", "<script", "content", "all" }) |word| {
            if (word.len > source.len - at or !std.ascii.eqlIgnoreCase(source[at..][0..word.len], word)) continue;
            if (std.ascii.eqlIgnoreCase(word, "counter") or word[0] == '<') return false;
            if (at != 0 and (std.ascii.isAlphanumeric(source[at - 1]) or source[at - 1] == '-' or source[at - 1] == '_')) continue;
            var end = at + word.len;
            while (end < source.len and std.ascii.isWhitespace(source[end])) : (end += 1) {}
            if (end < source.len and source[end] == ':') return false;
        }
    }
    return true;
}
fn counterRuleInsideUniqueRoot(rule: ObservedFigureRule, root_class: []const u8) bool {
    const selector = rule.selector orelse return false;
    if (!selector.syntax_known or rule.list_uncertain or selector.chain.len < 2 or
        selector.necessary_previous_sibling or selector.necessary_previous_adjacent != null or
        selector.necessary_sibling_ancestors.len != 0 or selector.necessary_has_next != null) return false;
    // Only ordinary descendant/child edges occur in this known chain. A
    // required class before the subject confines every possible match below
    // the unique retained root, including dynamic subjects and pseudo content.
    for (selector.chain[0 .. selector.chain.len - 1]) |compound|
        for (compound.positive.classes) |class| if (Profile.hasClass(root_class, class)) return true;
    return false;
}
fn counterInventoryEqual(left: *const Profile, right: *const Profile) bool {
    const left_opaque = if (left.custom_properties) |custom| custom.is_opaque else false;
    const right_opaque = if (right.custom_properties) |custom| custom.is_opaque else false;
    if (left_opaque != right_opaque or left.observed_figure_rules.len != right.observed_figure_rules.len) return false;
    for (left.observed_figure_rules, right.observed_figure_rules) |l, r| {
        if (!std.mem.eql(u8, l.raw_selector, r.raw_selector) or !std.mem.eql(u8, l.css, r.css) or
            l.order != r.order or l.source_index != r.source_index or l.source_byte_start != r.source_byte_start or
            l.rank_unknown != r.rank_unknown or l.conditional != r.conditional or l.list_uncertain != r.list_uncertain or
            l.conditions.len != r.conditions.len) return false;
        for (l.conditions, r.conditions) |lc, rc| if (!std.mem.eql(u8, lc, rc)) return false;
    }
    return true;
}
fn counterRuleIsUniqueRoot(rule: ObservedFigureRule, root_class: []const u8) bool {
    const selector = rule.selector orelse return false;
    if (!selector.syntax_known or selector.chain.len != 1 or selector.pseudo != null or rule.list_uncertain or
        rule.rank_unknown or rule.conditional or selector.necessary_previous_sibling or
        selector.necessary_previous_adjacent != null or selector.necessary_sibling_ancestors.len != 0 or
        selector.necessary_has_next != null) return false;
    for (selector.chain[0].positive.classes) |class| if (Profile.hasClass(root_class, class)) return true;
    return false;
}
fn counterResetRuleIndex(styles: *const Profile, candidate: ContainerRule) ?usize {
    const provenance = candidate.provenance orelse return null;
    for (styles.observed_figure_rules, 0..) |rule, index| if (rule.order == candidate.order and
        rule.source_index == provenance.source_index and rule.source_byte_start == provenance.css_byte_start and
        std.mem.eql(u8, rule.raw_selector, provenance.selector) and std.mem.eql(u8, rule.css, candidate.css)) return index;
    return null;
}
const ParsedCounterRule = struct { rule: usize, declarations: []const ObservedFigureDeclaration };
const PreparedCounterInventory = struct {
    styles: *const Profile,
    rules: []const ParsedCounterRule,
    safe_strings: []const u8,
};
fn prepareCounterInventory(scratch: std.mem.Allocator, styles: *const Profile,
    extra_declarations: []const ObservedFigureDeclaration) !?PreparedCounterInventory
{
    var parsed_rules: std.ArrayList(ParsedCounterRule) = .empty;
    var all_declarations: std.ArrayList(ObservedFigureDeclaration) = .empty;
    for (styles.observed_figure_rules, 0..) |rule, index| {
        if (!counterDeclarationStreamClosed(rule.css)) return null;
        var declarations: std.ArrayList(ObservedFigureDeclaration) = .empty;
        try appendObservedFigureDeclarations(scratch, &declarations, rule.css, .{ .order = rule.order }, false,
            rule.rank_unknown, rule.source_index, rule.source_byte_start);
        try parsed_rules.append(scratch, .{ .rule = index, .declarations = declarations.items });
        try all_declarations.appendSlice(scratch, declarations.items);
    }
    try all_declarations.appendSlice(scratch, extra_declarations);
    var safe_string_names: std.ArrayList(u8) = .empty;
    var binding_work: usize = 0;
    var opaque_variables = if (styles.custom_properties) |custom| custom.is_opaque else false;
    for (all_declarations.items) |declaration| if (declaration.syntax_unknown) { opaque_variables = true; break; };
    if (!opaque_variables) for (all_declarations.items) |declaration| {
        if (!customName(declaration.name) or !counterLiteralStrings(declaration.raw) or Profile.hasClass(safe_string_names.items, declaration.name)) continue;
        var safe = true;
        for (all_declarations.items) |other| {
            if (binding_work == 2_000_000) return null;
            binding_work += 1;
            if (std.mem.eql(u8, other.name, declaration.name) and !counterLiteralStrings(other.raw)) { safe = false; break; }
        }
        if (safe) {
            if (safe_string_names.items.len + declaration.name.len + 1 > 65536) return null;
            try safe_string_names.appendSlice(scratch, declaration.name); try safe_string_names.append(scratch, ' ');
        }
    };
    if (styles.observed_figure_rules.len > 8192) return null;
    return .{ .styles = styles, .rules = parsed_rules.items, .safe_strings = safe_string_names.items };
}
pub fn observedUnobservedCounterResets(a: std.mem.Allocator, styles: *const Profile, root: *const TextElement,
    source_image: *const PageSourceImage, contexts: []const FigureObservedContext, unique_root_class: []const u8,
    complete_inline_styles: []const u8) !?UnobservedCounterResetProof
{
    if (styles.globally_unresolved or source_image.styles != styles or source_image.root != root or
        !pageSourceImageCurrent(source_image) or !counterSourceClosedWithLabels(source_image.source, source_image.plain_link_labels) or
        contexts.len != 2 or unique_root_class.len == 0) return null;
    const snapshot = source_image.snapshot;
    for (contexts) |context| {
        if (context.styles.globally_unresolved or !observedStyleGraphValid(context.styles, context.nodes, context.root)) return null;
        var names = std.mem.tokenizeAny(u8, unique_root_class, " \t\r\n\x0c");
        while (names.next()) |name| {
            if (!Profile.hasClass(observedFigureAttribute(context.nodes[context.root], "class") orelse "", name)) return null;
            for (context.nodes, 0..) |node, index| if (index != context.root and
                Profile.hasClass(observedFigureAttribute(node, "class") orelse "", name)) return null;
        }
    }
    if (!counterInventoryEqual(styles, contexts[0].styles)) return null;
    var scratch_storage = std.heap.ArenaAllocator.init(a); defer scratch_storage.deinit();
    const scratch = scratch_storage.allocator();
    var extra_declarations: std.ArrayList(ObservedFigureDeclaration) = .empty;
    if (!counterDeclarationStreamClosed(complete_inline_styles)) return null;
    try appendObservedFigureDeclarations(scratch, &extra_declarations, complete_inline_styles, .{}, false, false, null, 0);
    var extra_bytes = complete_inline_styles.len;
    // Literal custom bindings in either exact graph are also possible token
    // sources. The complete GET/source census covers the unmodelled skin tail.
    for (contexts) |context| for (context.nodes) |node| if (observedFigureAttribute(node, "style")) |css| {
        if (css.len > 65536 - extra_bytes or !counterDeclarationStreamClosed(css)) return null;
        extra_bytes += css.len;
        try appendObservedFigureDeclarations(scratch, &extra_declarations, css, .{}, false, false, null, 0);
    };
    const primary = (try prepareCounterInventory(scratch, styles, extra_declarations.items)) orelse return null;
    var alternative = primary;
    alternative.styles = contexts[1].styles;
    if (!counterInventoryEqual(styles, contexts[1].styles))
        alternative = (try prepareCounterInventory(scratch, contexts[1].styles, extra_declarations.items)) orelse return null;
    const inventories = [_]PreparedCounterInventory{ primary, alternative };
    var work: usize = 0;
    var covered: std.ArrayList(UnobservedCounterReset) = .empty;
    for (styles.container_rules, 0..) |candidate, candidate_index| {
        if (candidate.rank_unknown or candidate.viewport != .all) continue;
        const index = counterResetRuleIndex(styles, candidate) orelse continue;
        const reset = styles.observed_figure_rules[index];
        if (!counterRuleIsUniqueRoot(reset, unique_root_class)) continue;
        for (primary.rules[index].declarations) |declaration| {
            if (!std.ascii.eqlIgnoreCase(declaration.name, "counter-reset") or declaration.syntax_unknown) continue;
            const name = singleCounterReset(declaration.raw) orelse continue;
            const own = observedStyleRuleMatch(reset, contexts[0].nodes, null, contexts[0].root, null, .{});
            if (own == .unknown or observedFigureConditions(reset, .{}) != .known) continue;
            var valid = true;
            for (contexts, inventories) |context, inventory| {
                const safe_strings = inventory.safe_strings;
                // Every ordinal below belongs to this role's own complete
                // inventory. Different API/GET heads are never equated.
                for (inventory.rules) |parsed| {
                    var relevant = false;
                    for (parsed.declarations) |item| if (counterDeclarationMayUse(item, name, safe_strings)) { relevant = true; break; };
                    if (!relevant) continue;
                    const rule = context.styles.observed_figure_rules[parsed.rule];
                    if (counterRuleIsUniqueRoot(rule, unique_root_class)) {
                        for (parsed.declarations) |item| if (counterDeclarationMayUse(item, name, safe_strings) and
                            (!std.ascii.eqlIgnoreCase(item.name, "counter-reset") or
                                !std.mem.eql(u8, singleCounterReset(item.raw) orelse "", name))) { valid = false; };
                        if (!valid) break;
                        const root_match = observedStyleRuleMatch(rule, context.nodes, null, context.root, null, .{});
                        if (root_match == .unknown or observedFigureConditions(rule, .{}) != .known) { valid = false; break; }
                        continue;
                    }
                    // Following siblings inherit counter state too. A consumer
                    // without this positive confinement cannot be refuted by a
                    // graph that ends at the parser-output subtree.
                    if (!counterRuleInsideUniqueRoot(rule, unique_root_class)) { valid = false; break; }
                    if (context.nodes.len > (2_000_000 - work) / 4) return null;
                    work += context.nodes.len * 4;
                    for (context.nodes, 0..) |_, subject| for ([_]?GeneratedFigurePseudo{ null, .before, .after, .other }) |pseudo| {
                        if (observedStyleRuleMatch(rule, context.nodes, null, @intCast(subject), pseudo, .{}) != .no and
                            observedFigureConditions(rule, .{}) != .no) { valid = false; break; }
                    };
                    if (!valid) break;
                }
                if (!valid) break;
                for (context.nodes) |node| if (observedFigureAttribute(node, "style")) |css| {
                    var inline_declarations: std.ArrayList(ObservedFigureDeclaration) = .empty;
                    try appendObservedFigureDeclarations(scratch, &inline_declarations, css, .{}, false, false, null, 0);
                    for (inline_declarations.items) |item| if (counterDeclarationMayUse(item, name, safe_strings)) { valid = false; break; };
                    if (!valid) break;
                };
                if (!valid) break;
            }
            if (valid) {
                if (covered.items.len == 64) return null;
                try covered.append(a, .{ .rule = candidate_index, .name = try a.dupe(u8, name) });
            }
        }
    }
    if (covered.items.len == 0) { covered.deinit(a); return null; }
    return .{ .source_image = source_image, .styles = styles, .source = source_image.source, .source_snapshot = snapshot, .root = root,
        .rules = styles.container_rules, .resets = try covered.toOwnedSlice(a) };
}

pub const page_source_focus_max_actions: usize = 4096;
pub const PageSourceFocusAction = struct { token: []const u8, subjects: [2]u32, original_hrefs: [2]?[]const u8 = .{ null, null } };
const PageSourceFocusActionSnapshot = struct { offset: usize, bytes: usize, subjects: [2]u32, original_hrefs: [2]?[]const u8 };
const PageSourceFocusGraphSnapshot = struct {
    context: ObservedInlineLinkPaintContext,
    nodes: []const ObservedStyleNode,
    rules: []const ObservedFigureRule,
    sources: []const SourceRange,
};

// A provisional, build-only obligation. It never establishes action paint or
// native emission. The Document consumer must discharge every action ordinal.
pub const PageSourceFocusProof = struct {
    storage: std.heap.ArenaAllocator,
    source_image: *const PageSourceImage,
    styles: *const Profile,
    root: *const TextElement,
    complete_root: *const TextElement,
    native_snapshot: []const PageSourceFocusNativeSnapshot,
    source: []const u8,
    source_image_snapshot: []const u8,
    actions: []const PageSourceFocusAction,
    action_snapshot: []const PageSourceFocusActionSnapshot,
    rules: []const ContainerRule,
    rule_snapshot: []const ContainerRule,
    observed_rules: []const ObservedFigureRule,
    observed_snapshot: []const ObservedFigureRule,
    sources: []const SourceRange,
    source_snapshot: []const SourceRange,
    covered_rules: []const usize,
    covered_snapshot: []const usize,
    graphs: [2]PageSourceFocusGraphSnapshot,

    pub fn deinit(self: *@This()) void { self.storage.deinit(); self.* = undefined; }
};

// Complete action-only source has one declaring inline root in each independent
// graph. Its font strut is separate from each A's effective font/paint snapshot.
// This receipt cannot account for ordinary text outside those exact actions.
pub const PageSourceInlineOwnerProof = struct {
    focus: *const PageSourceFocusProof,
    style: types.ContainerStyle,
    style_snapshot: types.ContainerStyle,
    language: []const u8,
    language_snapshot: []const u8,
    absent_rules: []const usize,
    absent_snapshot: []const usize,
    covered_rules: []const usize,
    covered_snapshot: []const usize,

    pub fn jsonStringify(_: @This(), _: anytype) std.Io.Writer.Error!void { return error.WriteFailed; }
    pub fn jsonParse(_: std.mem.Allocator, _: anytype, _: std.json.ParseOptions) !@This() { return error.UnexpectedToken; }
    pub fn jsonParseFromValue(_: std.mem.Allocator, _: std.json.Value, _: std.json.ParseOptions) !@This() { return error.UnexpectedToken; }
};

pub fn pageSourceInlineOwnerCurrent(proof: *const PageSourceInlineOwnerProof) bool {
    return pageSourceFocusCurrent(proof.focus) and proof.language.len != 0 and
        std.mem.eql(u8, proof.language, proof.language_snapshot) and
        observedFigureDataEqual([]const usize, proof.absent_rules, proof.absent_snapshot, 0) and
        observedFigureDataEqual(types.ContainerStyle, proof.style, proof.style_snapshot, 0) and
        observedFigureDataEqual([]const usize, proof.covered_rules, proof.covered_snapshot, 0);
}

fn sourceInlineOwnerProperty(name: []const u8) bool {
    for ([_][]const u8{ "font-family", "font-size", "font-weight", "font-style", "line-height", "color",
        "text-decoration", "text-decoration-line", "outline", "outline-color", "outline-width", "outline-style", "outline-offset" }) |property|
        if (std.ascii.eqlIgnoreCase(name, property)) return true;
    return false;
}

fn sourceInlineOwnerObservedOrigin(styles: *const Profile, candidate: ContainerRule, observed_styles: *const Profile) ?usize {
    const origin = candidate.provenance orelse return null;
    if (candidate.rank_unknown or candidate.viewport != .all or origin.conditions.len != 0 or
        origin.source_index >= styles.sources.len) return null;
    return sourceInlineOwnerObservedIdentity(styles, candidate, observed_styles);
}

fn sourceInlineOwnerObservedIdentity(styles: *const Profile, candidate: ContainerRule, observed_styles: *const Profile) ?usize {
    const origin = candidate.provenance orelse return null;
    if (origin.source_index >= styles.sources.len) return null;
    const source = styles.sources[origin.source_index];
    for (observed_styles.observed_figure_rules, 0..) |rule, index| {
        if (rule.source_index >= observed_styles.sources.len or rule.source_byte_start != origin.css_byte_start or
            !std.mem.eql(u8, rule.raw_selector, origin.selector) or !std.mem.eql(u8, rule.css, candidate.css) or
            !pageSourceFocusSourceEqual(source, observed_styles.sources[rule.source_index])) continue;
        return index;
    }
    return null;
}

// Refutation uses the maintained selector matcher with unknown action state.
// Every captured node and pseudo subject in both graphs must be impossible;
// rank and condition uncertainty cannot revive a selector that matches nowhere.
fn sourceInlineOwnerRuleAbsent(styles: *const Profile, candidate: ContainerRule, contexts: []const ObservedInlineLinkPaintContext) bool {
    for (contexts) |context| {
        const index = sourceInlineOwnerObservedIdentity(styles, candidate, context.styles) orelse return false;
        const observed = context.styles.observed_figure_rules[index];
        for (context.nodes, 0..) |_, subject| {
            for ([_]?GeneratedFigurePseudo{ null, .before, .after, .other }) |pseudo|
                if (observedStyleRuleMatch(observed, context.nodes, null, @intCast(subject), pseudo, .{}) != .no) return false;
        }
    }
    return true;
}

fn sourceInlineOwnerFocusDeclaration(proof: *const PageSourceFocusProof, context: ObservedInlineLinkPaintContext,
    declaration: ObservedFigureDeclaration) bool
{
    if (!std.ascii.eqlIgnoreCase(declaration.name, "outline-color")) return false;
    for (proof.covered_rules) |index| {
        if (index >= proof.styles.container_rules.len) return false;
        const observed = pageSourceFocusObservedOrigin(proof.styles, proof.styles.container_rules[index], context.styles) orelse continue;
        const rule = context.styles.observed_figure_rules[observed];
        if (declaration.source_index == rule.source_index and declaration.source_byte_start == rule.source_byte_start) return true;
    }
    return false;
}

pub fn observedPageSourceInlineOwnerAlloc(a: std.mem.Allocator, focus: *const PageSourceFocusProof) std.mem.Allocator.Error!?PageSourceInlineOwnerProof {
    return observedPageSourceInlineOwnerIn(a, focus) catch |err| switch (err) {
        error.OutOfMemory => return error.OutOfMemory, else => return null,
    };
}

fn observedPageSourceInlineOwnerIn(a: std.mem.Allocator, focus: *const PageSourceFocusProof) !?PageSourceInlineOwnerProof {
    if (!pageSourceFocusCurrent(focus) or focus.actions.len == 0) return null;
    // Use the maintained inline parser for transparent balanced emphasis. Its
    // exact source slices, not label equality, identify every issued action.
    const InlineIterator = @import("blob_encoder").document_ir.InlineIterator;
    var iterator: InlineIterator = .{ .input = focus.source, .renderer_boundaries = true };
    var action_index: usize = 0;
    while (iterator.next()) |token| {
        if (token.kind == .text and token.text.len == 0) continue;
        if ((token.kind != .link and token.kind != .external_link) or action_index >= focus.actions.len or
            token.trail.len != 0 or token.literal_tail or token.link_label_restored_close) return null;
        const action = focus.actions[action_index];
        const offset = pageSourceFocusTokenOffset(focus.source, action.token) orelse return null;
        var selected: InlineIterator = .{ .input = action.token, .renderer_boundaries = true };
        const expected = selected.next() orelse return null;
        if (selected.cursor != action.token.len or iterator.cursor != offset + action.token.len or
            token.kind != expected.kind or token.text.ptr != expected.text.ptr or token.text.len != expected.text.len or
            token.target.ptr != expected.target.ptr or token.target.len != expected.target.len) return null;
        action_index += 1;
    }
    if (iterator.cursor != focus.source.len or iterator.bold or iterator.italic or action_index != focus.actions.len) return null;
    const contexts = [_]ObservedInlineLinkPaintContext{ focus.graphs[0].context, focus.graphs[1].context };
    const samples = (try observedInlineLinkViewportSamples(a, &contexts)) orelse return null;
    var style: ?types.ContainerStyle = null;
    var language: ?[]const u8 = null;
    for (contexts, 0..) |context, arm| for (samples) |sample| {
        const owner = (try observedInlineDeclaringOwnerFont(a, context, context.root, null, sample.width)) orelse return null;
        if (owner.language.len == 0 or owner.font_scale_basis != .normal_body or owner.font_scale == null or owner.font_family == null or
            owner.bold or owner.italic or owner.code or owner.small or owner.superscript or owner.subscript or
            owner.font_features != null or owner.role != .normal or owner.classes.len != 0) return null;
        if (language) |held| {
            if (!std.mem.eql(u8, held, owner.language)) return null;
        } else language = owner.language;
        const value: types.ContainerStyle = .{ .font_family = owner.font_family, .owner_font_scale = owner.font_scale };
        if (style) |prior| {
            if (!observedFigureDataEqual(types.ContainerStyle, prior, value, 0)) return null;
        } else style = value;
        for (context.nodes, 0..) |node, index| {
            var inside_action = false;
            for (focus.actions) |action| if (authoredElementDescendant(context.nodes, @intCast(index), action.subjects[arm])) {
                inside_action = true; break;
            };
            if (inside_action) continue;
            // A focus census does not represent direction, presentational box
            // attributes or activation. Keep only inert metadata and the exact
            // stylesheet declarations accounted below; never infer an initial
            // direction from a non-LTR/automatic captured attribute.
            for (node.attributes) |attribute| {
                if (std.ascii.eqlIgnoreCase(attribute.name, "dir")) {
                    if (!std.ascii.eqlIgnoreCase(attribute.value, "ltr")) return null;
                    continue;
                }
                var metadata = false;
                for ([_][]const u8{ "class", "id", "lang", "title", "style", "typeof", "about", "data-mw", "data-mw-i18n",
                    "data-mw-section-id", "data-mw-parsoid-version", "data-mw-html-version", "data-mw-ve-target-container" }) |name|
                    if (std.ascii.eqlIgnoreCase(attribute.name, name)) { metadata = true; break; };
                if (!metadata) return null;
            }
            // Only root ancestry and consumed emphasis can own this anonymous
            // inline source outside an A. No paragraph margin or other box
            // borrows the action census or this root's font strut.
            if (authoredElementDescendant(context.nodes, @intCast(index), context.root) and node.has_text != false) return null;
            if (!authoredElementDescendant(context.nodes, context.root, @intCast(index))) {
                const emphasis = std.ascii.eqlIgnoreCase(node.tag, "i") or std.ascii.eqlIgnoreCase(node.tag, "b");
                if (!emphasis) return null;
                const declaring = (try observedInlineDeclaringOwnerFont(a, context, @intCast(index), null, sample.width)) orelse return null;
                var owns_action = false;
                for (focus.actions) |action| if (authoredElementDescendant(context.nodes, action.subjects[arm], @intCast(index))) {
                    owns_action = true;
                    if (emphasis) {
                        const child_font = (try observedInlineDeclaringLinkFont(a, context, action.subjects[arm], sample.width)) orelse return null;
                        if (!observedFigureDataEqual(types.InlineFontSnapshot, declaring, child_font, 0)) return null;
                    }
                };
                if (!owns_action) return null;
            }
            for ([_]bool{ false, true }) |motion| {
                var declarations = (try observedStyleNodeDeclarations(a, context.styles, context.nodes, @intCast(index), null, null,
                    .{ .viewport_width = sample.width, .reduced_motion = motion })) orelse return null;
                defer declarations.deinit(a);
                for (declarations.items) |declaration| {
                    if (customName(declaration.name) and !declaration.syntax_unknown) continue;
                    if (sourceInlineOwnerFocusDeclaration(focus, context, declaration)) continue;
                    if (!std.ascii.eqlIgnoreCase(declaration.name, "font-family") and
                        !std.ascii.eqlIgnoreCase(declaration.name, "font-size") and
                        !std.ascii.eqlIgnoreCase(declaration.name, "font-weight") and
                        !std.ascii.eqlIgnoreCase(declaration.name, "font-style") and
                        !std.ascii.eqlIgnoreCase(declaration.name, "color")) return null;
                }
            }
        }
    };
    var covered: std.ArrayList(usize) = .empty;
    var absent: std.ArrayList(usize) = .empty;
    for (focus.styles.container_rules, 0..) |rule, index| {
        if (sourceInlineOwnerRuleAbsent(focus.styles, rule, &contexts)) {
            try absent.append(a, index);
            try covered.append(a, index);
            continue;
        }
        for (contexts) |context| _ = sourceInlineOwnerObservedOrigin(focus.styles, rule, context.styles) orelse return null;
        var position: usize = 0;
        while (try nextDeclarationAlloc(a, rule.css, &position)) |raw| {
            defer a.free(raw);
            if (trim(raw).len == 0) continue;
            const colon = std.mem.indexOfScalar(u8, raw, ':') orelse return null;
            const name = trim(raw[0..colon]);
            const priority = customPriority(raw[colon + 1 ..]);
            if (priority.unknown or trim(priority.value).len == 0 or
                (!customName(name) and !sourceInlineOwnerProperty(name))) return null;
        }
        try covered.append(a, index);
    }
    const owned_style = style orelse return null;
    const indices = try covered.toOwnedSlice(a);
    const absent_indices = try absent.toOwnedSlice(a);
    return .{ .absent_rules = absent_indices, .absent_snapshot = try a.dupe(usize, absent_indices),
        .focus = focus, .style = owned_style, .language = language.?, .language_snapshot = try a.dupe(u8, language.?),
        .style_snapshot = try observedFigureDataClone(types.ContainerStyle, a, owned_style, 0),
        .covered_rules = indices, .covered_snapshot = try a.dupe(usize, indices) };
}

fn pageSourceFocusTokenOffset(source: []const u8, token: []const u8) ?usize {
    const base = @intFromPtr(source.ptr); const address = @intFromPtr(token.ptr);
    if (token.len == 0 or address < base or address - base > source.len or token.len > source.len - (address - base)) return null;
    return address - base;
}

pub fn pageSourceFocusCurrent(proof: *const PageSourceFocusProof) bool {
    if (proof.styles != proof.source_image.styles or proof.root != proof.source_image.root or
        proof.source.ptr != proof.source_image.source.ptr or proof.source.len != proof.source_image.source.len or
        proof.source_image_snapshot.ptr != proof.source_image.snapshot.ptr or proof.source_image_snapshot.len != proof.source_image.snapshot.len or
        !pageSourceImageCurrent(proof.source_image) or proof.styles.globally_unresolved or proof.styles.reading_target != .screen or
        proof.rules.ptr != proof.styles.container_rules.ptr or proof.rules.len != proof.styles.container_rules.len or
        proof.observed_rules.ptr != proof.styles.observed_figure_rules.ptr or proof.observed_rules.len != proof.styles.observed_figure_rules.len or
        proof.covered_rules.len == 0 or proof.actions.len > page_source_focus_max_actions or
        proof.actions.len != proof.action_snapshot.len or
        !observedFigureDataEqual([]const ContainerRule, proof.rules, proof.rule_snapshot, 0) or
        !observedFigureDataEqual([]const ObservedFigureRule, proof.observed_rules, proof.observed_snapshot, 0) or
        proof.sources.ptr != proof.styles.sources.ptr or proof.sources.len != proof.styles.sources.len or
        !observedFigureDataEqual([]const SourceRange, proof.sources, proof.source_snapshot, 0) or
        !observedFigureDataEqual([]const usize, proof.covered_rules, proof.covered_snapshot, 0)) return false;
    if (!pageSourceFocusAlternativesConsistent(proof.complete_root)) return false;
    for (proof.native_snapshot) |snapshot| if (!pageSourceFocusNativeCurrent(snapshot)) return false;
    if (!pageSourceFocusWeakGraph(proof.root, proof.graphs[0].context) or
        !pageSourceFocusNativeGraph(proof.complete_root, proof.graphs[0].context) or
        !pageSourceFocusNativeGraph(proof.complete_root.alternative_ancestry orelse proof.complete_root, proof.graphs[1].context)) return false;
    for (proof.actions, proof.action_snapshot) |action, snapshot| {
        const offset = pageSourceFocusTokenOffset(proof.source, action.token) orelse return false;
        if (offset != snapshot.offset or action.token.len != snapshot.bytes or !std.meta.eql(action.subjects, snapshot.subjects) or
            !observedFigureDataEqual([2]?[]const u8, action.original_hrefs, snapshot.original_hrefs, 0)) return false;
    }
    for (proof.graphs) |graph| {
        const context = graph.context;
        if (context.styles.globally_unresolved or context.styles.reading_target != .screen or
            !observedStyleGraphValid(context.styles, context.nodes, context.root) or
            !observedFigureDataEqual([]const ObservedStyleNode, context.nodes, graph.nodes, 0) or
            !observedFigureDataEqual([]const ObservedFigureRule, context.styles.observed_figure_rules, graph.rules, 0) or
            !observedFigureDataEqual([]const SourceRange, context.styles.sources, graph.sources, 0)) return false;
    }
    return true;
}

fn pageSourceFocusSourceEqual(left: SourceRange, right: SourceRange) bool {
    return left.byte_start == right.byte_start and left.bytes == right.bytes and
        left.unknown_applicability == right.unknown_applicability and
        std.mem.eql(u8, left.base_url, right.base_url) and std.mem.eql(u8, &left.css_sha256, &right.css_sha256);
}
fn pageSourceFocusObservedOrigin(styles: *const Profile, candidate: ContainerRule, observed_styles: *const Profile) ?usize {
    const origin = candidate.provenance orelse return null;
    if (candidate.rank_unknown or candidate.viewport != .all or origin.conditions.len != 0 or
        !std.mem.eql(u8, trim(origin.selector), ":focus") or origin.source_index >= styles.sources.len) return null;
    const source = styles.sources[origin.source_index];
    for (observed_styles.observed_figure_rules, 0..) |rule, index| {
        if (rule.source_index >= observed_styles.sources.len or rule.source_byte_start != origin.css_byte_start or
            !std.mem.eql(u8, rule.raw_selector, origin.selector) or !std.mem.eql(u8, rule.css, candidate.css) or
            !pageSourceFocusSourceEqual(source, observed_styles.sources[rule.source_index])) continue;
        return index;
    }
    return null;
}

fn pageSourceFocusRuleEligible(a: std.mem.Allocator, styles: *const Profile, rule: ContainerRule) !bool {
    const original = pageSourceFocusObservedOrigin(styles, rule, styles) orelse return false;
    return tableSourceFocusRule(a, styles.observed_figure_rules[original]);
}

pub fn hasPageSourceFocusObligation(styles: *const Profile) bool {
    if (styles.globally_unresolved or styles.reading_target != .screen or styles.page_style_parent == null) return false;
    var buffer: [512]u8 = undefined;
    for (styles.container_rules) |rule| {
        var fixed = std.heap.FixedBufferAllocator.init(&buffer);
        const eligible = pageSourceFocusRuleEligible(fixed.allocator(), styles, rule) catch
            (pageSourceFocusRuleEligible(std.heap.page_allocator, styles, rule) catch false);
        if (eligible) return true;
    }
    return false;
}

fn pageSourceFocusNeutralAttributes(node: ObservedStyleNode, original_href: ?[]const u8) bool {
    var supported = false;
    for ([_][]const u8{ "html", "body", "main", "article", "section", "div", "span", "b", "strong", "i", "em", "u", "s", "small", "big", "sup", "sub", "abbr", "cite", "p", "h1", "h2", "h3", "h4", "h5", "h6", "dl", "dt", "dd", "ul", "ol", "li", "figure", "figcaption", "table", "caption", "thead", "tbody", "tfoot", "tr", "td", "th", "colgroup", "col", "img", "br", "hr", "wbr", "meta", "link", "style", "code", "pre", "mark", "bdi", "bdo", "ruby", "rp", "rt", "a" }) |tag|
        if (std.ascii.eqlIgnoreCase(node.tag, tag)) { supported = true; break; };
    if (!supported) return false;
    const anchor = std.ascii.eqlIgnoreCase(node.tag, "a");
    if (anchor and (observedFigureAttribute(node, "href") orelse return false).len == 0) return false;
    // Inert normalization metadata is admitted only as an exact per-operation
    // input already consumed by Book's source/captured target join. This query
    // does not normalize a URL or establish that independent correspondence.
    if (original_href) |expected| {
        if (!anchor or expected.len == 0 or !std.mem.eql(u8,
            observedFigureAttribute(node, "data-mw-original-href") orelse return false, expected)) return false;
    } else if (observedFigureAttribute(node, "data-mw-original-href") != null) return false;
    for (node.attributes) |attribute| {
        const name = attribute.name;
        if (name.len >= 2 and std.ascii.eqlIgnoreCase(name[0..2], "on")) return false;
        for ([_][]const u8{ "contenteditable", "tabindex", "autofocus", "accesskey", "role", "draggable", "hidden", "inert", "controls", "usemap", "ismap" }) |activation|
            if (std.ascii.eqlIgnoreCase(name, activation)) return false;
        var known = false;
        for ([_][]const u8{ "class", "id", "lang", "dir", "title", "style", "align", "width", "height", "rowspan", "colspan", "border", "cellpadding", "cellspacing", "src", "alt", "typeof", "about", "data-mw", "data-mw-i18n", "data-mw-section-id", "data-mw-parsoid-version", "data-mw-html-version", "data-mw-ve-target-container", "data-column-count", "aria-labelledby", "aria-hidden" }) |plain|
            if (std.ascii.eqlIgnoreCase(name, plain)) { known = true; break; };
        if (anchor and (std.ascii.eqlIgnoreCase(name, "href") or std.ascii.eqlIgnoreCase(name, "rel"))) known = true;
        if (anchor and original_href != null and std.ascii.eqlIgnoreCase(name, "data-mw-original-href")) known = true;
        if (!known) return false;
        if (std.ascii.eqlIgnoreCase(name, "class")) {
            var classes = std.mem.tokenizeAny(u8, attribute.value, " \t\r\n\x0c");
            while (classes.next()) |class| for ([_][]const u8{ "NavFrame", "NavContent", "collapsible", "sortable", "mw-collapsible", "mw-collapsed", "mw-collapsible-content", "oo-ui-widget", "mw-ui-button" }) |hook|
                if (std.mem.eql(u8, class, hook)) return false;
        }
    }
    return true;
}

fn pageSourceFocusGraphClosed(a: std.mem.Allocator, contexts: []const ObservedInlineLinkPaintContext,
    actions: []const PageSourceFocusAction) !bool
{
    if (contexts.len != 2) return false;
    for (contexts, 0..) |context, arm| {
        if (context.styles.globally_unresolved or context.styles.reading_target != .screen or context.nodes.len > 16384 or
            !observedStyleGraphValid(context.styles, context.nodes, context.root)) return false;
        var anchors: usize = 0;
        for (context.nodes, 0..) |node, index| {
            if (!std.ascii.eqlIgnoreCase(node.tag, "a")) {
                if (!pageSourceFocusNeutralAttributes(node, null)) return false;
                continue;
            }
            if (!authoredElementDescendant(context.nodes, @intCast(index), context.root)) return false;
            var found: usize = 0;
            var original_href: ?[]const u8 = null;
            for (actions) |action| {
                if (action.subjects[arm] == index) { found += 1; original_href = action.original_hrefs[arm]; }
            }
            if (found != 1 or !pageSourceFocusNeutralAttributes(node, original_href)) return false;
            anchors += 1;
        }
        if (anchors != actions.len) return false;
    }
    const samples = (try observedInlineLinkViewportSamples(a, contexts)) orelse return false;
    var scratch_storage = std.heap.ArenaAllocator.init(a); defer scratch_storage.deinit();
    for (contexts) |context| for (samples) |sample| for ([_]bool{ false, true }) |motion| {
        _ = scratch_storage.reset(.retain_capacity); const scratch = scratch_storage.allocator();
        const environments = try scratch.alloc(CustomEnvironment, context.nodes.len);
        for (context.nodes, 0..) |node, index| {
            const parent: CustomEnvironment = if (node.parent) |parent_index| environments[parent_index] else .{ .complete = true };
            var collected = (try observedStyleNodeDeclarations(scratch, context.styles, context.nodes, @intCast(index), null, null,
                .{ .viewport_width = sample.width, .reduced_motion = motion })) orelse return false;
            defer collected.deinit(scratch);
            const environment = try observedFigureCustomEnvironment(scratch, collected.items, parent, true);
            environments[index] = environment;
            if (!tableSourceStaticFocusDeclarations(collected.items) or !try observedFigureStaticMotion(scratch, collected.items, environment)) return false;
            if (std.ascii.eqlIgnoreCase(node.tag, "a")) continue;
            // A scrollable non-A owner has a real independent focus obligation.
            // No Table/Figure count or absent tabindex can discharge it here.
            for ([_][]const u8{ "overflow", "overflow-x", "overflow-y" }) |property| {
                const value = try observedFigureKeyword(scratch, collected.items, property,
                    if (std.mem.eql(u8, property, "overflow")) &.{} else &.{"overflow"}, environment,
                    &.{"visible"}, "visible", null, false, "visible");
                if (value.unresolved or value.value == null or !std.mem.eql(u8, value.value.?, "visible")) return false;
            }
        }
    };
    return true;
}

pub fn observedPageSourceFocusAlloc(a: std.mem.Allocator, styles: *const Profile, root: *const TextElement,
    complete_root: *const TextElement, source_image: *const PageSourceImage, contexts: []const ObservedInlineLinkPaintContext,
    actions: []const PageSourceFocusAction) std.mem.Allocator.Error!?PageSourceFocusProof
{
    if (styles.globally_unresolved or styles.reading_target != .screen or styles.page_style_parent == null or
        source_image.styles != styles or source_image.root != root or !pageSourceImageCurrent(source_image) or
        contexts.len != 2 or contexts[0].nodes.ptr == contexts[1].nodes.ptr or actions.len > page_source_focus_max_actions) return null;
    if (!pageSourceFocusAlternativesConsistent(complete_root)) return null;
    if (!pageSourceFocusWeakGraph(root, contexts[0]) or !pageSourceFocusNativeGraph(complete_root, contexts[0]) or
        !pageSourceFocusNativeGraph(complete_root.alternative_ancestry orelse complete_root, contexts[1])) return null;
    var storage = std.heap.ArenaAllocator.init(a); var retain = false; defer if (!retain) storage.deinit();
    const owned = storage.allocator();
    var prior_end: usize = 0;
    for (actions, 0..) |action, index| {
        const offset = pageSourceFocusTokenOffset(source_image.source, action.token) orelse return null;
        if (offset < prior_end) return null;
        prior_end = offset + action.token.len;
        for (contexts, 0..) |context, arm| {
            const subject = action.subjects[arm];
            if (subject >= context.nodes.len or !std.ascii.eqlIgnoreCase(context.nodes[subject].tag, "a") or
                (index != 0 and subject <= actions[index - 1].subjects[arm])) return null;
        }
    }
    if (!(pageSourceFocusGraphClosed(owned, contexts, actions) catch |err| switch (err) {
        error.OutOfMemory => return error.OutOfMemory, else => return null,
    })) return null;
    var covered: std.ArrayList(usize) = .empty;
    for (styles.container_rules, 0..) |rule, index| {
        if (!try pageSourceFocusRuleEligible(owned, styles, rule)) continue;
        var complete = true;
        for (contexts) |context| {
            const observed = pageSourceFocusObservedOrigin(styles, rule, context.styles) orelse { complete = false; break; };
            if (!try tableSourceFocusRule(owned, context.styles.observed_figure_rules[observed])) { complete = false; break; }
        }
        if (complete) try covered.append(owned, index);
    }
    if (covered.items.len == 0) return null;
    var graphs: [2]PageSourceFocusGraphSnapshot = undefined;
    for (contexts, 0..) |context, arm| graphs[arm] = .{
        .context = context,
        .nodes = observedFigureDataClone([]const ObservedStyleNode, owned, context.nodes, 0) catch |err| switch (err) { error.OutOfMemory => return error.OutOfMemory, else => return null },
        .rules = observedFigureDataClone([]const ObservedFigureRule, owned, context.styles.observed_figure_rules, 0) catch |err| switch (err) { error.OutOfMemory => return error.OutOfMemory, else => return null },
        .sources = observedFigureDataClone([]const SourceRange, owned, context.styles.sources, 0) catch |err| switch (err) { error.OutOfMemory => return error.OutOfMemory, else => return null },
    };
    const snapshots = try owned.alloc(PageSourceFocusActionSnapshot, actions.len);
    for (actions, snapshots) |action, *snapshot| snapshot.* = .{ .offset = pageSourceFocusTokenOffset(source_image.source, action.token).?,
        .bytes = action.token.len, .subjects = action.subjects,
        .original_hrefs = observedFigureDataClone([2]?[]const u8, owned, action.original_hrefs, 0) catch |err| switch (err) {
            error.OutOfMemory => return error.OutOfMemory, else => return null,
        } };
    const covered_rules = try covered.toOwnedSlice(owned);
    var proof: PageSourceFocusProof = .{
        .storage = undefined, .source_image = source_image, .styles = styles, .root = root, .source = source_image.source, .source_image_snapshot = source_image.snapshot,
        .complete_root = complete_root, .native_snapshot = try pageSourceFocusNativeSnapshots(owned, root, complete_root),
        .actions = try owned.dupe(PageSourceFocusAction, actions), .action_snapshot = snapshots,
        .rules = styles.container_rules,
        .rule_snapshot = observedFigureDataClone([]const ContainerRule, owned, styles.container_rules, 0) catch |err| switch (err) { error.OutOfMemory => return error.OutOfMemory, else => return null },
        .observed_rules = styles.observed_figure_rules,
        .observed_snapshot = observedFigureDataClone([]const ObservedFigureRule, owned, styles.observed_figure_rules, 0) catch |err| switch (err) { error.OutOfMemory => return error.OutOfMemory, else => return null },
        .sources = styles.sources,
        .source_snapshot = observedFigureDataClone([]const SourceRange, owned, styles.sources, 0) catch |err| switch (err) { error.OutOfMemory => return error.OutOfMemory, else => return null },
        .covered_rules = covered_rules, .covered_snapshot = try owned.dupe(usize, covered_rules), .graphs = graphs,
    };
    proof.storage = storage;
    if (!pageSourceFocusCurrent(&proof)) return null;
    retain = true;
    return proof;
}

const PageSourceFocusNativeSnapshot = struct {
    node: *const TextElement,
    tag: []const u8, classes: []const u8, id: []const u8, language: ?[]const u8,
    inline_style: ?[]const u8, attributes: ?AttributePresenceSource,
    parent: ?*const TextElement, alternative: ?*const TextElement,
    ancestry_complete: bool, physical_complete: bool,
};
fn pageSourceFocusOptionalEqual(left: ?[]const u8, right: ?[]const u8) bool {
    if (left) |value| return if (right) |other| std.mem.eql(u8, value, other) else false;
    return right == null;
}
fn pageSourceFocusNativeCurrent(snapshot: PageSourceFocusNativeSnapshot) bool {
    const node = snapshot.node;
    if (!std.mem.eql(u8, node.tag, snapshot.tag) or !std.mem.eql(u8, node.classes, snapshot.classes) or
        !std.mem.eql(u8, node.id, snapshot.id) or !pageSourceFocusOptionalEqual(node.language, snapshot.language) or
        !pageSourceFocusOptionalEqual(node.observed_inline_style, snapshot.inline_style) or
        node.parent != snapshot.parent or node.alternative_ancestry != snapshot.alternative or
        node.ancestry_complete != snapshot.ancestry_complete or node.physical_ancestry_complete != snapshot.physical_complete) return false;
    if (snapshot.attributes) |retained| {
        const current = node.attribute_presence orelse return false;
        if (current.ctx != retained.ctx or current.get != retained.get) return false;
    } else if (node.attribute_presence != null) return false;
    return true;
}
fn pageSourceFocusNativeGraph(root: *const TextElement, context: ObservedInlineLinkPaintContext) bool {
    var native: ?*const TextElement = root;
    var observed: ?u32 = context.root;
    var remaining: usize = 64;
    while (native) |node| {
        if (remaining == 0) return false;
        remaining -= 1;
        const index = observed orelse return false;
        if (index >= context.nodes.len or !node.ancestry_complete or !node.physical_ancestry_complete) return false;
        const captured = context.nodes[index];
        if (!std.ascii.eqlIgnoreCase(node.tag, captured.tag) or
            !std.mem.eql(u8, node.classes, observedFigureAttribute(captured, "class") orelse "") or
            !std.mem.eql(u8, node.id, observedFigureAttribute(captured, "id") orelse "") or
            !pageSourceFocusOptionalEqual(node.language, observedFigureAttribute(captured, "lang")) or
            !std.mem.eql(u8, node.observed_inline_style orelse return false, observedFigureAttribute(captured, "style") orelse "")) return false;
        const attributes = node.attribute_presence orelse return false;
        for (captured.attributes) |attribute| if (attributes.get(attributes.ctx, attribute.name) != .present) return false;
        for ([_][]const u8{ "tabindex", "contenteditable", "autofocus", "accesskey", "role", "draggable", "hidden", "inert", "controls", "usemap", "ismap", "onfocus", "onblur", "onclick", "onkeydown", "onmouseover" }) |activation| {
            if (attributes.get(attributes.ctx, activation) != .absent) return false;
        }
        native = node.parent; observed = captured.parent;
    }
    return observed == null;
}
fn pageSourceFocusWeakGraph(root: *const TextElement, context: ObservedInlineLinkPaintContext) bool {
    var native: ?*const TextElement = root; var observed: ?u32 = context.root;
    var remaining: usize = 64;
    while (native) |node| {
        if (remaining == 0) return false; remaining -= 1;
        const index = observed orelse return false;
        if (index >= context.nodes.len) return false;
        const captured = context.nodes[index];
        // The weak path must not contain contradictory native activation or
        // inline-style information. Book's weak path intentionally has neither.
        if (node.attribute_presence != null or node.observed_inline_style != null or node.alternative_ancestry != null or
            !std.ascii.eqlIgnoreCase(node.tag, captured.tag) or
            !std.mem.eql(u8, node.classes, observedFigureAttribute(captured, "class") orelse "")) return false;
        native = node.parent; observed = captured.parent;
    }
    return true;
}
fn pageSourceFocusNativeSnapshots(a: std.mem.Allocator, weak: *const TextElement, complete: *const TextElement) std.mem.Allocator.Error![]const PageSourceFocusNativeSnapshot {
    var snapshots: std.ArrayList(PageSourceFocusNativeSnapshot) = .empty;
    for ([_]*const TextElement{ weak, complete, complete.alternative_ancestry orelse complete }) |root| {
        var cursor: ?*const TextElement = root;
        var remaining: usize = 64;
        while (cursor) |node| {
            if (remaining == 0) break; remaining -= 1;
            try snapshots.append(a, .{ .node = node, .tag = try a.dupe(u8, node.tag), .classes = try a.dupe(u8, node.classes),
                .id = try a.dupe(u8, node.id), .language = if (node.language) |value| try a.dupe(u8, value) else null,
                .inline_style = if (node.observed_inline_style) |value| try a.dupe(u8, value) else null,
                .attributes = node.attribute_presence, .parent = node.parent, .alternative = node.alternative_ancestry,
                .ancestry_complete = node.ancestry_complete, .physical_complete = node.physical_ancestry_complete });
            cursor = node.parent;
        }
    }
    return snapshots.toOwnedSlice(a);
}

fn pageSourceFocusAlternativesConsistent(root: *const TextElement) bool {
    var primary: ?*const TextElement = root;
    var alternative: ?*const TextElement = root.alternative_ancestry;
    const has_alternative = alternative != null;
    var remaining: usize = 64;
    while (primary) |node| {
        if (remaining == 0) return false; remaining -= 1;
        if (has_alternative) {
            const other = alternative orelse return false;
            if (node.alternative_ancestry != other or other.alternative_ancestry != null) return false;
            alternative = other.parent;
        } else if (node.alternative_ancestry != null) return false;
        primary = node.parent;
    }
    return alternative == null;
}

pub const PageStaticMotionProof = struct {
    styles: *const Profile,
    source: []const u8,
    root: *const TextElement,
};

pub const BoundedTextClassScope = struct {
    page_source_image: ?*const PageSourceImage = null,
    page_source_focus: ?*const PageSourceFocusProof = null,
    page_source_inline_owner: ?*const PageSourceInlineOwnerProof = null,
    unobserved_counter_resets: ?UnobservedCounterResetProof = null,
    page_static_motion: ?PageStaticMotionProof = null,
    closed_row_colors: ?ClosedRowColorProof = null,
    closed_missing_figures: ?ClosedMissingFigureProof = null,
    empty_missing_figure_captions: ?EmptyMissingFigureCaptionProof = null,
    closed_ready_figures: ?ClosedReadyFigureProof = null,
    source_div_parent_tags: []const SourceDivParentTagProof = &.{},
    source_div_parent_tags_source: ?[]const u8 = null,
    source_literal_divs: []const SourceLiteralDivProof = &.{},
    source_literal_divs_source: ?[]const u8 = null,
    source_root_tables: []const SourceRootTableProof = &.{},
    source_root_tables_source: ?[]const u8 = null,
    // Separate positive capability issued only after exact complete-page selection.
    // It proves a distant parser-root ancestor, never an edge or sibling position.
    page_styles: ?*const Profile = null,
    page_style_root: ?*const TextElement = null,
    // Independent complete path, consumed only by a source-issued root child.
    page_style_complete_root: ?*const TextElement = null,
    // Computed agreement over every observed parser-subtree element under
    // both authenticated shell states. This certifies no node identity or edge.
    page_custom_invariant: ?CustomEnvironment = null,
    source_custom_elements: []const SourceCustomElementProof = &.{},
    source_custom_elements_source: ?[]const u8 = null,
    source_root_children: []const SourceRootChildProof = &.{},
    source_root_parent_groups: []const SourceRootParentProof = &.{},
    source_root_children_source: ?[]const u8 = null,
    source_bullet_rubies: []const SourceBulletRubyProof = &.{},
    source_bullet_rubies_source: ?[]const u8 = null,
    source_inline_rubies: []const SourceInlineRubyProof = &.{},
    source_inline_rubies_source: ?[]const u8 = null,
    source_siblings: []const SourceSiblingProof = &.{},
    source_siblings_source: ?[]const u8 = null,
    root_tag: []const u8,
    root_classes: []const u8,
    subtree_classes: []const u8,
    complete_ancestor_class_superset: ?[]const u8 = null,
    // Complete selected source and both captured outer paths; absence only.
    complete_ancestor_id_superset: ?[]const u8 = null,
};

// Visibility is resolved only during production; no CSS enters a reader record.
// Its own-class namespace is separate from the table ancestor paint namespace.
// Producer-only text paint. Keep real element ancestry separate from inherited
// span classes: a descendant selector must never match a flattened class union.
pub const SourceSiblingElement = struct { tag: []const u8, classes: []const u8 = "", id: []const u8 = "" };
pub const SourceSiblingProof = struct {
    anchor_start: usize = 0, anchor_end: usize = 0,
    name_start: usize, name_len: usize, attrs_start: usize, attrs_len: usize,
    // Nonzero identity of the actual parent in the complete observed tree.
    parent_key: usize,
    previous: ?SourceSiblingElement,
};
// Complete ordinary list/body correspondence plus conservative API/GET Ruby
// census. This supplies only query-local negative classes, never parent edges.
pub const SourceBulletRubyProof = struct {
    line_start: usize, line_end: usize,
    ruby_start: usize, ruby_end: usize,
    classes: []const u8,
    root: *const TextElement,
};

// Complete source-line/API paragraph correspondence and every matching Ruby
// in both captured trees. Negative occurrence classes only; no physical edges.
pub const SourceInlineRubyProof = struct {
    line_start: usize, line_end: usize,
    ruby_start: usize, ruby_end: usize,
    classes: []const u8,
    root: *const TextElement,
};

pub const SourceRootChildProof = struct {
    anchor_start: usize, anchor_end: usize,
    name_start: usize, name_len: usize, attrs_start: usize, attrs_len: usize,
};
// Common parent facts for repeated closed anchors. No observed node identity,
// ordinal, sibling relation, or per-occurrence correspondence is issued.
pub const SourceRootParentProof = struct {
    anchor: SourceRootChildProof,
    candidate_count: u16,
};
// Build-only captured repair of a bare UL run immediately after an exact note.
// The following ordinary wiki list remains responsible for its body/actions.
pub const SourceLiteralUlRestoration = struct { end: usize, body_end: usize, depth: u8, items: u16 };
// Build-only complete wiki Table/cell correspondence, issued only after the
// same ordered body join has proved its enclosing literal DIV or parser root
// and every cell.
// These are source coordinates, not captured style or a reader capability.
pub const SourceWikiCellParentProof = struct {
    // Null names the proved parser-output parent, not an unknown parent.
    // The complete source/captured Table join is required in either variant.
    parent_start: ?usize,
    table_start: usize,
    table_open_end: usize,
    table_end: usize,
    row_start: usize,
    row_end: usize,
    attrs_start: usize,
    attrs_end: usize,
    body_start: usize,
    body_end: usize,
    header: bool,
};
pub const SourceLiteralDivProof = struct {
    range: SourceRootChildProof,
    parent_start: ?usize,
    restored_ul: ?SourceLiteralUlRestoration = null,
    wiki_cell_parent: ?SourceWikiCellParentProof = null,
};
// Common tag only: no captured ordinal, parent identity or positive edge.
pub const SourceDivParentTagProof = struct { range: SourceRootChildProof, candidate_count: u16, parent_tag: []const u8 };
pub const TextElement = struct {
    // Query-local negative direct-parent fact; never used for positive matching.
    source_parent_tag_nonmatch: ?[]const u8 = null,
    // Query-local negative facts from a tracked, physically authored SPAN.
    source_direct_parent_classes: ?[]const u8 = null,
    source_fragment_target_absent: bool = false,
    source_nonlink_element: bool = false,
    // Immediate query only. These tokens can refute local source rules in inherited box checks.
    source_inline_box_ancestor_classes: ?[]const u8 = null,
    // Query-local native constructor receipt; no root, classes or positive match.
    constructed_direct_parent: ?*const TextElement = null,
    source_literal_div: ?*const SourceLiteralDivProof = null,
    source_wiki_root_table: ?*const SourceWikiCellParentProof = null,
    source_literal_div_current: ?[]const u8 = null,
    // Independently retained actual ancestry alternative, never a class union.
    // The alternative node has no alternative itself. Page queries preserve
    // unknown whenever the two actual states differ in selector applicability.
    alternative_ancestry: ?*const TextElement = null,
    source_root_child: ?*const SourceRootChildProof = null,
    // Null is an unobserved declaration domain; empty is an observed absence.
    observed_inline_style: ?[]const u8 = null,
    // Query-local source dir attribute: null unknown, empty observed absence.
    // The overlay source resolver consumes this value without granting ancestry.
    observed_direction: ?[]const u8 = null,
    // Computed at this actual node, before descendant redefinitions. Each
    // retained API/GET path owns its own environment; null lends no variables.
    observed_custom_environment: ?CustomEnvironment = null,
    // Exact selected parser root, separate from logical parent links and class
    // supersets. Source loss clears this capability; it cannot certify adjacency.
    page_style_root: ?*const TextElement = null,
    page_style_source: ?[]const u8 = null,
    page_style_anchor: ?[]const u8 = null,
    source_sibling: ?*const SourceSiblingProof = null,
    source_sibling_scope: ?*const BoundedTextClassScope = null,
    source_sibling_source: ?[]const u8 = null,
    tag: []const u8,
    // Optional complete observed inventory for this element only. No ancestor
    // or generated-tag defaults can establish attribute absence.
    attribute_presence: ?AttributePresenceSource = null,
    // Null is an unobserved attribute domain. Empty proves typeof is absent.
    // Figure matching admits only proved Thumb/Frame format membership,
    // not an exclusive inventory of other generated RDFa tokens.
    typeof_tokens: ?[]const u8 = null,
    // Null inherits; an explicit empty or unsupported language is a barrier.
    language: ?[]const u8 = null,
    classes: []const u8 = "",
    id: []const u8 = "",
    parent: ?*const TextElement = null,
    // Explicit complete observed physical path: every parent edge is actual
    // adjacency through the document root. A logical compiler parent chain or
    // complete class inventory does not establish this build-only certificate.
    physical_ancestry_complete: bool = false,
    source_key: usize = 0,
    // Complete class-token union of all actual ancestors, including generated
    // wrappers and the selected outer domain. Null leaves that domain unknown.
    // Refusal-only: this cannot establish selector order, adjacency or matching.
    complete_ancestor_classes: ?[]const u8 = null,
    complete_ancestor_ids: ?[]const u8 = null,
    // Provenance is cache identity only; it grants no matching knowledge.
    ancestor_class_scope: ?*const BoundedTextClassScope = null,
    ancestor_class_source: ?[]const u8 = null,
    // Authoritative one-based original element-sibling position; null is unknown.
    element_index: ?u32 = null,
    // Build-only end of a selected complete content tree; fragments default unknown.
    ancestry_complete: bool = false,
};
const TextCompound = struct {
    tag: ?[]const u8 = null,
    typeof_token: ?[]const u8 = null,
    classes: []const []const u8 = &.{},
    ids: []const []const u8 = &.{},
    fn matches(self: TextCompound, element: *const TextElement) bool {
        if (self.tag) |tag| if (!std.ascii.eqlIgnoreCase(tag, element.tag)) return false;
        for (self.classes) |name| if (!Profile.hasClass(element.classes, name)) return false;
        for (self.ids) |name| if (!std.mem.eql(u8, name, element.id)) return false;
