const GeneratedFigurePseudo = enum { before, after, other };
const ObservedDynamicPseudo = enum { link, any_link, visited, hover, active, focus, focus_visible, focus_within };
const ObservedFigureLinkState = struct {
    visited: ?bool = null,
    hover: ?bool = null,
