// A complete captured DIV or closed inline child inventory can refute a necessary terminal
// sibling relation. It supplies neither a positive sibling match nor rank.
// Outer/root siblings have no such parent certificate. Reciprocal links and
// the exact first-child position keep incomplete or foreign edges unknown.
fn observedCompletePreviousRefutes(selector: GeneratedFigureSelector, nodes: []const ObservedStyleNode, subject: u32) bool {
    if (selector.chain.len == 0 or selector.chain.len > 16 or subject >= nodes.len) return false;
    const node = nodes[subject]; const parent = node.parent orelse return false;
    if (parent >= subject or !nodes[parent].known_complete_child_elements) return false;
    const closed_dd = std.ascii.eqlIgnoreCase(nodes[parent].tag, "dd") and
        (if (nodes[parent].parent) |outer| outer < parent and std.ascii.eqlIgnoreCase(nodes[outer].tag, "dl") else false);
    const closed_inline = std.ascii.eqlIgnoreCase(nodes[parent].tag, "i") or
        std.ascii.eqlIgnoreCase(nodes[parent].tag, "em") or std.ascii.eqlIgnoreCase(nodes[parent].tag, "b") or
        std.ascii.eqlIgnoreCase(nodes[parent].tag, "strong") or std.ascii.eqlIgnoreCase(nodes[parent].tag, "span");
    if (!std.ascii.eqlIgnoreCase(nodes[parent].tag, "div") and !closed_dd and !closed_inline) return false;
    if (selector.necessary_has_next) |required| {
        // The same closed parent inventory owns both sibling directions. A
        // rich subject's descendants precede its next sibling in this exact
        // source preorder; they are not candidate next element siblings.
        var following: usize = @as(usize, subject) + 1;
        var remaining: usize = 4096;
        while (following < nodes.len) : (following += 1) {
            if (remaining == 0) return false;
            remaining -= 1;
            const owner = nodes[following].parent orelse return false;
            if (owner >= following) return false;
            if (owner < subject) break;
        }
        const next: ?u32 = if (following == nodes.len) null else next: {
            const owner = nodes[following].parent.?;
            if (owner > parent) return false;
            break :next if (owner == parent) @as(u32, @intCast(following)) else null;
        };
        if (node.known_next_element_sibling != next or node.known_no_next_element_sibling != (next == null)) return false;
        if (next) |index| {
            if (nodes[index].known_previous_element_sibling != subject or nodes[index].known_no_previous_element_sibling) return false;
            if (observedFigureCompoundMatchIn(required, nodes[index], false, &remaining, false, null) == .no) return true;
        } else return true;
    }
    // necessary_has_next is extracted only from the terminal compound. Its
    // impossibility refutes the conjunction even with earlier ancestor terms.
    // Previous-combinator projection retains its original one-compound bound.
    if (selector.chain.len != 1) return false;
    if (node.known_no_previous_element_sibling) {
        return node.known_previous_element_sibling == null and subject == parent + 1 and selector.necessary_previous_sibling;
    }
    const previous = node.known_previous_element_sibling orelse return false;
    if (previous <= parent or previous >= subject or nodes[previous].parent != parent or
        nodes[previous].known_next_element_sibling != subject or nodes[previous].known_no_next_element_sibling) return false;
    const required = selector.necessary_previous_adjacent orelse return false;
    var budget: usize = 4096;
    return observedFigureCompoundMatchIn(required, nodes[previous], false, &budget, false, null) == .no;
}

fn observedStyleSelectorMatchValidated(selector: GeneratedFigureSelector, nodes: []const ObservedStyleNode, missing_media: ?u32,
    subject: u32, pseudo: ?GeneratedFigurePseudo, evaluation: ObservedFigureEvaluation) ContainerSelectorMatch
{
    if (subject >= nodes.len or selector.chain.len == 0 or selector.chain.len > 16 or selector.chain.len != selector.direct_parent.len) return .unknown;
    if (selector.pseudo != pseudo) return .no;
    if (observedCompletePreviousRefutes(selector, nodes, subject)) return .no;
    // A necessary previous-sibling relation cannot hold on the exact prefix
    // TABLE whose captured AND source graphs carry authenticated absence.
    // This grants no positive sibling match or selector specificity.
    if (selector.necessary_previous_sibling) {
        if (evaluation.table_focus) |domain|
            if (domain.sourceTableHasNoPrevious(nodes, subject)) return .no;
        if (evaluation.table_scroll_focus) |domain|
            if (domain.sourceTableHasNoPrevious(nodes, subject)) return .no;
    }
    if (evaluation.ready_sibling) |issued| {
        const caption_link = figureObservedCaptionSiblingLink(nodes, issued.caption, subject);
        if (issued.nodes.ptr == nodes.ptr and issued.nodes.len == nodes.len and (subject == issued.anchor or caption_link)) {
            if (selector.necessary_previous_sibling and nodes[subject].known_no_previous_element_sibling) return .no;
            if (caption_link) if (selector.necessary_previous_adjacent) |required|
                if (nodes[subject].known_previous_element_sibling) |previous| {
                    var previous_budget: usize = 4096;
                    if (previous < subject and nodes[previous].parent == nodes[subject].parent
                        and observedFigureCompoundMatchIn(required, nodes[previous], false, &previous_budget, false, null) == .no) return .no;
                };
            if (selector.necessary_has_next) |required| {
                if (caption_link and nodes[subject].known_no_next_element_sibling) return .no;
                if (nodes[subject].known_next_element_sibling) |next|
                    if (next > subject and next < nodes.len and nodes[subject].parent != null
                        and nodes[next].parent == nodes[subject].parent and (caption_link or next == issued.caption)) {
                        var next_budget: usize = 4096;
                        if (observedFigureCompoundMatchIn(required, nodes[next], false, &next_budget, false, null) == .no) return .no;
                    };
            }
        }
    }
    var budget: usize = 4096;
    if (selector.necessary_html_root) |root| {
        if (nodes.len == 0 or nodes[0].parent != null or !std.ascii.eqlIgnoreCase(nodes[0].tag, "html")) return .unknown;
        if (observedFigureCompoundMatchIn(root, nodes[0], true, &budget, false, null) == .no) return .no;
    }
    for (selector.necessary_sibling_ancestors) |compound| {
        var ancestor = nodes[subject].parent;
        var possible = false;
        while (ancestor) |index| : (ancestor = nodes[index].parent) {
            if (budget == 0) return .unknown;
            if (observedFigureCompoundMatchIn(compound, nodes[index], index == 0, &budget,
                evaluation.missing_width != null and missing_media == index,
                observedFigureStateAt(nodes, index, evaluation)) != .no) {
                possible = true;
                break;
            }
        }
        if (!possible) return .no;
    }
    return observedStyleMatchAt(selector, nodes, missing_media, subject, selector.chain.len - 1, &budget, evaluation);
}
fn observedFigureRuleMatchWithEffects(rule: ObservedFigureRule, context: FigureObservedContext, subject: u32, pseudo: ?GeneratedFigurePseudo, evaluation: ObservedFigureEvaluation) ContainerSelectorMatch {
    if (rule.selector) |selector| {
        const result = observedFigureSelectorMatchWithEffects(selector, context, subject, pseudo, evaluation);
        return if (result == .known and (rule.list_uncertain or !selector.syntax_known)) .unknown else result;
    }
    if (rule.weak_selector) |weak| if (observedFigureSelectorMatchWithEffects(weak, context, subject, pseudo, evaluation) == .no) return .no;
    return .unknown;
}
const ObservedFigureOwnedNodes = struct { indices: []const u32 };
// One synchronous Figure proof owns this state-independent graph result.
// It cannot escape through the public context, computed nodes or wire data.
// Keep its allocator outside the per-state scratch arenas. Inputs are borrowed
// for the operation; public entry wrappers always validate a fresh context.
const ObservedFigureCandidateCounts = struct {
