}
fn observedFigureUnknownRank(conditions: []const []const u8) bool {
    for (conditions) |condition| if (atRuleNamed(condition, "layer") or atRuleNamed(condition, "scope")) return true;
    return false;
}
const ObservedFigureDeclaration = struct {
