    defer a.free(candidates);
    var definite = false;
    for (candidates) |candidate| definite = definite or !candidate.uncertain;
    var selected: ?bool = if (definite) null else false;
    for (candidates) |candidate| {
        if (candidate.rank_unknown) return null;
