    };
    const NumericValue = struct {
        number: bool,
        scalar: f64 = 0,
        px: f64 = 0,
        em: f64 = 0,
        percent: f64 = 0,
        fn finite(self: NumericValue) bool {
            return std.math.isFinite(self.scalar) and std.math.isFinite(self.px) and
