                    if (!Profile.hasClass(classes, required)) continue :rules;
            }
            if (selector.required_own_attribute) |name| if (self.attribute_presence) |attributes| {
                if (attributes.get(attributes.ctx, name) == .absent) continue;
            };
            if (selector.tag) |tag| if (!std.ascii.eqlIgnoreCase(tag, self.tag)) continue;
            if (selector.id) |id| if (!std.mem.eql(u8, id, self.id)) continue;
            for (selector.classes) |required| {
                if (!Profile.hasClass(self.classes, self.profile.display_classes[required])) continue :rules;
            }
            return .{ .css = rule.css, .specificity = selector.specificity, .order = rule.order, .uncertain = selector.uncertain };
        }
        return null;
    }
};

pub const DisplayCascade = struct {
    hidden: ?bool = false,
    seen: bool = false,
    priority: Priority = .{},
    inline_style: bool = false,

    pub fn consider(self: *DisplayCascade, hidden: ?bool, important: bool, specificity: u32, order: u32, inline_style: bool) void {
        const next: Priority = .{ .important = important, .specificity = specificity, .order = order };
        if (self.seen) {
            if (important == self.priority.important and inline_style != self.inline_style) {
                if (!inline_style) return;
            } else if (!next.wins(self.priority)) return;
        }
        self.* = .{ .hidden = hidden, .seen = true, .priority = next, .inline_style = inline_style };
    }
};

/// The output medium is a producer choice, independent of page or skin provenance.
pub const ReadingTarget = enum { unknown, screen, print };

/// Producer-only static table styles. No selector or declaration text enters a reader.
pub const Profile = struct {
    reading_target: ReadingTarget = .unknown,
    // Selected views borrow both this immutable page profile and their global
    // parent. No selected view owns or deinitializes either arena.
    page_style_parent: ?*const Profile = null,
    custom_properties: ?*const CustomProfile = null,
    arena: std.heap.ArenaAllocator,
    sources: []const SourceRange = &.{},
    // Exact parser inputs, owned by this profile arena. Used only when a selected
    // page adds its authored sheets; source metadata alone cannot rebuild rules.
    retained_sources: []const Source = &.{},
    rules: []const Rule,
    classes: []const []const u8,
    ancestor_classes: []const []const u8 = &.{},
    admitted_rule_numbers: []const u32,
    has_unsupported_rules: bool,
    globally_unresolved: bool = false,
    text_rules: []const TextRule = &.{},
    observed_figure_rules: []const ObservedFigureRule = &.{},
    block_rules: []const TextRule = &.{},
    container_rules: []const ContainerRule = &.{},
    figure_rules: []const TextRule = &.{},
    missing_link_custom_rules: []const TextRule = &.{},
    display_rules: []const DisplayRule = &.{},
    display_classes: []const []const u8 = &.{},

    pub fn displayRules(self: *const Profile, tag: []const u8, classes: []const u8, id: []const u8) DisplayIterator {
        return .{ .profile = self, .tag = tag, .id = id, .classes = classes };
    }

    pub fn resolveAlignment(self: *const Profile, a: std.mem.Allocator, tag: []const u8, classes: []const u8, id: []const u8, legacy_align: ?[]const u8, css: []const u8) std.mem.Allocator.Error!AlignmentResolution {
        return self.resolveAlignmentWithAncestors(a, tag, classes, id, legacy_align, css, null);
    }
    /// Reuse only complete ancestor-class absence. A present class, parent
    /// pointer or class union never establishes selector matching or adjacency.
    pub fn resolveAlignmentIn(self: *const Profile, a: std.mem.Allocator, element: *const TextElement, legacy_align: ?[]const u8, css: []const u8) std.mem.Allocator.Error!AlignmentResolution {
        if (self.page_style_parent != null) {
            if (element.page_style_root == null or css.len > max_css_bytes) return .{ .specified = true, .unresolved = true };
            const matched = try self.containerRuleMatchesIn(a, element);
            defer a.free(matched.rules);
            if (matched.unresolved) return .{ .specified = true, .unresolved = true };
            var cascade_value: AlignmentCascade = .{};
            if (presentationalTextAlign(legacy_align)) |alignment| cascade_value.consider(.{ .property = .text_align, .value = .{ .align_value = alignment }, .important = false, .order = 0 }, 0, false, false);
            for (matched.rules) |rule| try cascade_value.declarations(a, rule.css, rule.specificity, rule.order,
                rule.match == .unknown or rule.viewport != .all or rule.rank_unknown, false);
            try cascade_value.declarations(a, css, 0, max_rules * 1024, false, true);
            return cascade_value.resolution;
        }
        return self.resolveAlignmentWithAncestors(a, element.tag, element.classes, element.id, legacy_align, css, element.complete_ancestor_classes);
    }
    fn resolveAlignmentWithAncestors(self: *const Profile, a: std.mem.Allocator, tag: []const u8, classes: []const u8, id: []const u8, legacy_align: ?[]const u8, css: []const u8, ancestor_classes: ?[]const u8) std.mem.Allocator.Error!AlignmentResolution {
        if (self.globally_unresolved or css.len > max_css_bytes) return .{ .specified = true, .unresolved = true };
        var cascade_value: AlignmentCascade = .{};
        if (presentationalTextAlign(legacy_align)) |alignment| cascade_value.consider(.{ .property = .text_align, .value = .{ .align_value = alignment }, .important = false, .order = 0 }, 0, false, false);
        var matches = self.displayRules(tag, classes, id);
        matches.complete_ancestor_classes = ancestor_classes;
        while (matches.next()) |matched| try cascade_value.declarations(a, matched.css, matched.specificity, matched.order, matched.uncertain, false);
        try cascade_value.declarations(a, css, 0, max_rules * 1024, false, true);
        return cascade_value.resolution;
    }

    pub fn resolveFontSize(self: *const Profile, a: std.mem.Allocator, tag: []const u8, classes: []const u8, id: []const u8, css: []const u8) std.mem.Allocator.Error!?FontSizeValue {
        return self.resolveFontSizeWithAttributes(a, tag, classes, id, css, null);
    }

    pub fn resolveFontSizeWithAttributes(self: *const Profile, a: std.mem.Allocator, tag: []const u8, classes: []const u8, id: []const u8, css: []const u8, attributes: ?AttributePresenceSource) std.mem.Allocator.Error!?FontSizeValue {
        if (self.globally_unresolved or css.len > max_css_bytes) return .unknown;
        var cascade_value: FontCascade = .{};
        var matches = self.displayRules(tag, classes, id);
        matches.attribute_presence = attributes;
        while (matches.next()) |matched| try cascade_value.declarations(a, matched.css, matched.specificity, matched.order, matched.uncertain, false);
        try cascade_value.declarations(a, css, 0, max_rules * 1024, false, true);
        return cascade_value.value;
    }

    /// Uses the same typed ancestor selector proof as text paint. Necessary
    /// own-attribute absence may refute an unsupported candidate, never admit it.
    pub fn resolveFontSizeIn(self: *const Profile, a: std.mem.Allocator, element: *const TextElement, css: []const u8, attributes: ?AttributePresenceSource) std.mem.Allocator.Error!?FontSizeValue {
        return self.resolveFontSizeInFor(false, a, element, css, attributes);
    }

    pub fn resolveObservedCellFontSizeIn(self: *const Profile, a: std.mem.Allocator, element: *const TextElement, css: []const u8, attributes: ?AttributePresenceSource) std.mem.Allocator.Error!?ObservedFontSizeValue {
        return self.resolveFontSizeInFor(true, a, element, css, attributes);
    }

    fn resolveFontSizeInFor(self: *const Profile, comptime observed_lengths: bool, a: std.mem.Allocator, element: *const TextElement, css: []const u8, attributes: ?AttributePresenceSource) std.mem.Allocator.Error!?(if (observed_lengths) ObservedFontSizeValue else FontSizeValue) {
        if (self.globally_unresolved or (self.page_style_parent != null and element.page_style_root == null) or css.len > max_css_bytes) return .unknown;
        var cascade_value: FontCascadeFor(observed_lengths) = .{};
        for (self.text_rules) |rule| {
            const matched = rule.selector.matchIn(element, self.page_style_parent != null);
            if (matched == .no) continue;
            if (rule.selector.required_own_attribute) |name| if (attributes) |known| {
                if (known.get(known.ctx, name) == .absent) continue;
            };
            try cascade_value.declarations(a, rule.css, rule.selector.specificity, rule.order, rule.selector.uncertain or matched == .unknown, false);
        }
        try cascade_value.declarations(a, css, 0, max_rules * 1024, false, true);
        return cascade_value.value;
    }

    /// The caller owns the result array; declarations remain borrowed from this
    /// build-time profile. No selector or CSS text belongs in a reader record.
    pub fn containerRuleMatchesIn(self: *const Profile, a: std.mem.Allocator, element: *const TextElement) std.mem.Allocator.Error!ContainerRuleMatches {
        if (self.globally_unresolved or (self.page_style_parent != null and element.page_style_root == null)) return .{ .unresolved = true };
        var rules: std.ArrayList(ContainerRuleMatch) = .empty;
        errdefer rules.deinit(a);
        for (self.container_rules) |rule| {
            const matched = rule.selector.matchIn(element, self.page_style_parent != null);
            if (matched == .no) continue;
            const specificity = if (element.source_sibling_scope != null and rule.selector.adjacent_sibling != null and matched == .known)
                rule.selector.adjacent_sibling.?.specificity else rule.selector.specificity;
            try rules.append(a, .{ .closed_row_attribute = rule.selector.completeOwnAttribute(), .css = rule.css, .order = rule.order, .specificity = specificity,
                .match = matched, .viewport = rule.viewport, .rank_unknown = rule.rank_unknown, .provenance = rule.provenance });
        }
        return .{ .rules = try rules.toOwnedSlice(a) };
    }

    fn containerRuleMatchesForReadyPreflightIn(self: *const Profile, a: std.mem.Allocator, element: *const TextElement, complete_classes: ?[]const u8, complete_ids: ?[]const u8) std.mem.Allocator.Error!ContainerRuleMatches {
        if (self.globally_unresolved or (self.page_style_parent != null and element.page_style_root == null)) return .{ .unresolved = true };
        var rules: std.ArrayList(ContainerRuleMatch) = .empty;
        errdefer rules.deinit(a);
        for (self.container_rules) |rule| {
            if (complete_classes) |classes| if (rule.selector.absentFromCompleteClasses(classes)) continue;
            if (complete_ids) |ids| if (rule.selector.absentFromCompleteIds(ids)) continue;
            const matched = rule.selector.matchIn(element, self.page_style_parent != null);
            if (matched == .no) continue;
            const specificity = if (element.source_sibling_scope != null and rule.selector.adjacent_sibling != null and matched == .known)
                rule.selector.adjacent_sibling.?.specificity else rule.selector.specificity;
            try rules.append(a, .{ .closed_row_attribute = rule.selector.completeOwnAttribute(), .css = rule.css, .order = rule.order, .specificity = specificity,
                .match = matched, .viewport = rule.viewport, .rank_unknown = rule.rank_unknown, .provenance = rule.provenance,
                .closed_figure_domain = rule.selector.requiresFigureDomain() });
        }
        return .{ .rules = try rules.toOwnedSlice(a) };
    }

    pub fn relativeContextPolicyPresentIn(self: *const Profile, a: std.mem.Allocator, element: *const TextElement, css: []const u8) std.mem.Allocator.Error!bool {
        if (self.globally_unresolved or try hasRelativeContextDeclarationsAlloc(a, css)) return true;
        const matched = try self.containerRuleMatchesIn(a, element);
        defer a.free(matched.rules);
        if (matched.unresolved) return true;
        for (matched.rules) |rule| if (try hasRelativeContextDeclarationsAlloc(a, rule.css)) return true;
        return false;
    }

    pub fn columnFlowStylesheetPolicyAbsent(self: *const Profile, a: std.mem.Allocator) std.mem.Allocator.Error!bool {
        if (self.globally_unresolved) return false;
        for (self.container_rules) |rule| if (try hasColumnDescendantDeclarationsAlloc(a, rule.css)) return false;
        return true;
    }

    // This query covers only the closed MissingLinkPaint palette, decoration
    // and focus contract. The caller separately checks every actual ancestor;
    // it is not a font, layout, visibility or whole-page fidelity certificate.
    pub fn missingLinkAdditionalPaintUnchangedIn(self: *const Profile, a: std.mem.Allocator, element: *const TextElement) std.mem.Allocator.Error!bool {
        return (try self.missingLinkAdditionalPaintBlockerIn(a, element)) == null;
    }
    // The bool proof and its diagnostic share the exact matching and declaration
    // walk. Every returned slice belongs to this Profile until deinit().
    pub fn missingLinkAdditionalPaintBlockerIn(self: *const Profile, a: std.mem.Allocator, element: *const TextElement) std.mem.Allocator.Error!?MissingLinkPaintBlocker {
        const matches = try self.containerRuleMatchesIn(a, element);
        defer a.free(matches.rules);
        if (matches.unresolved) return .{ .reason = .global_unresolved };
        for (matches.rules) |rule| {
            var at: usize = 0;
            while (true) {
                const start = at;
                const raw = (try nextDeclarationAlloc(a, rule.css, &at)) orelse break;
                defer a.free(raw);
                if (trim(raw).len == 0) continue;
                const witness: MissingLinkPaintBlocker = .{ .reason = .declaration, .rule = rule,
                    .declaration = rule.css[start..at], .declaration_offset = start };
                const colon = std.mem.indexOfScalar(u8, raw, ':') orelse {
                    var malformed = witness; malformed.reason = .malformed_declaration; return malformed;
                };
                const name = trim(raw[0..colon]);
                const value = customPriority(raw[colon + 1 ..]);
                if (value.unknown) {
                    var unknown = witness; unknown.reason = .unknown_priority; return unknown;
                }
                if (customName(name) and !missingLinkCustomProperty(name)) continue;
                // These affect glyph shaping, which remains a separate text
                // obligation. They cannot set the closed paint fields above.
                if (std.ascii.eqlIgnoreCase(name, "font-feature-settings") or
                    std.ascii.eqlIgnoreCase(name, "-moz-font-feature-settings") or
                    std.ascii.eqlIgnoreCase(name, "-webkit-font-feature-settings")) continue;
                // Tab stops affect inherited text layout, not these closed link
                // paint fields. Keep selector uncertainty and layout refusal.
                if (std.ascii.eqlIgnoreCase(name, "tab-size") or
                    std.ascii.eqlIgnoreCase(name, "-moz-tab-size") or
                    std.ascii.eqlIgnoreCase(name, "-o-tab-size")) continue;
                // The frame floor belongs to Figure geometry, not link paint.
                // Its separate cascade must still represent or refuse it.
                if (std.ascii.eqlIgnoreCase(name, "min-width")) continue;
                return witness;
            }
        }
        return null;
    }
    // Refusal-only query over the same all-rule inventory and declaration
    // scanner as ordinary Container resolution. A match here never issues a
    // parent edge or computed inherited state. Custom values themselves have no
    // effect; their consuming declarations are still visited normally.
    pub fn pageAncestorEffectBlockerIn(self: *const Profile, a: std.mem.Allocator, root: ?*const TextElement) std.mem.Allocator.Error!?PageAncestorEffectBlocker {
        return self.pageAncestorEffectBlockerWithReadyFiguresIn(a, root, null);
    }

    fn pageAncestorEffectBlockerWithReadyFiguresIn(self: *const Profile, a: std.mem.Allocator, root: ?*const TextElement, ready: ?ClosedReadyFigureProof) std.mem.Allocator.Error!?PageAncestorEffectBlocker {
        return self.pageAncestorEffectBlockerWithFigureObligationsIn(a, root, null, ready, null);
    }
    fn pageAncestorEffectBlockerWithFigureObligationsIn(self: *const Profile, a: std.mem.Allocator, root: ?*const TextElement, figures: ?ClosedMissingFigureProof, ready: ?ClosedReadyFigureProof, complete_classes: ?[]const u8) std.mem.Allocator.Error!?PageAncestorEffectBlocker {
        return self.pageAncestorEffectBlockerWithRowColorObligationIn(a, root, figures, ready, complete_classes, null, null);
    }

    fn pageAncestorEffectBlockerWithRowColorObligationIn(self: *const Profile, a: std.mem.Allocator, root: ?*const TextElement, figures: ?ClosedMissingFigureProof, ready: ?ClosedReadyFigureProof, complete_classes: ?[]const u8, row_colors: ?*const ClosedRowColorProof, row_color_required: ?*bool) std.mem.Allocator.Error!?PageAncestorEffectBlocker {
        return self.pageAncestorEffectBlockerWithRowColorAndStaticMotionIn(a, root, figures, ready, complete_classes, row_colors, row_color_required, null, null, null);
    }

    fn pageAncestorEffectBlockerWithRowColorAndStaticMotionIn(self: *const Profile, a: std.mem.Allocator, root: ?*const TextElement, figures: ?ClosedMissingFigureProof, ready: ?ClosedReadyFigureProof, complete_classes: ?[]const u8, row_colors: ?*const ClosedRowColorProof, row_color_required: ?*bool, motion: ?PageStaticMotionProof, counters: ?*const UnobservedCounterResetProof, complete_ids: ?[]const u8) std.mem.Allocator.Error!?PageAncestorEffectBlocker {
        return self.pageAncestorEffectBlockerWithSourceFocusIn(a, root, figures, ready, complete_classes, row_colors, row_color_required, motion, counters, complete_ids, null, null, null);
    }

    fn pageAncestorEffectBlockerWithSourceFocusIn(self: *const Profile, a: std.mem.Allocator, root: ?*const TextElement, figures: ?ClosedMissingFigureProof, ready: ?ClosedReadyFigureProof, complete_classes: ?[]const u8, row_colors: ?*const ClosedRowColorProof, row_color_required: ?*bool, motion: ?PageStaticMotionProof, counters: ?*const UnobservedCounterResetProof, complete_ids: ?[]const u8, focus: ?*const PageSourceFocusProof, focus_required: ?*bool, inline_owner: ?*const PageSourceInlineOwnerProof) std.mem.Allocator.Error!?PageAncestorEffectBlocker {
        const motion_covered = if (motion) |proof| proof.styles == self and proof.root == root and proof.source.len != 0 else false;
        const missing_covered = if (figures) |proof| proof.styles == self and proof.root == root and proof.source.len != 0 and proof.operations > 0 and proof.operations <= 64 else false;
        const figures_covered = missing_covered or (if (ready) |proof| proof.styles == self and proof.root == root and proof.source.len != 0 and proof.operations > 0 and proof.operations <= 64 else false);
        if (self.page_style_parent == null) return null;
        if (self.globally_unresolved) return .{ .reason = .global_unresolved };
        var ancestor = root orelse return .{ .reason = .missing_root };
        var depth: usize = 0;
        while (true) : (depth += 1) {
            if (depth == 64) return .{ .reason = .depth_limit, .ancestor_depth = depth };
            var query = ancestor.*;
            // This temporary marker only enables a potential-match query. Its
            // self fallback cannot authorize anything: every non-no result is
            // retained as a refusal. Do not export this node to any resolver.
            query.page_style_root = &query;
            query.complete_ancestor_classes = null;
            query.complete_ancestor_ids = null;
            query.source_literal_div = null;
            query.source_literal_div_current = null;
            query.source_sibling = null;
            query.source_sibling_scope = null;
            query.source_sibling_source = null;
            query.ancestry_complete = false;
            query.physical_ancestry_complete = false;
            const matches = try self.containerRuleMatchesForReadyPreflightIn(a, &query, complete_classes, complete_ids);
            defer a.free(matches.rules);
            if (matches.unresolved) return .{ .reason = .global_unresolved, .ancestor_depth = depth };
            for (matches.rules) |rule| {
                if (figures_covered and rule.closed_figure_domain) continue;
                var position: usize = 0;
                while (true) {
                    const start = position;
                    const raw = (try nextDeclarationAlloc(a, rule.css, &position)) orelse break;
                    defer a.free(raw);
                    if (trim(raw).len == 0) continue;
                    if (std.mem.indexOfScalar(u8, raw, ':')) |colon| {
                        const name = trim(raw[0..colon]);
                        const value = customPriority(raw[colon + 1 ..]);
                        if (customName(name) and !value.unknown) continue;
                        if (motion_covered and !value.unknown and pageStaticMotionProperty(name)) continue;
                        if (self.unobservedCounterDeclarationCovered(root, counters, rule.css, rule.order, rule.provenance, name, value)) continue;
                        if (self.pageSourceFocusDeclarationCovered(root, focus, rule.css, rule.order, rule.provenance, name, value) or
                            self.pageSourceInlineOwnerDeclarationCovered(root, focus, inline_owner, rule.css, rule.order, rule.provenance, name, value)) {
                            if (focus_required) |required| required.* = true;
                            continue;
                        }
                        if (!rule.rank_unknown and rule.viewport == .all and self.rowColorDeclarationCovered(root, row_colors, rule.closed_row_attribute, name, value.unknown)) {
                            if (row_color_required) |required| if (row_colors.?.owners.len != 0) { required.* = true; };
                            continue;
                        }
                    }
                    return .{ .reason = .declaration, .ancestor_depth = depth,
                        .rule = rule, .declaration = rule.css[start..position], .declaration_offset = start };
                }
            }
            ancestor = ancestor.parent orelse return null;
        }
    }

    // A distant-root capability does not describe every generated intermediate
    // node. Until an operation issues that path, any ordinary declaration may
    // affect such a node. This conservative boundary is deliberately separate
    // from own-element resolution: own fields can be compiled while the normal
    // report retains the unrepresented ancestor effect. No selector is claimed
    // to match a real node by this second witness.
    pub fn pageUnprovedInheritanceBlockerIn(self: *const Profile, a: std.mem.Allocator, root: ?*const TextElement) std.mem.Allocator.Error!?PageAncestorEffectBlocker {
        return self.pageUnprovedInheritanceBlockerWithReadyFiguresIn(a, root, null);
    }

    pub fn pageUnprovedInheritanceBlockerWithReadyFiguresIn(self: *const Profile, a: std.mem.Allocator, root: ?*const TextElement, ready: ?ClosedReadyFigureProof) std.mem.Allocator.Error!?PageAncestorEffectBlocker {
        return self.pageUnprovedInheritanceBlockerWithFigureObligationsIn(a, root, null, ready);
    }
    pub fn pageUnprovedInheritanceBlockerWithFigureObligationsIn(self: *const Profile, a: std.mem.Allocator, root: ?*const TextElement, figures: ?ClosedMissingFigureProof, ready: ?ClosedReadyFigureProof) std.mem.Allocator.Error!?PageAncestorEffectBlocker {
        return self.pageUnprovedInheritanceBlockerWithCompleteClassesIn(a, root, figures, ready, null);
    }

    pub fn pageUnprovedInheritanceBlockerWithCompleteClassesIn(self: *const Profile, a: std.mem.Allocator, root: ?*const TextElement, figures: ?ClosedMissingFigureProof, ready: ?ClosedReadyFigureProof, complete_classes: ?[]const u8) std.mem.Allocator.Error!?PageAncestorEffectBlocker {
        return self.pageUnprovedInheritanceBlockerWithCompleteClassesAndRowColorObligationIn(a, root, figures, ready, complete_classes, null, null);
    }

    pub fn pageUnprovedInheritanceBlockerWithCompleteClassesAndRowColorObligationIn(self: *const Profile, a: std.mem.Allocator, root: ?*const TextElement, figures: ?ClosedMissingFigureProof, ready: ?ClosedReadyFigureProof, complete_classes: ?[]const u8, row_colors: ?*const ClosedRowColorProof, row_color_required: ?*bool) std.mem.Allocator.Error!?PageAncestorEffectBlocker {
        return self.pageUnprovedInheritanceBlockerWithCompleteClassesRowColorAndStaticMotionIn(a, root, figures, ready, complete_classes, row_colors, row_color_required, null);
    }

    pub fn pageUnprovedInheritanceBlockerWithCompleteClassesRowColorAndStaticMotionIn(self: *const Profile, a: std.mem.Allocator, root: ?*const TextElement, figures: ?ClosedMissingFigureProof, ready: ?ClosedReadyFigureProof, complete_classes: ?[]const u8, row_colors: ?*const ClosedRowColorProof, row_color_required: ?*bool, motion: ?PageStaticMotionProof) std.mem.Allocator.Error!?PageAncestorEffectBlocker {
        return self.pageUnprovedInheritanceBlockerWithClosedCountersIn(a, root, figures, ready, complete_classes, row_colors, row_color_required, motion, null, null);
    }
    pub fn pageUnprovedInheritanceBlockerWithClosedCountersIn(self: *const Profile, a: std.mem.Allocator, root: ?*const TextElement, figures: ?ClosedMissingFigureProof, ready: ?ClosedReadyFigureProof, complete_classes: ?[]const u8, row_colors: ?*const ClosedRowColorProof, row_color_required: ?*bool, motion: ?PageStaticMotionProof, counters: ?*const UnobservedCounterResetProof, complete_ids: ?[]const u8) std.mem.Allocator.Error!?PageAncestorEffectBlocker {
        return self.pageUnprovedInheritanceBlockerWithClosedCountersAndSourceFocusIn(a, root, figures, ready, complete_classes, row_colors, row_color_required, motion, counters, complete_ids, null, null);
    }

    pub fn pageUnprovedInheritanceBlockerWithClosedCountersAndSourceFocusIn(self: *const Profile, a: std.mem.Allocator, root: ?*const TextElement, figures: ?ClosedMissingFigureProof, ready: ?ClosedReadyFigureProof, complete_classes: ?[]const u8, row_colors: ?*const ClosedRowColorProof, row_color_required: ?*bool, motion: ?PageStaticMotionProof, counters: ?*const UnobservedCounterResetProof, complete_ids: ?[]const u8, focus: ?*const PageSourceFocusProof, focus_required: ?*bool) std.mem.Allocator.Error!?PageAncestorEffectBlocker {
        return self.pageUnprovedInheritanceBlockerWithSourceInlineOwnerIn(a, root, figures, ready, complete_classes,
            row_colors, row_color_required, motion, counters, complete_ids, focus, focus_required, null);
    }

    pub fn pageUnprovedInheritanceBlockerWithSourceInlineOwnerIn(self: *const Profile, a: std.mem.Allocator, root: ?*const TextElement, figures: ?ClosedMissingFigureProof, ready: ?ClosedReadyFigureProof, complete_classes: ?[]const u8, row_colors: ?*const ClosedRowColorProof, row_color_required: ?*bool, motion: ?PageStaticMotionProof, counters: ?*const UnobservedCounterResetProof, complete_ids: ?[]const u8, focus: ?*const PageSourceFocusProof, focus_required: ?*bool, inline_owner: ?*const PageSourceInlineOwnerProof) std.mem.Allocator.Error!?PageAncestorEffectBlocker {
        const motion_covered = if (motion) |proof| proof.styles == self and proof.root == root and proof.source.len != 0 else false;
        const missing_covered = if (figures) |proof| proof.styles == self and proof.root == root and proof.source.len != 0 and proof.operations > 0 and proof.operations <= 64 else false;
        const figures_covered = missing_covered or (if (ready) |proof| proof.styles == self and proof.root == root and proof.source.len != 0 and proof.operations > 0 and proof.operations <= 64 else false);
        if (try self.pageAncestorEffectBlockerWithSourceFocusIn(a, root, figures, ready, complete_classes, row_colors, row_color_required, motion, counters, complete_ids, focus, focus_required, inline_owner)) |failure| return failure;
        if (self.page_style_parent == null) return null;
        for (self.container_rules) |rule| {
            if (complete_classes) |classes| if (rule.selector.absentFromCompleteClasses(classes)) continue;
            if (complete_ids) |ids| if (rule.selector.absentFromCompleteIds(ids)) continue;
            if (figures_covered and rule.selector.requiresFigureDomain()) continue;
            var position: usize = 0;
            while (true) {
                const start = position;
                const raw = (try nextDeclarationAlloc(a, rule.css, &position)) orelse break;
                defer a.free(raw);
                if (trim(raw).len == 0) continue;
                if (std.mem.indexOfScalar(u8, raw, ':')) |colon| {
                    const name = trim(raw[0..colon]);
                    const value = customPriority(raw[colon + 1 ..]);
                    if (customName(name) and !value.unknown) continue;
                    if (motion_covered and !value.unknown and pageStaticMotionProperty(name)) continue;
                    if (self.unobservedCounterDeclarationCovered(root, counters, rule.css, rule.order, rule.provenance, name, value)) continue;
                        if (self.pageSourceFocusDeclarationCovered(root, focus, rule.css, rule.order, rule.provenance, name, value) or
                            self.pageSourceInlineOwnerDeclarationCovered(root, focus, inline_owner, rule.css, rule.order, rule.provenance, name, value)) {
                            if (focus_required) |required| required.* = true;
                            continue;
                        }
                    if (!rule.rank_unknown and rule.viewport == .all and self.rowColorDeclarationCovered(root, row_colors, rule.selector.completeOwnAttribute(), name, value.unknown)) {
                        if (row_color_required) |required| if (row_colors.?.owners.len != 0) { required.* = true; };
                        continue;
                    }
                }
                return .{ .reason = .unproved_ancestor_path,
                    .rule = .{ .css = rule.css, .order = rule.order, .specificity = rule.selector.specificity,
                        .match = .unknown, .viewport = rule.viewport, .rank_unknown = rule.rank_unknown, .provenance = rule.provenance },
                    .declaration = rule.css[start..position], .declaration_offset = start };
            }
        }
        return null;
    }

    fn pageSourceInlineOwnerDeclarationCovered(self: *const Profile, root: ?*const TextElement,
        focus: ?*const PageSourceFocusProof, maybe: ?*const PageSourceInlineOwnerProof,
        css: []const u8, order: u32, provenance: ?ContainerRuleProvenance,
        property: []const u8, value: CustomPriorityValue) bool
    {
        const proof = maybe orelse return false;
        if (proof.focus != focus or proof.focus.styles != self or proof.focus.root != root or
            !pageSourceInlineOwnerCurrent(proof)) return false;
        const origin = provenance orelse return false;
        for (proof.covered_rules) |index| {
            if (index >= self.container_rules.len) return false;
            const rule = self.container_rules[index];
            const retained = rule.provenance orelse return false;
            if (rule.css.ptr == css.ptr and rule.css.len == css.len and rule.order == order and
                origin.source_index == retained.source_index and origin.css_byte_start == retained.css_byte_start and
                std.mem.eql(u8, origin.selector, retained.selector)) {
                // The constructor checked every node/pseudo in both graphs.
                // Currentness above retains those exact inventories and the
                // independent absent-index snapshot; do not repeat that work
                // for each declaration of the same rule.
                for (proof.absent_rules) |absent| if (absent == index) return true;
                return !value.unknown and sourceInlineOwnerProperty(property) and !rule.rank_unknown and rule.viewport == .all;
            }
        }
        return false;
    }

    fn pageSourceFocusDeclarationCovered(self: *const Profile, root: ?*const TextElement,
        maybe: ?*const PageSourceFocusProof, css: []const u8, order: u32, provenance: ?ContainerRuleProvenance,
        property: []const u8, value: CustomPriorityValue) bool
    {
        if (value.unknown or !std.ascii.eqlIgnoreCase(property, "outline-color")) return false;
        const proof = maybe orelse return false;
        if (proof.styles != self or proof.root != root or !pageSourceFocusCurrent(proof)) return false;
        const origin = provenance orelse return false;
        for (proof.covered_rules) |index| {
            if (index >= self.container_rules.len) return false;
            const rule = self.container_rules[index];
            const retained = rule.provenance orelse return false;
            if (!rule.rank_unknown and rule.viewport == .all and rule.css.ptr == css.ptr and rule.css.len == css.len and rule.order == order and
                origin.source_index == retained.source_index and origin.css_byte_start == retained.css_byte_start and
                std.mem.eql(u8, origin.selector, retained.selector)) return true;
        }
        return false;
    }

    fn unobservedCounterDeclarationCovered(self: *const Profile, root: ?*const TextElement,
        counters: ?*const UnobservedCounterResetProof, css: []const u8, order: u32, provenance: ?ContainerRuleProvenance,
        property: []const u8, value: CustomPriorityValue) bool
    {
        const proof = counters orelse return false;
        if (proof.styles != self or proof.root != root or !unobservedCounterSourceCurrent(proof) or
            proof.rules.ptr != self.container_rules.ptr or proof.rules.len != self.container_rules.len or
            proof.resets.len == 0 or proof.resets.len > 64 or value.unknown or !std.ascii.eqlIgnoreCase(property, "counter-reset")) return false;
        const name = singleCounterReset(value.value) orelse return false;
        const origin = provenance orelse return false;
        for (proof.resets) |entry| {
            if (entry.rule >= self.container_rules.len or !std.mem.eql(u8, entry.name, name)) continue;
            const rule = self.container_rules[entry.rule];
            const retained = rule.provenance orelse continue;
            if (!rule.rank_unknown and rule.viewport == .all and rule.css.ptr == css.ptr and rule.css.len == css.len and rule.order == order and
                origin.source_index == retained.source_index and origin.css_byte_start == retained.css_byte_start and
                std.mem.eql(u8, origin.selector, retained.selector)) return true;
        }
        return false;
    }

    fn rowColorDeclarationCovered(self: *const Profile, root: ?*const TextElement, maybe: ?*const ClosedRowColorProof, attribute: ?[]const u8, property: []const u8, unknown_priority: bool) bool {
        const proof = maybe orelse return false;
        const name = attribute orelse return false;
        return proof.styles == self and proof.root == root and proof.source.len != 0 and proof.owners.len <= 4096 and
            (if (proof.absent_source != null) closedRowColorAbsenceValid(proof) else proof.owners.len > 0) and
            std.mem.eql(u8, proof.attribute, "bgcolor") and std.ascii.eqlIgnoreCase(name, proof.attribute) and
            !unknown_priority and std.ascii.eqlIgnoreCase(property, "color");
    }

    pub fn resolvePositionedContainerIn(self: *const Profile, a: std.mem.Allocator,
        element: *const TextElement, css: []const u8, environment: ?CustomEnvironment,
        inherited_font: ?types.InlineFontSnapshot) !?ContainerResolution
    {
        return self.resolvePositionedContainerInDiagnosed(a, element, css, environment, inherited_font, null);
    }
    pub fn resolvePositionedContainerInDiagnosed(self: *const Profile, a: std.mem.Allocator,
        element: *const TextElement, css: []const u8, environment: ?CustomEnvironment,
        inherited_font: ?types.InlineFontSnapshot, diagnostic: ?*PositionedContainerQueryDiagnostic) !?ContainerResolution
    {
        return self.resolvePositionedContainerWithAbsenceDiagnosed(a, element, css, environment, inherited_font, null, diagnostic);
    }
    pub fn resolvePositionedContainerWithAbsenceDiagnosed(self: *const Profile, a: std.mem.Allocator,
        element: *const TextElement, css: []const u8, environment: ?CustomEnvironment,
        inherited_font: ?types.InlineFontSnapshot, absence: ?PositionedContainerAbsence,
        diagnostic: ?*PositionedContainerQueryDiagnostic) !?ContainerResolution
    {
        if (diagnostic) |sink| sink.* = .{};
        return resolvePositionedContainerFromText(a, self, element, css, environment, inherited_font, absence, diagnostic);
    }

    pub fn resolveContainerIn(self: *const Profile, a: std.mem.Allocator, element: *const TextElement, css: []const u8) std.mem.Allocator.Error!ContainerResolution {
        return self.resolveContainerInWithCustom(a, element, css, null);
    }

    pub fn resolveContainerInWithCustom(self: *const Profile, a: std.mem.Allocator, element: *const TextElement, css: []const u8, environment: ?CustomEnvironment) std.mem.Allocator.Error!ContainerResolution {
        return self.resolveContainerInWithInheritance(a, element, css, environment, false);
    }

    /// The ordinary producer may consume border-collapse here only after its
    /// complete per-element inherited cascade has produced a concrete value.
    pub fn resolveContainerInWithInheritance(self: *const Profile, a: std.mem.Allocator, element: *const TextElement, css: []const u8, environment: ?CustomEnvironment, border_collapse_consumed: bool) std.mem.Allocator.Error!ContainerResolution {
        if (self.globally_unresolved or css.len > max_css_bytes) return .{ .unresolved = true };
        const matched = try self.containerRuleMatchesIn(a, element);
        defer a.free(matched.rules);
        if (matched.unresolved) return .{ .unresolved = true };
        var base = try containerCascadeAt(a, matched.rules, css, null, environment, border_collapse_consumed);
        if (base.unresolved) return base;
        // Preserve the existing bounded selector/cascade work. Semantic changes
        // become the already represented descending viewport bands below.
        var thresholds: [32]u32 = undefined;
        var count: usize = 0;
        for (matched.rules) |rule| {
            if (rule.viewport != .screen_max_width_px) continue;
            const limit = rule.viewport.screen_max_width_px;
            var found = false;
            for (thresholds[0..count]) |known| found = found or known == limit;
            if (found) continue;
            if (count == thresholds.len) { base.unresolved = true; return base; }
            var index = count;
            while (index != 0 and thresholds[index - 1] < limit) : (index -= 1) thresholds[index] = thresholds[index - 1];
            thresholds[index] = limit; count += 1;
        }
        var bands: std.ArrayList(types.ContainerScreenMaxWidth) = .empty;
        defer bands.deinit(a);
        var previous = base.style;
        for (thresholds[0..count]) |limit| {
            const selected = try containerCascadeAt(a, matched.rules, css, limit, environment, border_collapse_consumed);
            base.specified = base.specified or selected.specified;
            if (selected.unresolved) { base.unresolved = true; return base; }
            if (containerStyleEqual(previous, selected.style)) continue;
            var responsive: types.ContainerScreenMaxWidth = .{ .max_width_px = limit };
            var normalized = selected.style;
            inline for (.{ "width", "max_width", "box_sizing", "line_height" }) |field| {
                if (!std.meta.eql(@field(previous, field), @field(selected.style, field))) {
                    // Absence cannot erase a preceding winner. Explicit
                    // auto/none/normal resets remain represented values.
                    @field(responsive, field) = @field(selected.style, field) orelse { base.unresolved = true; return base; };
                }
                @field(normalized, field) = @field(previous, field);
            }
            if (previous.float_side != selected.style.float_side) {
                responsive.float_side = if (selected.style.float_side) |side| switch (side) {
                    .left => .left, .right => .right,
                } else .none;
            }
            normalized.float_side = previous.float_side;
            if (previous.clear != selected.style.clear)
                responsive.clear = selected.style.clear orelse { base.unresolved = true; return base; };
            normalized.clear = previous.clear;
            // No dynamic layout, padding, paint, font or unrepresented property
            // is discarded by the band encoder. Alias and unknown checks above
            // still execute independently in every selected interval.
            if (!containerStyleEqual(previous, normalized) or !types.validContainerScreenMaxWidth(responsive) or
                bands.items.len == types.max_container_screen_rules) { base.unresolved = true; return base; }
            try bands.append(a, responsive);
            previous = selected.style;
        }
        if (bands.items.len != 0) {
            var responsive = bands.items[0];
            if (bands.items.len > 1) responsive.following_rules = try a.dupe(types.ContainerScreenMaxWidth, bands.items[1..]);
            if (!types.validContainerScreenMaxWidth(responsive)) { base.unresolved = true; return base; }
            base.style.screen_max_width = responsive;
        }
        return base;
    }

    pub fn resolveBlockGeometryIn(self: *const Profile, a: std.mem.Allocator, element: *const TextElement, css: []const u8) std.mem.Allocator.Error!BlockGeometryResolution {
        if (self.globally_unresolved or (self.page_style_parent != null and element.page_style_root == null) or css.len > max_css_bytes) return .{ .unresolved = true };
        var cascade_value: BlockGeometryCascade = .{};
        defer cascade_value.possible.deinit(a);
        for (self.block_rules) |rule| {
            const matched = rule.selector.matchIn(element, self.page_style_parent != null);
            if (matched == .no) continue;
            try cascade_value.declarations(a, rule.css, rule.selector.specificity, rule.order, rule.selector.uncertain or matched == .unknown, false);
        }
        try cascade_value.declarations(a, css, 0, max_rules * 1024, false, true);
        // DIV has zero initial edges; paragraph UA margins are viewer-owned,
        // so a P quartet needs independently explicit values on every side.
        return cascade_value.result(std.ascii.eqlIgnoreCase(element.tag, "div"));
    }

    pub fn hasTextContext(self: *const Profile) bool { return self.hasTextPaint() or self.block_rules.len != 0; }

    pub fn hasNewAnchorTextRule(self: *const Profile) bool {
        if (self.page_style_parent) |parent| if (parent.hasNewAnchorTextRule()) return true;
        for (self.text_rules) |rule| {
            if (rule.selector.chain.len == 0) continue;
            const terminal = rule.selector.chain[rule.selector.chain.len - 1];
            if (terminal.tag) |tag| if (!std.ascii.eqlIgnoreCase(tag, "a")) continue;
            for (terminal.classes) |class| if (std.mem.eql(u8, class, "new")) return true;
        }
        return false;
    }
    pub fn hasTextPaint(self: *const Profile) bool { return self.page_style_parent != null or self.globally_unresolved or self.text_rules.len != 0; }

    pub fn resolveTextPaint(self: *const Profile, a: std.mem.Allocator, element: *const TextElement, css: []const u8) std.mem.Allocator.Error!TextPaint {
        return self.resolveTextPaintWithCustom(a, element, css, null);
    }

    pub fn resolveTextPaintWithCustom(self: *const Profile, a: std.mem.Allocator, element: *const TextElement, css: []const u8, environment: ?CustomEnvironment) std.mem.Allocator.Error!TextPaint {
        if (self.page_style_parent != null) if (element.alternative_ancestry) |alternative| {
            if (element.observed_inline_style) |actual| {
                const other = alternative.observed_inline_style orelse return .{ .color = .unknown, .weight = .unknown, .font_style = .unknown };
                if (!std.mem.eql(u8, actual, other)) return .{ .color = .unknown, .weight = .unknown, .font_style = .unknown };
            }
        };
        if (self.globally_unresolved or (self.page_style_parent != null and element.page_style_root == null) or css.len > max_css_bytes) return .{ .color = .unknown, .weight = .unknown, .font_style = .unknown };
        var cascade_value: TextCascade = .{ .custom_environment = environment };
        defer cascade_value.possible_colors.deinit(a);
        defer cascade_value.possible_weights.deinit(a);
        defer cascade_value.possible_font_styles.deinit(a);
        for (self.text_rules) |rule| {
            const matched = rule.selector.matchIn(element, self.page_style_parent != null);
            if (matched != .no) try cascade_value.declarations(a, rule.css, rule.selector.specificity, rule.order, rule.selector.uncertain or matched == .unknown, false);
        }
        try cascade_value.declarations(a, css, 0, max_rules * 1024, false, true);
        return cascade_value.result();
    }

    // The compiler calls this only for a complete source-issued physical path.
    // Ordinary inheritance reuses the existing cascade at each real ancestor;
    // unknown values stop that field. Other effects retain the page refusal.
    pub fn resolveTextPaintWithObservedInheritance(self: *const Profile, a: std.mem.Allocator, element: *const TextElement, css: []const u8, environment: ?CustomEnvironment) std.mem.Allocator.Error!TextPaint {
        var result = try self.resolveTextPaintWithCustom(a, element, css, environment);
        if (self.page_style_parent == null or element.source_root_child == null or !element.physical_ancestry_complete) return result;
        var color_needed = result.color == null or result.color.? == .inherit;
        var weight_needed = result.weight == null or result.weight.? == .inherit;
        var italic_needed = result.font_style == null or result.font_style.? == .inherit;
        var cursor = element.parent;
        var depth: usize = 0;
        while (cursor) |ancestor| : (depth += 1) {
            if (!color_needed and !weight_needed and !italic_needed) break;
            if (depth == 64 or !ancestor.physical_ancestry_complete or ancestor.observed_inline_style == null) {
                if (color_needed) { result.color = .unknown; result.color_inline = false; }
                if (weight_needed) { result.weight = .unknown; result.weight_inline = false; }
                if (italic_needed) { result.font_style = .unknown; result.font_style_inline = false; }
                break;
            }
            // Compute an ancestor's variable consumers only from its own
            // retained environment. The descendant argument cannot lend values.
            var ancestor_environment = ancestor.observed_custom_environment;
            if (ancestor.alternative_ancestry) |alternative| {
                ancestor_environment = if (ancestor_environment) |actual|
                    if (alternative.observed_custom_environment) |other| try intersectCustomEnvironmentsAlloc(a, actual, other) else null
                else null;
            }
            const paint = try self.resolveTextPaintWithCustom(a, ancestor, ancestor.observed_inline_style.?, ancestor_environment);
            if (color_needed) if (paint.color) |value| if (value != .inherit) {
                result.color = value; result.color_inline = false; color_needed = false;
            };
            if (weight_needed) if (paint.weight) |value| if (value != .inherit) {
                result.weight = value; result.weight_inline = false; weight_needed = false;
            };
            if (italic_needed) if (paint.font_style) |value| if (value != .inherit) {
                result.font_style = value; result.font_style_inline = false; italic_needed = false;
            };
            cursor = ancestor.parent;
        }
        return result;
    }

    // The caller supplies the complete, source-bound class domain of the
    // generated Figure and its finite caption, with no authored inline style.
    // This borrowed view changes only Figure rules; never deinit the view.
    pub fn figureStaticMotionViewIn(self: *const Profile, a: std.mem.Allocator, complete_classes: []const u8) std.mem.Allocator.Error!?Profile {
        if (self.globally_unresolved or complete_classes.len > 65536) return null;
        var arena = std.heap.ArenaAllocator.init(a); defer arena.deinit();
        const scratch = arena.allocator();
        const Range = struct { start: usize = 0, end: usize = 0, eligible: bool = false };
        const ranges = try scratch.alloc(Range, self.figure_rules.len);
        @memset(ranges, .{});
        var declarations: std.ArrayList(ObservedFigureDeclaration) = .empty;
        for (self.figure_rules, 0..) |rule, index| {
            if (figureMotionClassesRefute(rule.selector, complete_classes)) continue;
            const begin = declarations.items.len;
            // No selector, condition or cascade order is promoted to a match.
            // Every possible declaration and the initial state remain candidates.
            appendObservedFigureDeclarations(scratch, &declarations, rule.css,
                .{ .specificity = rule.selector.specificity, .order = rule.order }, true, true, null, 0) catch |err| switch (err) {
                    error.OutOfMemory => return error.OutOfMemory, else => return null,
                };
            var complete = true; var pos: usize = 0;
            while (try nextDeclarationAlloc(scratch, rule.css, &pos)) |raw| {
                if (trim(raw).len == 0) continue;
                const colon = std.mem.indexOfScalar(u8, raw, ':') orelse { complete = false; continue; };
                if (trim(raw[0..colon]).len == 0 or trim(raw[colon + 1..]).len == 0) complete = false;
            }
            ranges[index] = .{ .start = begin, .end = declarations.items.len,
                .eligible = complete and declarations.items.len != begin };
        }
        var used = try ObservedFigurePropertyUse.init(scratch, declarations.items);
        // An incomplete custom environment retains variable uncertainty.
        if (!try used.staticMotion(scratch, .{})) return null;
        var omitted: usize = 0;
        for (ranges) |*range| {
            if (!range.eligible) continue;
            for (used.used[range.start..range.end]) |consumed| range.eligible = range.eligible and consumed;
            if (range.eligible) omitted += 1;
        }
        if (omitted == 0) return null;
        const retained = try a.alloc(TextRule, self.figure_rules.len - omitted);
        var count: usize = 0;
        for (self.figure_rules, ranges) |rule, range| if (!range.eligible) {
            retained[count] = rule; count += 1;
        };
        var view = self.*; view.figure_rules = retained;
        return view;
    }

    // Borrowed Figure-only view: the caller owns a complete source-bound
    // generated Figure/caption domain. Generated html/body/div/figure/
    // figcaption/a/img roles cannot be form controls. The finite caption
    // inventory and every actual inherited node must exclude both possible
    // hosts of Mozilla's exact inner-focus pseudo. An open or paired ancestor
    // path cannot lend absence. Original text/ancestor profiles stay intact.
    pub fn figureControlPseudoViewIn(self: *const Profile, a: std.mem.Allocator, authored: ?*const TextElement, caption_tags: ?[]const []const u8) std.mem.Allocator.Error!?Profile {
        if (self.globally_unresolved) return null;
        const tags = caption_tags orelse return null;
        if (tags.len > 64) return null;
        for (tags) |tag| if (std.ascii.eqlIgnoreCase(tag, "button") or std.ascii.eqlIgnoreCase(tag, "input")) return null;
        var cursor = authored;
        var depth: usize = 0;
        var closed = authored == null;
        while (cursor) |node| : (depth += 1) {
            if (depth == 64 or node.alternative_ancestry != null or
                std.ascii.eqlIgnoreCase(node.tag, "button") or std.ascii.eqlIgnoreCase(node.tag, "input")) return null;
            if (node.ancestry_complete) {
                if (node.parent != null or !std.ascii.eqlIgnoreCase(node.tag, "div") or !hasClass(node.classes, "mw-parser-output")) return null;
                closed = true;
            }
            cursor = node.parent;
        }
        if (!closed) return null;
        var omitted: usize = 0;
        for (self.figure_rules) |rule| if (rule.selector.figure_control_pseudo) { omitted += 1; };
        if (omitted == 0) return null;
        const retained = try a.alloc(TextRule, self.figure_rules.len - omitted);
        var count: usize = 0;
        for (self.figure_rules) |rule| if (!rule.selector.figure_control_pseudo) {
            retained[count] = rule; count += 1;
        };
        var view = self.*; view.figure_rules = retained;
        return view;
    }

    fn figureMotionClassesRefute(selector_value: TextSelector, complete_classes: []const u8) bool {
        for (selector_value.necessary_ancestor_classes) |required| if (!hasClass(complete_classes, required)) return true;
        for (selector_value.caption_class_guard) |required| if (!hasClass(complete_classes, required)) return true;
        if (!selector_value.uncertain) for (selector_value.chain) |part| {
            for (part.classes) |required| if (!hasClass(complete_classes, required)) return true;
        };
        return false;
    }

    pub fn resolveFigure(self: *const Profile, a: std.mem.Allocator, element: *const TextElement, font_scale: f32, rtl: bool) std.mem.Allocator.Error!FigureStyle {
        return resolveFigureStyle(self, a, element, font_scale, rtl);
    }

    pub const FigureRootDirectionUse = enum { independent, generated_only, unresolved };

    // A source site default does not attest ParserOutput's page direction.
    // Rules that can depend on that unknown root and later caption children
    // need more context than the pure generated-Figure preparation supplies.
    pub fn figureRootDirectionUse(self: *const Profile, authored: ?*const TextElement) FigureRootDirectionUse {
        return self.figureRootDirectionUseWithCaptionClasses(authored, null);
    }

    pub fn figureRootDirectionUseWithCaptionClasses(self: *const Profile, authored: ?*const TextElement, caption_classes: ?[]const u8) FigureRootDirectionUse {
        return self.figureRootDirectionUseWithCaptionDomain(authored, caption_classes, null);
    }

    pub fn figureRootDirectionUseWithCaptionDomain(self: *const Profile, authored: ?*const TextElement, caption_classes: ?[]const u8, caption_tags: ?[]const []const u8) FigureRootDirectionUse {
        return self.figureRootDirectionUseWithLanguage(authored, caption_classes, caption_tags, null, false, null);
    }
    pub const FigureRootDirectionWitness = struct {
        pub const Reason = enum { none, predicate, chain, terminal, custom_predicate, custom_classes };
        reason: Reason = .none,
        rule_index: usize = 0,
        custom_rule: bool = false,
        // Borrowed from this Profile; consumed synchronously at the refusal.
        css: []const u8 = "",
    };
    fn rootDirectionRefusal(witness: ?*FigureRootDirectionWitness, reason: FigureRootDirectionWitness.Reason, rule_index: usize, custom_rule: bool, css: []const u8) FigureRootDirectionUse {
        if (witness) |out| out.* = .{ .reason = reason, .rule_index = rule_index, .custom_rule = custom_rule, .css = css };
        return .unresolved;
    }
    pub fn figureRootDirectionUseWithLanguage(self: *const Profile, authored: ?*const TextElement, caption_classes: ?[]const u8, caption_tags: ?[]const []const u8, root_language: ?[]const u8, caption_no_language_override: bool, outer_languages: ?[]const []const u8) FigureRootDirectionUse {
        return self.figureRootDirectionUseWithWitness(authored, caption_classes, caption_tags, root_language, caption_no_language_override, outer_languages, null);
    }
    pub fn figureRootDirectionUseWithWitness(self: *const Profile, authored: ?*const TextElement, caption_classes: ?[]const u8, caption_tags: ?[]const []const u8, root_language: ?[]const u8, caption_no_language_override: bool, outer_languages: ?[]const []const u8, witness: ?*FigureRootDirectionWitness) FigureRootDirectionUse {
        return self.figureRootDirectionUseWithCompleteClasses(authored, caption_classes, caption_tags, root_language, caption_no_language_override, outer_languages, null, witness);
    }
    pub fn figureRootDirectionUseWithCompleteClasses(self: *const Profile, authored: ?*const TextElement, caption_classes: ?[]const u8, caption_tags: ?[]const []const u8, root_language: ?[]const u8, caption_no_language_override: bool, outer_languages: ?[]const []const u8, complete_classes: ?[]const u8, witness: ?*FigureRootDirectionWitness) FigureRootDirectionUse {
        if (witness) |out| out.* = .{};
        const ltr: TextElement = .{ .tag = "div", .classes = "mw-content-ltr mw-parser-output" };
        const rtl: TextElement = .{ .tag = "div", .classes = "mw-content-rtl mw-parser-output" };
        var result: FigureRootDirectionUse = .independent;
        direction_rule: for (self.figure_rules, 0..) |rule, rule_index| {
            // Only complete supported selectors supply necessary terminal classes.
            // Unknown functional/pseudo projections retain their existing guards.
            if (caption_classes) |inherited_classes| if (!rule.selector.uncertain and rule.selector.chain.len != 0) {
                for (rule.selector.chain[rule.selector.chain.len - 1].classes) |required|
                    if (!figureCaptionClassPresent(authored, inherited_classes, required)) continue :direction_rule;
            };
            if (caption_no_language_override) if (rule.selector.language_range) |range| {
                // A bare rule can affect an ancestor and then inherit into the
                // caption even when an inner language overrides that ancestor.
                var outer_absent = rule.figure_language_baseline_only;
                if (outer_languages) |languages| {
                    outer_absent = languages.len != 0;
                    for (languages) |language| outer_absent = outer_absent and languageValueRefutes(range, language);
                }
                var absent = outer_absent and languageRefutes(range, null, root_language);
                var cursor = authored;
                while (cursor) |node| : (cursor = node.parent) absent = absent and languageRefutes(range, node, root_language);
                if (absent) continue;
            };
            // The exact bare :lang() parser retains its matching uncertainty,
            // but changing only the content wrapper's LTR/RTL class cannot
            // change language inheritance. This proves direction independence,
            // not that the rule is absent or that its declarations are safe.
            // Keep the ordinary Figure/font cascade responsible for those effects.
            if (rule.selector.language_range != null) continue;
            // A fully inventoried caption cannot acquire a subject tag absent
            // from both its native nodes and the actual inherited ancestry.
            // This refutes an effect; it never matches a language predicate.
            if (caption_tags) |tags| if (rule.selector.caption_subject_tag) |required| {
                // Only list containers have a complete absence certificate.
                // Other authored/generated wrapper domains remain unchanged.
                const list_container = std.ascii.eqlIgnoreCase(required, "ol") or
                    std.ascii.eqlIgnoreCase(required, "ul") or std.ascii.eqlIgnoreCase(required, "dl");
                var present = !list_container;
                for ([_][]const u8{ "html", "body", "div", "figure", "figcaption", "a", "img" }) |tag|
                    present = present or std.ascii.eqlIgnoreCase(tag, required);
                for (tags) |tag| present = present or std.ascii.eqlIgnoreCase(tag, required);
                var ancestor = authored;
                while (ancestor) |element| : (ancestor = element.parent)
                    present = present or std.ascii.eqlIgnoreCase(element.tag, required);
                if (!present) continue;
            };
            // Matched primary Thumb/Frame CSS explicitly sets center on the
            // frame and start on its caption. A root-only inherited alignment
            // cannot cross either barrier; descendant rules remain evaluated.
            if (rule.figure_root_alignment_only and !rule.selector.uncertain and rule.selector.chain.len == 1 and
                (rule.selector.matches(&ltr) or rule.selector.matches(&rtl))) continue;
            if (rule.selector.root_predicate_unresolved) {
                if (caption_classes) |inherited_classes| {
                    const complete: ?[]const u8 = if (rule.selector.caption_class_guard_requires_complete) complete_classes else "";
                    if (complete) |outer_classes| {
                        var absent = false;
                        for (rule.selector.caption_class_guard) |name| {
                            const present = if (rule.selector.caption_class_guard_requires_complete)
                                figureFunctionalClassPossible(authored, inherited_classes, outer_classes, name)
                            else figureCaptionClassPresent(authored, inherited_classes, name);
                            absent = absent or !present;
                        }
                        if (absent) continue;
                    }
                }
                return rootDirectionRefusal(witness, .predicate, rule_index, false, rule.css);
            }
            for (rule.selector.chain, 0..) |compound, index| {
                if (compound.matches(&ltr) == compound.matches(&rtl)) continue;
                // A first descendant compound is independent only if the next
                // compound cannot be an existing ancestor or the root. Its
                // future match is then below this actual authored ancestor.
                var independently_matched = false;
                if (index == 0 and !rule.selector.direct_children and rule.selector.chain.len > 1 and
                    !rule.selector.chain[1].matches(&ltr) and !rule.selector.chain[1].matches(&rtl))
                {
                    var preceding_match = false;
                    var parent = authored;
                    while (parent) |element| : (parent = element.parent) {
                        if (element.ancestry_complete) break;
                        if (rule.selector.chain[1].matches(element)) preceding_match = true;
                        if (element.source_key != 0 and compound.matches(element)) independently_matched = true;
                    }
                    independently_matched = independently_matched and !preceding_match;
                }
                if (independently_matched) continue;
                // These two generated nodes are completely evaluated before
                // caption effects. Other terminal/ancestor domains stay strict.
                if (index != 0 or rule.selector.chain.len != 2 or rule.selector.uncertain) return rootDirectionRefusal(witness, .chain, rule_index, false, rule.css);
                const terminal = rule.selector.chain[1];
                const tag = terminal.tag orelse return rootDirectionRefusal(witness, .terminal, rule_index, false, rule.css);
                if ((!std.ascii.eqlIgnoreCase(tag, "figure") and !std.ascii.eqlIgnoreCase(tag, "figcaption")) or
                    terminal.classes.len != 0 or terminal.ids.len != 0) return rootDirectionRefusal(witness, .terminal, rule_index, false, rule.css);
                result = .generated_only;
            }
        }
        // Custom definitions are separate from direct Figure rules. A root
        // direction-dependent environment must not leak into the later parse.
        if (self.custom_properties) |custom| for (custom.rules, 0..) |rule, rule_index| {
            if (rule.root_only) continue; // CSS :root is not this content DIV.
            if (rule.root_predicate_unresolved) return rootDirectionRefusal(witness, .custom_predicate, rule_index, true, rule.css);
            if (rule.selector.tag) |tag| if (!std.ascii.eqlIgnoreCase(tag, "div")) continue;
            if (rule.selector.id) |id| if (id.len != 0) continue;
            var match_ltr = true;
            var match_rtl = true;
            for (rule.selector.classes) |required| {
                const name = custom.classes[required];
                match_ltr = match_ltr and Profile.hasClass(ltr.classes, name);
                match_rtl = match_rtl and Profile.hasClass(rtl.classes, name);
            }
            if (match_ltr != match_rtl) return rootDirectionRefusal(witness, .custom_classes, rule_index, true, rule.css);
        };
        return result;
    }

    // A known content language does not reset styles inherited from omitted
    // outer subjects. Keep their absence proof separate from LTR/RTL invariance.
    pub fn figureOuterLanguageEffectsUnchanged(self: *const Profile, outer_languages: ?[]const []const u8) bool {
        for (self.figure_rules) |rule| if (rule.selector.language_range) |range| {
            var absent = rule.figure_language_baseline_only;
            if (outer_languages) |languages| {
                absent = languages.len != 0;
                for (languages) |language| absent = absent and languageValueRefutes(range, language);
            }
            if (!absent) return false;
        };
        return true;
    }

    // Closing content ancestry must not introduce an uncomputed inherited
    // cascade. Direct generated-Figure rules are resolved separately below.
    pub fn contentParentEffectsUnchanged(self: *const Profile, original: ?*const TextElement, projected: *const TextElement) bool {
        if (self.globally_unresolved) return false;
        for (self.figure_rules) |rule| {
            if (rule.figure_root_alignment_only and !rule.selector.uncertain and rule.selector.chain.len == 1 and
                projected.ancestry_complete and projected.source_key == 0 and projected.parent == null and
                std.ascii.eqlIgnoreCase(projected.tag, "div") and Profile.hasClass(projected.classes, "mw-parser-output")) continue;
            if (rule.selector.matches(projected) and (original == null or !rule.selector.matches(original.?))) return false;
        }
        return true;
    }

    pub fn missingLinkCustomPaintUnchanged(self: *const Profile, element: *const TextElement) bool {
        if (self.globally_unresolved) return false;
        for (self.missing_link_custom_rules) |rule| {
            var cursor: ?*const TextElement = element;
            while (cursor) |node| : (cursor = node.parent) {
                if (rule.selector.matches(node) or figureOuterSelectorUnknown(rule.selector, node)) return false;
            }
            // The supplied content DIV is not the browser HTML/BODY. A token
            // definition on those outer subjects may be inherited even when
            // the complete content subtree contains no matching element.
            if (rule.selector.chain.len != 0) {
                const terminal = rule.selector.chain[rule.selector.chain.len - 1];
                if (terminal.tag) |tag| if (std.ascii.eqlIgnoreCase(tag, "html") or std.ascii.eqlIgnoreCase(tag, "body")) return false;
            }
        }
        return true;
    }

    pub fn sourceRubyInlinePaddingAlloc(self: *const Profile, a: std.mem.Allocator,
        element: *const TextElement, css: []const u8, source_declarations: []const []const u8,
        trace_refusal: bool) std.mem.Allocator.Error!?RubyInlinePadding
    {
        const padding = try rubyInlinePaddingAlloc(a, css) orelse return null;
        // The compiler supplies a complete, current native declaration chain,
        // beginning with this exact own style. TextElement alone is not that
        // custody proof: ordinary rendering can omit unneeded ancestor nodes.
        if (!rubySourceDeclarationChainValid(element, css, source_declarations)) return null;
        // Own padding is represented separately. Every stylesheet layout rule
        // still passes the established Ruby query with the original node.
        if (!try self.sourceRubyLayoutUnchanged(a, element, "", trace_refusal)) return null;
        if (!try self.sourceRubyDeclarationsStaticMotion(a, source_declarations)) return null;
        return padding;
    }

    fn rubySourceDeclarationChainValid(element: *const TextElement, css: []const u8,
        source_declarations: []const []const u8) bool
    {
        if (source_declarations.len == 0 or source_declarations.len > 65 or
            !std.mem.eql(u8, source_declarations[0], css)) return false;
        var node: ?*const TextElement = element;
        var node_budget: usize = 64;
        while (node) |current| : (node = current.parent) {
            if (node_budget == 0 or current.alternative_ancestry != null) return false;
            node_budget -= 1;
        }
        return true;
    }

    fn sourceRubyDeclarationsStaticMotion(self: *const Profile, a: std.mem.Allocator,
        source_declarations: []const []const u8) std.mem.Allocator.Error!bool
    {
        var arena = std.heap.ArenaAllocator.init(a); defer arena.deinit();
        const scratch = arena.allocator();
        var declarations: std.ArrayList(ObservedFigureDeclaration) = .empty;
        // A negative static-motion proof conservatively retains unrelated rules.
        // It never turns unknown selector/condition/order into a matched winner.
        var profile: ?*const Profile = self;
        var profiles_remaining: usize = 64;
        while (profile) |current| : (profile = current.page_style_parent) {
            if (profiles_remaining == 0 or current.globally_unresolved) return false;
            profiles_remaining -= 1;
            for (current.figure_rules) |rule| {
                appendObservedFigureDeclarations(scratch, &declarations, rule.css,
                    .{ .specificity = rule.selector.specificity, .order = rule.order }, true, true, null, 0)
                    catch |err| switch (err) { error.OutOfMemory => return error.OutOfMemory, else => return false };
            }
        }
        for (source_declarations) |inline_css| {
            appendObservedFigureDeclarations(scratch, &declarations, inline_css,
                .{ .inline_style = true }, true, true, null, 0)
                catch |err| switch (err) { error.OutOfMemory => return error.OutOfMemory, else => return false };
        }
        if (!try observedFigureStaticMotion(scratch, declarations.items, .{})) return false;
        return true;
    }

    // An own numeric value is useful only when the caller retains the live
    // source declaration chain and emits the factor with each effective font.
    // Null is absence or refusal, never permission to bypass the legacy query.
    pub fn sourceRubyUnitlessLineHeightAlloc(self: *const Profile, a: std.mem.Allocator,
        element: *const TextElement, css: []const u8, source_declarations: []const []const u8,
        trace_refusal: bool) std.mem.Allocator.Error!?f32
    {
        if (!std.ascii.eqlIgnoreCase(element.tag, "span") or
            !rubySourceDeclarationChainValid(element, css, source_declarations)) return null;
        var arena = std.heap.ArenaAllocator.init(a); defer arena.deinit();
        const scratch = arena.allocator();
        var declarations: std.ArrayList(ObservedFigureDeclaration) = .empty;
        if (!try self.sourceRubyLayoutIn(scratch, element, css, trace_refusal, &declarations)) return null;
        // An absent custom binding is unknown: this query has no complete
        // observed environment to lend a computed value or unset fallback.
        const selected = try authoredElementLineHeight(scratch, declarations.items, .{});
        if (selected != .multiplier or !std.math.isFinite(selected.multiplier) or selected.multiplier < 0) return null;
        if (!try self.sourceRubyDeclarationsStaticMotion(scratch, source_declarations)) return null;
        return selected.multiplier;
    }

    pub fn sourceRubyLayoutUnchanged(self: *const Profile, a: std.mem.Allocator, element: *const TextElement, css: []const u8, trace_refusal: bool) std.mem.Allocator.Error!bool {
        return self.sourceRubyLayoutIn(a, element, css, trace_refusal, null);
    }

    fn sourceRubyLayoutIn(self: *const Profile, a: std.mem.Allocator, element: *const TextElement,
        css: []const u8, trace_refusal: bool, line_height_declarations: ?*std.ArrayList(ObservedFigureDeclaration)) std.mem.Allocator.Error!bool
    {
        if (self.globally_unresolved or css.len > max_css_bytes) {
            if (trace_refusal) std.debug.print("RUBY_PROFILE_REFUSAL stage=profile global_unresolved={any} inline_css_bytes={d}\n", .{ self.globally_unresolved, css.len });
            return false;
        }
        for (self.figure_rules, 0..) |rule, rule_index| {
            // The existing exact terminal pseudo parser proves a necessary
            // button/input subject. This query is for the Ruby element itself;
            // no outer ancestry, attribute value or positive match is inferred.
            if (rule.selector.figure_control_pseudo and knownNonControlHost(element.tag) and
                (if (element.alternative_ancestry) |other| other.alternative_ancestry == null and
                    knownNonControlHost(other.tag) and other.page_style_root == element.page_style_root and
                    other.ancestor_class_scope == element.ancestor_class_scope and
                    (if (element.ancestor_class_source) |source| (if (other.ancestor_class_source) |value|
                        source.ptr == value.ptr and source.len == value.len else false) else other.ancestor_class_source == null) and
                    (if (element.page_style_source) |source| (if (other.page_style_source) |value|
                        source.ptr == value.ptr and source.len == value.len else false) else other.page_style_source == null)
                    else true)) continue;
            // Reuse the source-issued negative parent fact. Each independently
            // held view must disprove the terminal edge; presence proves nothing.
            if (rule.selector.necessary_direct_parent_tag) |required| {
                // A complete live native label operation can establish this one
                // edge independently of any observed page or distant ancestry.
                if (element.constructed_direct_parent) |native| if (std.ascii.eqlIgnoreCase(element.tag, "ruby") and
                    element.alternative_ancestry == null and native != element and element.parent == native and
                    native.alternative_ancestry == null and native.tag.len != 0 and
                    !std.ascii.eqlIgnoreCase(native.tag, required)) continue;
                var refuted = true;
                for ([_]?*const TextElement{ element, element.alternative_ancestry }) |maybe| if (maybe) |view| {
                    const actual = view.source_parent_tag_nonmatch orelse { refuted = false; break; };
                    if (view.page_style_root == null or view.page_style_root != element.page_style_root or
                        view.ancestor_class_scope != element.ancestor_class_scope or
                        (view != element and view.alternative_ancestry != null) or
                        (if (element.ancestor_class_source) |source| (if (view.ancestor_class_source) |other|
                            source.ptr != other.ptr or source.len != other.len else true) else view.ancestor_class_source != null) or
                        actual.len == 0 or std.ascii.eqlIgnoreCase(actual, required)) { refuted = false; break; }
                };
                if (refuted) continue;
            }
            // Reuse the issued complete-class absence proof before the outer
            // unknown-ancestry fallback. Every held root must refute the rule.
            if (rule.selector.ancestorClassesRefute(element) and
                (if (element.alternative_ancestry) |other| other.alternative_ancestry == null and
                    rule.selector.ancestorClassesRefute(other) else true)) continue;
            const matched = rule.selector.matches(element);
            const outer_unknown: ?bool = if (!matched) figureOuterSelectorUnknown(rule.selector, element) else null;
            if (matched or (outer_unknown orelse false)) if (line_height_declarations) |declarations| {
                // The old loop is refusal-only. Positive value authority also
                // requires the maintained matcher to establish a certain match.
                const certain = matched and !rule.selector.uncertain and
                    rule.selector.matchIn(element, self.page_style_parent != null) == .known;
                appendObservedFigureDeclarations(a, declarations, rule.css,
                    .{ .specificity = rule.selector.specificity, .order = rule.order },
                    !certain, rule.selector.uncertain, null, 0) catch |err| switch (err) {
                        error.OutOfMemory => return error.OutOfMemory, else => return false,
                    };
            };
            if ((matched or (outer_unknown orelse false)) and
                !try rubyLayoutUnchangedIn(a, rule.css, line_height_declarations != null)) {
                if (trace_refusal) {
                    std.debug.print("RUBY_PROFILE_REFUSAL stage=rule index={d} order={d} specificity={d} uncertain={any} matched={any} outer_unknown={any} primary_classes_refute={any} alternative={any} direct_children={any} css_bytes={d} css_prefix={s}\n", .{
                        rule_index, rule.order, rule.selector.specificity, rule.selector.uncertain, matched,
                        outer_unknown, rule.selector.ancestorClassesRefute(element),
                        element.alternative_ancestry != null, rule.selector.direct_children, rule.css.len, rule.css[0..@min(rule.css.len, 512)],
                    });
                    std.debug.print("RUBY_PROFILE_SELECTOR chain_count={d} required_ancestor_classes={d} required_ancestor_ids={d}\n", .{
                        rule.selector.chain.len, rule.selector.necessary_ancestor_classes.len, rule.selector.necessary_ancestor_ids.len,
                    });
                    for (rule.selector.chain[0..@min(rule.selector.chain.len, 4)], 0..) |part, index| {
                        const tag = part.tag orelse "";
                        const typeof_token = part.typeof_token orelse "";
                        std.debug.print("RUBY_PROFILE_COMPOUND index={d} tag_bytes={d} tag_prefix={s} typeof_bytes={d} typeof_prefix={s} classes={d} ids={d}\n", .{
                            index, tag.len, tag[0..@min(tag.len, 128)], typeof_token.len, typeof_token[0..@min(typeof_token.len, 128)], part.classes.len, part.ids.len,
                        });
                        for (part.classes[0..@min(part.classes.len, 4)], 0..) |class, class_index|
                            std.debug.print("RUBY_PROFILE_CLASS compound={d} index={d} bytes={d} prefix={s}\n", .{ index, class_index, class.len, class[0..@min(class.len, 128)] });
                        for (part.ids[0..@min(part.ids.len, 4)], 0..) |id, id_index|
                            std.debug.print("RUBY_PROFILE_ID compound={d} index={d} bytes={d} prefix={s}\n", .{ index, id_index, id.len, id[0..@min(id.len, 128)] });
                    }
                    var ancestor: ?*const TextElement = element;
                    var depth: usize = 0;
                    while (ancestor) |node| : (depth += 1) {
                        if (depth == 4) break;
                        const classes = node.complete_ancestor_classes orelse "";
                        std.debug.print("RUBY_PROFILE_NODE depth={d} tag={s} own_classes={s} complete_classes={any} complete_bytes={d} complete_prefix={s} class_scope={any} class_source={any} ancestry_complete={any} physical_complete={any} page_root={any} alternative={any}\n", .{
                            depth, node.tag[0..@min(node.tag.len, 128)], node.classes[0..@min(node.classes.len, 128)],
                            node.complete_ancestor_classes != null, classes.len, classes[0..@min(classes.len, 256)],
                            node.ancestor_class_scope != null, node.ancestor_class_source != null, node.ancestry_complete,
                            node.physical_ancestry_complete, node.page_style_root != null, node.alternative_ancestry != null,
                        });
                        ancestor = node.parent;
                    }
                    std.debug.print("RUBY_PROFILE_ANCESTRY remaining={any}\n", .{ancestor != null});
                }
                return false;
            }
        }
        if (line_height_declarations) |declarations| {
            appendObservedFigureDeclarations(a, declarations, css,
                .{ .inline_style = true, .order = max_rules * 1024 }, false, false, null, 0)
                catch |err| switch (err) { error.OutOfMemory => return error.OutOfMemory, else => return false };
        }
        const unchanged = try rubyLayoutUnchangedIn(a, css, line_height_declarations != null);
        if (!unchanged and trace_refusal) std.debug.print("RUBY_PROFILE_REFUSAL stage=inline css_bytes={d} css_prefix={s}\n", .{ css.len, css[0..@min(css.len, 512)] });
        return unchanged;
    }

    pub fn sourceBidiScopeUnchanged(self: *const Profile, a: std.mem.Allocator, element: *const TextElement, css: []const u8) std.mem.Allocator.Error!bool {
        if (self.globally_unresolved or css.len > max_css_bytes) return false;
        for (self.figure_rules) |rule| {
            if ((rule.selector.matches(element) or figureOuterSelectorUnknown(rule.selector, element)) and
                try hasBidiDeclaration(a, rule.css)) return false;
        }
        return !(try hasBidiDeclaration(a, css));
    }

    pub fn deinit(self: *Profile) void {
        self.arena.deinit();
        self.* = undefined;
    }

    pub fn classScope(self: *const Profile, names: []const u8) Scope {
        var result: Scope = 0;
        var tokens = std.mem.tokenizeAny(u8, names, " \t\r\n\x0c");
        while (tokens.next()) |token| {
            for (self.classes, 0..) |name, i| if (std.mem.eql(u8, token, name)) {
                result |= @as(Scope, 1) << @intCast(i);
            };
        }
        return result;
    }

    pub fn hasClass(names: []const u8, required: []const u8) bool {
        var tokens = std.mem.tokenizeAny(u8, names, " \t\r\n\x0c");
        while (tokens.next()) |name| if (std.mem.eql(u8, name, required)) return true;
        return false;
    }

    pub fn ancestorScope(self: *const Profile, names: []const u8) Scope {
        var result: Scope = 0;
        var tokens = std.mem.tokenizeAny(u8, names, " \t\r\n\x0c");
        while (tokens.next()) |token| {
            for (self.ancestor_classes, 0..) |name, i| if (std.mem.eql(u8, token, name)) {
                result |= @as(Scope, 1) << @intCast(i);
            };
        }
        return result;
    }

    fn cascade(self: *const Profile, a: std.mem.Allocator, target: Target, scope: Scope, ancestor_scope: Scope, own_names: []const u8, context: ElementContext, legacy_bg: ?[]const u8, legacy_align: ?[]const u8, inline_css: []const u8) !Winners {
        const ancestor_names = context.ancestor_classes;
        const absent_from = context.complete_table_ancestor_classes orelse ancestor_names;
        var winners: Winners = .{};
        if (target == .td or target == .th or target == .cell) {
            addCellVerticalHint(&winners, context.legacy_vertical_align);
            addCellWidthHint(&winners, context.legacy_cell_width);
        }
        if (legacy_bg) |raw| if (try canonicalColorAlloc(a, raw)) |color| {
            winners.add(.{ .property = .background, .value = .{ .color = color }, .important = false, .order = 0 }, 0, false, false);
        };
        if (presentationalTextAlign(legacy_align)) |alignment| winners.add(.{ .property = .text_align, .value = .{ .align_value = alignment }, .important = false, .order = 0 }, 0, false, false);
        rules: for (self.rules) |rule| {
            // An empty table/cell projection cannot override these winners.
            // Custom properties remain owned by the separate custom environment.
            if (rule.declarations.len == 0) continue;
            const selector_value = rule.selector;
