    pub fn cellSourceScopeHazardsAlloc(self: *const Profile, a: std.mem.Allocator, tag: []const u8, names: []const u8, own_id: ?[]const u8, css: []const u8) std.mem.Allocator.Error!CellSourceScopeHazards {
