            while (pos < text.len and std.mem.indexOfScalar(u8, " \t\r\n\x0c", text[pos]) != null) : (pos += 1) {}
            if (pos == text.len) break;
            child = text[pos] == '>';
            if (child) {
                pos += 1;
                while (pos < text.len and std.mem.indexOfScalar(u8, " \t\r\n\x0c", text[pos]) != null) : (pos += 1) {}
                if (pos == text.len) return self.uncertainFigureSelector(raw);
            }
