    try std.testing.expectEqual(Profile.FigureRootDirectionUse.independent, profile.figureRootDirectionUse(null));
    const root: TextElement = .{ .tag = "div", .classes = "mw-content-ltr mw-parser-output", .ancestry_complete = true };
