    try std.testing.expectEqual(ContainerSelectorMatch.unknown, unknown.rules[0].match);
    item.ancestry_complete = true;
    try std.testing.expectEqual(@as(usize, 0), (try profile.containerRuleMatchesIn(a, &item)).rules.len);
}

