        "blockquote > :first-child{margin-top:0}", "blockquote > :last-child{margin-bottom:0}",
        "div > :first-child{margin-top:0}", "blockquote :first-child{margin-top:0}", "blockquote + div{margin-top:0}",
    }, 0..) |css, index| {
