    for ([_][]const u8{ "[bgcolor]:hover{color:#333}", "[bgcolor='red']{color:#333}", "tr[bgcolor]{color:#333}",
        "[bgcolor],:unknown{color:#333}", "[bgcolor]{font-size:2em}", "[bgcolor]{background-color:#eee}",
