        var anchor: TextElement = .{ .tag = "a", .parent = &middle };
        var node: TextElement = .{ .tag = "ruby", .parent = &anchor, .constructed_direct_parent = &anchor };
        var alternative: TextElement = .{ .tag = "ruby", .parent = &anchor };
