test "closed inline sibling proof refutes edit section brackets without consuming a real edit neighbour" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator); defer arena.deinit(); const a = arena.allocator();
    // Exact retained Mai GET stylesheet rule, including both content declarations.
    const css = ".client-nojs a.mw-editsection-visualeditor:first-of-type + .mw-editsection-divider + a::before,.ve-not-available a.mw-editsection-visualeditor:first-of-type + .mw-editsection-divider + a::before,.client-nojs a.mw-editsection-visualeditor:first-of-type + a::before,.ve-not-available a.mw-editsection-visualeditor:first-of-type + a::before{content:'[';content:'[' / '';margin-right:0.25em;margin-inline:0 0.25em}";
    var styles = try parseForTargetAlloc(a, css, .screen); defer styles.deinit();
    try std.testing.expect(styles.observed_figure_rules.len != 0);
    for ([_][]const u8{ "i", "em", "b", "strong", "span" }) |parent_tag| {
        var nodes = [_]ObservedStyleNode{
            .{ .tag = "html", .parent = null, .attributes = &.{.{ .name = "class", .value = "client-nojs ve-not-available" }} },
            .{ .tag = "body", .parent = 0, .attributes = &.{} },
            .{ .tag = "div", .parent = 1, .attributes = &.{.{ .name = "class", .value = "mw-parser-output" }} },
            .{ .tag = parent_tag, .parent = 2, .attributes = &.{}, .known_complete_child_elements = true },
            .{ .tag = "span", .parent = 3, .attributes = &.{.{ .name = "lang", .value = "la" }},
                .known_next_element_sibling = 5, .known_no_previous_element_sibling = true },
            .{ .tag = "a", .parent = 3, .attributes = &.{.{ .name = "href", .value = "https://la.wiktionary.org/wiki/Special:Search/mensis" }},
                .known_previous_element_sibling = 4, .known_no_next_element_sibling = true },
        };
        for (styles.observed_figure_rules) |rule|
            try std.testing.expectEqual(ContainerSelectorMatch.no, observedStyleRuleMatch(rule, &nodes, null, 5, .before, .{}));
        for (0..5) |mode| {
            var changed = nodes;
            switch (mode) {
                0 => changed[3].known_complete_child_elements = false,
                1 => changed[5].known_previous_element_sibling = null,
                2 => changed[4].known_next_element_sibling = null,
                3 => changed[4].parent = 2,
                4 => changed[3].tag = "p",
                else => unreachable,
            }
            var retained = false;
            for (styles.observed_figure_rules) |rule|
                retained = retained or observedStyleRuleMatch(rule, &changed, null, 5, .before, .{}) != .no;
            try std.testing.expect(retained);
        }
        for ([_][]const u8{ "mw-editsection-divider", "mw-editsection-visualeditor" }) |class_name| {
            nodes[4].tag = "a";
            nodes[4].attributes = &.{.{ .name = "class", .value = class_name }};
            var retained = false;
            for (styles.observed_figure_rules) |rule|
                retained = retained or observedStyleRuleMatch(rule, &nodes, null, 5, .before, .{}) != .no;
            try std.testing.expect(retained);
        }
    }
}

test "complete inline sibling proof refutes after brackets beyond rich descendants without granting edit rank" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator); defer arena.deinit(); const a = arena.allocator();
    const css = ".client-nojs a:has(+ .mw-editsection-divider + a.mw-editsection-visualeditor:last-of-type)::after,.ve-not-available a:has(+ .mw-editsection-divider + a.mw-editsection-visualeditor:last-of-type)::after,.client-nojs a:has(+ a.mw-editsection-visualeditor:last-of-type)::after,.ve-not-available a:has(+ a.mw-editsection-visualeditor:last-of-type)::after{content:']';content:']' / '';margin-left:0.25em;margin-inline:0.25em 0}";
    var styles = try parseForTargetAlloc(a, css, .screen); defer styles.deinit();
    try std.testing.expect(styles.observed_figure_rules.len != 0);
    for ([_][]const u8{ "div", "i", "em", "b", "strong", "span", "dd" }) |parent_tag| {
        var nodes = [_]ObservedStyleNode{
            .{ .tag = "html", .parent = null, .attributes = &.{.{ .name = "class", .value = "client-nojs ve-not-available" }} },
            .{ .tag = "body", .parent = 0, .attributes = &.{} },
            .{ .tag = "dl", .parent = 1, .attributes = &.{} },
            .{ .tag = parent_tag, .parent = 2, .attributes = &.{}, .known_complete_child_elements = true },
            .{ .tag = "span", .parent = 3, .attributes = &.{.{ .name = "lang", .value = "la" }}, .known_next_element_sibling = 5, .known_no_previous_element_sibling = true },
            .{ .tag = "a", .parent = 3, .attributes = &.{.{ .name = "href", .value = "/wiki/Target" }}, .known_previous_element_sibling = 4, .known_no_next_element_sibling = true },
            .{ .tag = "sup", .parent = 5, .attributes = &.{.{ .name = "class", .value = "dewikttm" }}, .has_text = true },
            .{ .tag = "span", .parent = 6, .attributes = &.{}, .has_text = true },
            .{ .tag = "p", .parent = 2, .attributes = &.{}, .has_text = true },
        };
        for (styles.observed_figure_rules) |rule| {
            const weak = rule.weak_selector orelse return error.TestUnexpectedResult;
            try std.testing.expect(weak.necessary_has_next != null and !weak.syntax_known);
            try std.testing.expectEqual(ContainerSelectorMatch.no, observedStyleRuleMatch(rule, &nodes, null, 5, .after, .{}));
            try std.testing.expectEqual(ContainerSelectorMatch.no, observedStyleRuleMatch(rule, nodes[0..8], null, 5, .after, .{}));
        }
        // A different real following child is also a valid necessary-fact
        // refutation; it cannot be confused with either SUP descendant.
        var following = nodes;
        following[5].known_no_next_element_sibling = false;
        following[5].known_next_element_sibling = 8;
        following[8].tag = "span"; following[8].parent = 3;
        following[8].known_previous_element_sibling = 5;
        for (styles.observed_figure_rules) |rule|
            try std.testing.expectEqual(ContainerSelectorMatch.no, observedStyleRuleMatch(rule, &following, null, 5, .after, .{}));
        for (0..10) |mode| {
            var changed = nodes;
            switch (mode) {
                0 => changed[3].known_complete_child_elements = false,
                1 => changed[5].known_no_next_element_sibling = false,
                2 => changed[5].known_next_element_sibling = 8,
                3 => changed[8].parent = 4,
                4 => changed[6].parent = 6,
                5 => changed[3].tag = "p",
                6 => { changed = following; changed[8].known_previous_element_sibling = 4; },
                7 => { changed = following; changed[8].known_no_previous_element_sibling = true; },
                8 => { changed = following; changed[8].tag = "a"; changed[8].attributes = &.{.{ .name = "class", .value = "mw-editsection-visualeditor" }}; },
                9 => { changed = following; changed[8].attributes = &.{.{ .name = "class", .value = "mw-editsection-divider" }}; },
                else => unreachable,
            }
            var retained = false;
            for (styles.observed_figure_rules) |rule|
                retained = retained or observedStyleRuleMatch(rule, &changed, null, 5, .after, .{}) != .no;
            try std.testing.expect(retained);
        }
        // The bounded query must not manufacture absence on exhausted work.
        const large = try a.alloc(ObservedStyleNode, 4103);
        @memcpy(large[0..6], nodes[0..6]);
        for (large[6..]) |*child| child.* = .{ .tag = "span", .parent = 5, .attributes = &.{}, .has_text = true };
        for (styles.observed_figure_rules) |rule|
            try std.testing.expect(observedStyleRuleMatch(rule, large, null, 5, .after, .{}) != .no);
    }
}

test "indexed gadget applicability survives source retention and page joins without an unconditional grant" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator); defer arena.deinit();
    const a = arena.allocator();
    const sources = [_]Source{
        .{ .css = ".gadget{text-align:left}:root{--gadget-ink:#123456}", .base_url = "", .unknown_applicability = true },
        .{ .css = ".ordinary{text-align:right}", .base_url = "" },
    };
    var profile = try parseSourcesForTargetAlloc(a, &sources, .screen); defer profile.deinit();
    try std.testing.expect(profile.sources[0].unknown_applicability and profile.retained_sources[0].unknown_applicability);
    try std.testing.expect(!profile.sources[1].unknown_applicability and !profile.retained_sources[1].unknown_applicability);
    const uncertain = try profile.resolveAlignment(a, "div", "gadget", "", null, "");
    try std.testing.expect(uncertain.unresolved and uncertain.value == null);
    const ordinary = try profile.resolveAlignment(a, "div", "ordinary", "", null, "");
    try std.testing.expect(!ordinary.unresolved and ordinary.value.? == .right);
    var joined = try joinPageSourcesAlloc(a, &profile, &.{}, &.{}); defer joined.deinit();
    try std.testing.expect(joined.retained_sources[0].unknown_applicability);
    try std.testing.expect((try joined.resolveAlignment(a, "div", "gadget", "", null, "")).unresolved);
    try attachCustomProperties(&joined, joined.retained_sources, .{
        .dark = false, .ancestors = &.{.{ .tag = "html", .root = true }},
    });
    try std.testing.expect(joined.custom_properties.?.root_environment.get("--gadget-ink") == .unknown);
    const serialized = try std.json.Stringify.valueAlloc(a, profile.sources, .{}); defer a.free(serialized);
    try std.testing.expect(std.mem.indexOf(u8, serialized, "\"unknown_applicability\":true") != null);
}

test "conditional source applicability binds inventory snapshots and observed focus source identity" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator); defer arena.deinit();
    const a = arena.allocator();
    const css = ":focus{outline:0}.probe{text-align:left}";
    var ordinary = try parseSourcesForTargetAlloc(a, &.{.{ .css = css, .base_url = "" }}, .screen); defer ordinary.deinit();
    var conditional = try parseSourcesForTargetAlloc(a, &.{.{ .css = css, .base_url = "", .unknown_applicability = true }}, .screen); defer conditional.deinit();
    try std.testing.expectEqualStrings(&ordinary.sources[0].css_sha256, &conditional.sources[0].css_sha256);
    try std.testing.expect(pageSourceFocusSourceEqual(ordinary.sources[0], ordinary.sources[0]));
    try std.testing.expect(!pageSourceFocusSourceEqual(ordinary.sources[0], conditional.sources[0]));
    try std.testing.expect(!pageSourceFocusSourceEqual(conditional.sources[0], ordinary.sources[0]));
    var snapshot = try ObservedStyleInventorySnapshot.init(a, &ordinary); defer snapshot.deinit();
    try std.testing.expect(snapshot.current());
    @constCast(ordinary.retained_sources)[0].unknown_applicability = true;
    try std.testing.expect(!snapshot.current());
    @constCast(ordinary.retained_sources)[0].unknown_applicability = false;
    try std.testing.expect(snapshot.current());
    @constCast(ordinary.sources)[0].unknown_applicability = true;
    try std.testing.expect(!snapshot.current());
    @constCast(ordinary.sources)[0].unknown_applicability = false;
    try std.testing.expect(snapshot.current());
    // Deep snapshots preserve the initially conditional state as well; this
    // is an identity guard, not a grant to mutate source applicability.
    var conditional_snapshot = try ObservedStyleInventorySnapshot.init(a, &conditional); defer conditional_snapshot.deinit();
    @constCast(conditional.retained_sources)[0].unknown_applicability = false;
    try std.testing.expect(!conditional_snapshot.current());
    @constCast(conditional.retained_sources)[0].unknown_applicability = true;
    try std.testing.expect(conditional_snapshot.current());
}


test "resolved border compatibility refuses corner projection without changing legacy raw container borders" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    const radius: types.StyleLength = .{ .unit = .px, .value = 4 };
    const corners: types.TableCornerRadii = .{
        .top_left = radius, .top_right = radius, .bottom_right = radius, .bottom_left = radius,
    };
    var winners: Winners = .{};
    winners.add(.{ .property = .corner_radii, .value = .{ .corner_radii = corners }, .important = false, .order = 0 }, 0, false, true);
    const width: types.StyleLength = .{ .unit = .px, .value = 1 };
    for ([_]types.StyleBorderPaint{ .{ .rgb = "#abcdef" }, .owner_current_color }) |paint| {
        const stroke: types.ResolvedStyleBorderLine = .{ .width = width, .paint = paint };
        for ([_]types.ResolvedStyleBorderEdge{
            .none, .hidden, .{ .solid = stroke }, .{ .dotted = stroke }, .{ .inset = stroke }, .{ .outset = stroke },
        }) |edge| {
            const border: types.StyleBorder = .{ .resolved_edges = types.ResolvedStyleBorderEdges.all(edge) };
            try std.testing.expect(types.validBorder(border));
            var style: types.TableStyle = .{ .collapse = .separate, .border = border };
            const before = style;
            try std.testing.expect(projectTableCorners(&style, winners));
            try std.testing.expect(style.corner_radii == null);
            try std.testing.expectEqualDeep(before, style);
        }
    }
    for ([_]types.StyleBorder{
        .none, .{ .solid = .{ .width = width, .color = "#abcdef" } },
    }) |border| {
        var style: types.TableStyle = .{ .collapse = .separate, .border = border };
        try std.testing.expect(!projectTableCorners(&style, winners));
        try std.testing.expectEqualDeep(corners, style.corner_radii orelse return error.TestUnexpectedResult);
        try std.testing.expectEqualDeep(border, style.border orelse return error.TestUnexpectedResult);
    }
    var old_edges: types.TableStyle = .{ .collapse = .separate, .border = .{ .edges = types.StyleBorderEdges.all(.hidden) } };
    const before_edges = old_edges;
    try std.testing.expect(projectTableCorners(&old_edges, winners));
    try std.testing.expectEqualDeep(before_edges, old_edges);

    for ([_][]const u8{ "none", "0" }) |raw| {
        const border = (try containerBorderAlloc(a, raw)) orelse return error.TestUnexpectedResult;
        try std.testing.expect(border == .none);
    }
    const solid = (try containerBorderAlloc(a, "1px solid #abcdef")) orelse return error.TestUnexpectedResult;
    try std.testing.expectEqualDeep(types.ContainerBorder{ .solid = .{ .width = width, .color = .{ .rgb = "#abcdef" } } }, solid);
    // Raw borderAlloc currently emits only None/Solid. Existing raw physical
    // edges come through the component cascade, not an injected return variant.
    var cascade: BorderCascade = .{};
    cascade.add(try borderUpdateAlloc(a, "border", "1px dotted #abcdef", null), .{}, false);
    const resolved = cascade.result();
    try std.testing.expect(!resolved.unresolved);
    const dotted = resolved.value orelse return error.TestUnexpectedResult;
    const dotted_edge: types.ContainerBorderEdge = .{ .dotted = .{ .width = width, .color = .{ .rgb = "#abcdef" } } };
    try std.testing.expectEqualDeep(types.ContainerBorder{ .edges = types.ContainerBorderEdges.all(dotted_edge) }, dotted);
    const old_style = styleBorderFromContainer(dotted) orelse return error.TestUnexpectedResult;
    try std.testing.expectEqualDeep(types.StyleBorder{ .edges = types.StyleBorderEdges.all(.{ .dotted = .{ .width = width, .color = "#abcdef" } }) }, old_style);
    try std.testing.expectEqualDeep(dotted_edge, containerEdgeFromStyle(old_style.edges.top));
    // No raw parser currently issues resolved_edges, so the new exhaustive
    // containerBorderAlloc refusal arm has no honest directly injectable input.
}


test "AN retained Greek table inline background discards invalid bare identifier without changing other CSS" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    // Exact CSS from Plantilla:-el-fles-semi- p8533/r32171 and
    // Plantilla:-el-fles-manu- p8535/r32173. This API receives CSS alone;
    // its border result does not grant a legacy border=1 width/style join.
    const css = "text-align:center;background:AFAFA;border-collapse:collapse; border-color:#ddd;";
    const reference = "text-align:center;border-collapse:collapse; border-color:#ddd;";
    const selected = try resolveInlineTableAlloc(a, css);
    const expected = try resolveInlineTableAlloc(a, reference);
    try std.testing.expect(!selected.unresolved and !expected.unresolved);
    try std.testing.expectEqualDeep(expected, selected);
    try std.testing.expectEqual(types.BorderCollapse.collapse, selected.style.?.collapse.?);
    try std.testing.expect(selected.style.?.background == null);
    // The independent CSS initial border style is none. The ordinary producer's
    // separate authored HTML border hint must not borrow this CSS-only proof.
    try std.testing.expect(selected.style.?.border.? == .none);
    const centered = try resolveInlineAlignmentAlloc(a, null, css);
    try std.testing.expect(centered.specified and !centered.unresolved);
    try std.testing.expectEqual(types.CellTextAlign.center, centered.value.?);

    for ([_][]const u8{
        "background:red;background:AFAFA!important",
        "background:AFAFA!important;background:red",
        "background:red;background:notacolor!important",
        "background:red;background:afafa",
    }) |candidate| {
        const actual = try resolveInlineTableAlloc(a, candidate);
        try std.testing.expect(!actual.unresolved);
        try std.testing.expectEqualStrings("#ff0000", actual.style.?.background.?);
    }
}

