const CapturedImportantMargins18Test = struct {
    // Reduced retained skin/Common rules and the actual authored table margin.
    // The graph is the existing four-node captured floating-table test shape.
    const skin_selector = ".mw-body p + ul,.mw-body p + ol,.mw-body p + table,.mw-body p + dl,.mw-body p + blockquote";
    const skin = skin_selector ++ "{margin-top:-0.5em}";
    const common_selector = "div.float-right,table.float-right,ul.float-right,.float-right";
    const common = common_selector ++ "{clear:right;float:right;margin:.4em 0 .5em .4em!important}";
    const base = "table{box-sizing:border-box;border-collapse:collapse;background:#ffffff}";
    const responsive = "@media(max-width:639px){table.float-right{float:none;display:block;overflow:auto;max-width:100%;width:fit-content;margin-left:0;margin-right:0}}";

    fn nodes(inline_margin: bool) [4]ObservedStyleNode {
        return .{
            .{ .tag = "html", .parent = null, .attributes = &.{} },
            .{ .tag = "body", .parent = 0, .attributes = &.{.{ .name = "class", .value = "mw-body" }} },
            .{ .tag = "div", .parent = 1, .attributes = &.{.{ .name = "class", .value = "mw-parser-output" }} },
            .{ .tag = "table", .parent = 2, .attributes = if (inline_margin)
                &.{ .{ .name = "class", .value = "wikitable float-right inflection-table flexbox" },
                    .{ .name = "style", .value = "margin:0 0 .5em .4em;" } }
                else &.{.{ .name = "class", .value = "wikitable float-right inflection-table flexbox" }} },
        };
    }

    fn expected(scale: f32) types.StyleEdges {
        return .{ .top = .{ .unit = .em, .value = 0.4 * scale },
            .right = .{ .unit = .px, .value = 0 }, .bottom = .{ .unit = .em, .value = 0.5 * scale },
            .left = .{ .unit = .em, .value = 0.4 * scale } };
    }
};

test "captured floating Table important margins dominate normal uncertain selector rank" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator); defer arena.deinit(); const a = arena.allocator();
    const F = CapturedImportantMargins18Test;
    var styles = try parseForTargetAlloc(a, F.base ++ F.skin ++ F.common ++ F.responsive, .screen); defer styles.deinit();
    var reference = try parseForTargetAlloc(a, F.base ++ F.common ++ F.responsive, .screen); defer reference.deinit();
    const nodes = F.nodes(true);
    const context: TableContainingDirectionContext = .{ .styles = &styles, .nodes = &nodes, .root = 2, .table = 3 };
    const reference_context: TableContainingDirectionContext = .{ .styles = &reference, .nodes = &nodes, .root = 2, .table = 3 };
    for ([_]f64{ 0, 639, 639.5, 900 }) |viewport| {
        errdefer std.debug.print("IMPORTANT_MARGIN18 positive viewport={d}\n", .{viewport});
        const path = (try observedTableDeclarationPath(a, context, 3, viewport, null)) orelse return error.TestUnexpectedResult;
        var uncertain_normal = false; var known_important = false; var inline_normal = false;
        for (path.declarations) |declaration| {
            if (std.mem.eql(u8, declaration.name, "margin-top") and std.mem.eql(u8, declaration.raw, "-0.5em")) {
                uncertain_normal = true;
                try std.testing.expect(declaration.uncertain and declaration.rank_unknown and !declaration.syntax_unknown and !declaration.priority.important);
            }
            if (std.mem.eql(u8, declaration.name, "margin") and std.mem.eql(u8, declaration.raw, ".4em 0 .5em .4em")) {
                known_important = true;
                try std.testing.expect(!declaration.uncertain and !declaration.rank_unknown and !declaration.syntax_unknown and declaration.priority.important);
            }
            if (declaration.priority.inline_style and std.mem.eql(u8, declaration.name, "margin")) {
                inline_normal = true;
                try std.testing.expect(!declaration.priority.important);
                try std.testing.expectEqualStrings("0 0 .5em .4em", declaration.raw);
            }
        }
        try std.testing.expect(uncertain_normal and known_important and inline_normal);
        const candidates = try observedFigurePropertyCandidates(a, path.declarations, "margin-top", &.{"margin"});
        try std.testing.expect(candidates.len != 0);
        for (candidates) |candidate| {
            try std.testing.expect(candidate.priority.important and !candidate.rank_unknown and !candidate.syntax_unknown);
            try std.testing.expectEqualStrings(".4em 0 .5em .4em", candidate.raw);
        }
        for ([_]f32{ 1, 2 }) |scale| {
            errdefer std.debug.print("IMPORTANT_MARGIN18 positive scale={d}\n", .{scale});
            const margins = try observedFigureEdges(a, path.declarations, path.environment, false, false, scale, null);
            try std.testing.expect(!margins.unresolved and margins.value != null);
            const expected = F.expected(scale);
            inline for (.{ "top", "right", "bottom", "left" }) |side| {
                const actual = @field(margins.value.?, side);
                try std.testing.expect(actual == .length);
                try std.testing.expectEqualDeep(@field(expected, side), actual.length);
            }
            const box = (try resolveObservedTableFloatViewportBox(a, context, viewport, scale, .normal_body, .ltr, .ltr, null)) orelse return error.TestUnexpectedResult;
            const independent = (try resolveObservedTableFloatViewportBox(a, reference_context, viewport, scale, .normal_body, .ltr, .ltr, null)) orelse return error.TestUnexpectedResult;
            try std.testing.expectEqualDeep(independent, box);
            try std.testing.expectEqualDeep(expected, box.style.margins.?);
            try std.testing.expect(box.style.margin_values == null and box.style.clear == .right);
            try std.testing.expectEqual(viewport <= 639, box.block);
            if (box.block) {
                try std.testing.expect(box.style.float_side == null and box.style.width == null);
                try std.testing.expectEqualDeep(types.StyleWidth{ .unit = .percent, .value = 100 }, box.max_width.?);
            } else {
                try std.testing.expect(box.style.float_side == .right and box.max_width == null);
            }
        }
    }
}

test "observed margin importance keeps ambiguous winners and computed invalid refusal" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator); defer arena.deinit(); const a = arena.allocator();
    const F = CapturedImportantMargins18Test;
    const Case = struct { name: []const u8, css: []const u8, inline_margin: bool = true,
        unknown_syntax: bool = false, unknown_rank: bool = false, no_definite: bool = false, invalid_winner: bool = false };
    for ([_]Case{
        .{ .name = "equally important uncertain selector", .css = F.base ++ F.common ++ F.skin_selector ++ "{margin-top:.8em!important}", .unknown_rank = true },
        .{ .name = "unknown importance", .css = F.base ++ F.common ++ "table{margin-top:.8em !questionable}", .unknown_syntax = true },
        .{ .name = "escaped property", .css = F.base ++ F.common ++ "table{margin\\2d top:.8em}", .unknown_syntax = true },
        .{ .name = "normal winner cannot defeat unknown rank", .css = F.base ++ F.skin_selector ++ "{margin-top:.8em}" ++ F.common_selector ++ "{clear:right;float:right;margin:.4em 0 .5em .4em}", .unknown_rank = true },
        .{ .name = "no definite winner", .css = F.base ++ F.skin_selector ++ "{margin-top:.8em}", .inline_margin = false, .unknown_rank = true, .no_definite = true },
        .{ .name = "invalid winning value cannot expose lower margin", .css = F.base ++ F.common ++ "table.float-right{margin:not-a-length!important}", .invalid_winner = true },
    }) |case| {
        errdefer std.debug.print("IMPORTANT_MARGIN18 refusal={s}\n", .{case.name});
        var styles = try parseForTargetAlloc(a, case.css, .screen); defer styles.deinit();
        const nodes = F.nodes(case.inline_margin);
        const context: TableContainingDirectionContext = .{ .styles = &styles, .nodes = &nodes, .root = 2, .table = 3 };
        var declarations = (try observedStyleNodeDeclarationsWithLanguage(a, &styles, &nodes, 3, null, null, .{ .viewport_width = 900 }, true)) orelse return error.TestUnexpectedResult;
        defer declarations.deinit(a);
        const candidates = try observedFigurePropertyCandidates(a, declarations.items, "margin-top", &.{"margin"});
        try std.testing.expect(candidates.len != 0);
        var retained_unknown_syntax = false; var retained_unknown_rank = false;
        for (candidates) |candidate| {
            retained_unknown_syntax = retained_unknown_syntax or candidate.syntax_unknown;
            retained_unknown_rank = retained_unknown_rank or candidate.rank_unknown;
            if (case.no_definite) try std.testing.expect(candidate.uncertain);
            if (case.invalid_winner) {
                try std.testing.expect(candidate.priority.important and !candidate.uncertain and !candidate.rank_unknown);
                try std.testing.expectEqualStrings("not-a-length", candidate.raw);
            }
        }
        if (case.unknown_syntax) try std.testing.expect(retained_unknown_syntax);
        if (case.unknown_rank) try std.testing.expect(retained_unknown_rank);
        const margins = try observedFigureEdges(a, declarations.items, .{ .complete = true }, false, false, 1, null);
        try std.testing.expect(margins.unresolved);
        try std.testing.expect((try resolveObservedTableFloatViewportBox(a, context, 900, 1, .normal_body, .ltr, .ltr, null)) == null);
    }
    // A guaranteed-invalid winning var() resets to initial zero; it never revives
    // the lower important Common shorthand or the normal authored inline margin.
    var styles = try parseForTargetAlloc(a, F.base ++ F.skin ++ F.common ++ "table.float-right{margin:var(--missing)!important}", .screen); defer styles.deinit();
    const nodes = F.nodes(true);
    const context: TableContainingDirectionContext = .{ .styles = &styles, .nodes = &nodes, .root = 2, .table = 3 };
    const path = (try observedTableDeclarationPath(a, context, 3, 900, null)) orelse return error.TestUnexpectedResult;
    const candidates = try observedFigurePropertyCandidates(a, path.declarations, "margin-top", &.{"margin"});
    try std.testing.expect(candidates.len != 0);
    for (candidates) |candidate| {
        try std.testing.expect(candidate.priority.important and !candidate.uncertain and !candidate.rank_unknown);
        try std.testing.expectEqualStrings("var(--missing)", candidate.raw);
    }
    const margins = try observedFigureEdges(a, path.declarations, path.environment, false, false, 1, null);
    try std.testing.expect(!margins.unresolved and margins.value != null);
    inline for (.{ "top", "right", "bottom", "left" }) |side| {
        const value = @field(margins.value.?, side);
        try std.testing.expect(value == .length);
        try std.testing.expectEqualDeep(types.StyleLength{ .unit = .px, .value = 0 }, value.length);
    }
    const box = (try resolveObservedTableFloatViewportBox(a, context, 900, 1, .normal_body, .ltr, .ltr, null)) orelse return error.TestUnexpectedResult;
    try std.testing.expectEqualDeep(types.StyleEdges.all(.{ .unit = .px, .value = 0 }), box.style.margins.?);
    // An unknown environment remains unresolved, even with the same winning bytes.
    try std.testing.expect((try observedFigureEdges(a, path.declarations, .{ .complete = false }, false, false, 1, null)).unresolved);
}

test "container descendant selectors require distinct ordered witnesses around a selected root" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    var rules = try parseForTargetAlloc(a,
        ".mw-parser-output .mw-parser-output .entry{width:10px}" ++
        ".mw-parser-output .entry{height:4px}" ++
        ".mw-parser-output body .entry{padding:3px}", .screen);
    defer rules.deinit();
    try std.testing.expectEqual(@as(usize, 3), rules.container_rules.len);
    const repeated = rules.container_rules[0].selector;
    const ordinary = rules.container_rules[1].selector;
    const reversed = rules.container_rules[2].selector;
    const body: TextElement = .{ .tag = "body" };
    const root: TextElement = .{ .tag = "div", .classes = "mw-parser-output", .parent = &body };
    var entry: TextElement = .{ .tag = "div", .classes = "entry", .parent = &root, .page_style_root = &root };
    try std.testing.expectEqual(ContainerSelectorMatch.known, ordinary.matchIn(&entry, true));
    try std.testing.expectEqual(ContainerSelectorMatch.unknown, repeated.matchIn(&entry, true));
    try std.testing.expectEqual(ContainerSelectorMatch.unknown, reversed.matchIn(&entry, true));
    const inner: TextElement = .{ .tag = "div", .classes = "mw-parser-output", .parent = &root };
    entry.parent = &inner;
    try std.testing.expectEqual(ContainerSelectorMatch.known, repeated.matchIn(&entry, true));
    // A detached selected root still supplies a positive ancestor. A shared
    // outer node cannot place that root above its own BODY ancestor.
    entry.parent = null;
    try std.testing.expectEqual(ContainerSelectorMatch.known, ordinary.matchIn(&entry, true));
    try std.testing.expectEqual(ContainerSelectorMatch.unknown, repeated.matchIn(&entry, true));
    entry.parent = &body;
    try std.testing.expectEqual(ContainerSelectorMatch.known, ordinary.matchIn(&entry, true));
    try std.testing.expectEqual(ContainerSelectorMatch.unknown, reversed.matchIn(&entry, true));
    entry.physical_ancestry_complete = true;
    try std.testing.expectEqual(ContainerSelectorMatch.no, reversed.matchIn(&entry, true));
}

test "page scoped public paint and geometry require ordered distinct witnesses on both branches" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    const Check = struct {
        fn uncertain(alloc: std.mem.Allocator, paint: *const Profile, geometry: *const Profile, node: *const TextElement) !void {
            const text = try paint.resolveTextPaint(alloc, node, "");
            try std.testing.expect(text.weight != null and text.weight.? == .unknown);
            try std.testing.expect((try geometry.resolveContainerIn(alloc, node, "")).unresolved);
        }
        fn known(alloc: std.mem.Allocator, paint: *const Profile, geometry: *const Profile, node: *const TextElement) !void {
            const text = try paint.resolveTextPaint(alloc, node, "");
            try std.testing.expect(text.weight != null and text.weight.? == .value and text.weight.?.value);
            const box = try geometry.resolveContainerIn(alloc, node, "");
            try std.testing.expect(!box.unresolved and box.specified and box.style.width != null);
            try std.testing.expect(box.style.width.? == .length);
            try std.testing.expectEqual(types.StyleWidth{ .unit = .px, .value = 10 }, box.style.width.?.length);
        }
    };
    var global = try parseForTargetAlloc(a, "", .screen);
    defer global.deinit();
    var paint = try parseForTargetAlloc(a, ".mw-parser-output .entry{font-weight:bold}", .screen);
    defer paint.deinit();
    paint.page_style_parent = &global;
    var geometry = try parseForTargetAlloc(a, ".mw-parser-output .entry{width:10px}", .screen);
    defer geometry.deinit();
    geometry.page_style_parent = &global;
    const body: TextElement = .{ .tag = "body" };
    const root: TextElement = .{ .tag = "div", .classes = "mw-parser-output", .parent = &body };
    const other: TextElement = .{ .tag = "div", .classes = "entry", .parent = &root, .page_style_root = &root };
    var subject: TextElement = .{ .tag = "div", .classes = "mw-parser-output entry", .parent = &body };
    subject.page_style_root = &subject;
    subject.alternative_ancestry = &other;
    // A subject cannot supply its own ancestor. An independent matching
    // alternative cannot make the disagreeing primary branch certain.
    try Check.uncertain(a, &paint, &geometry, &subject);
    subject.parent = &root;
    try Check.known(a, &paint, &geometry, &subject);
    // Both branch directions must retain the disagreement.
    var reversed_subject = other;
    subject.parent = &body;
    subject.alternative_ancestry = null;
    reversed_subject.alternative_ancestry = &subject;
    try Check.uncertain(a, &paint, &geometry, &reversed_subject);

    var repeated_paint = try parseForTargetAlloc(a, ".mw-parser-output .mw-parser-output .entry{font-weight:bold}", .screen);
    defer repeated_paint.deinit();
    repeated_paint.page_style_parent = &global;
    var repeated_geometry = try parseForTargetAlloc(a, ".mw-parser-output .mw-parser-output .entry{width:10px}", .screen);
    defer repeated_geometry.deinit();
    repeated_geometry.page_style_parent = &global;
    var detached: TextElement = .{ .tag = "div", .classes = "entry", .page_style_root = &root };
    // The selected root is a valid positive distant ancestor; it may not
    // become two witnesses when the chain requires two distinct ancestors.
    try Check.known(a, &paint, &geometry, &detached);
    try Check.uncertain(a, &repeated_paint, &repeated_geometry, &detached);
    detached.parent = &root;
    try Check.uncertain(a, &repeated_paint, &repeated_geometry, &detached);
    const nested: TextElement = .{ .tag = "div", .classes = "mw-parser-output", .parent = &root };
    detached.parent = &nested;
    try Check.known(a, &repeated_paint, &repeated_geometry, &detached);

    var reversed_paint = try parseForTargetAlloc(a, ".mw-parser-output body .entry{font-weight:bold}", .screen);
    defer reversed_paint.deinit();
    reversed_paint.page_style_parent = &global;
    var reversed_geometry = try parseForTargetAlloc(a, ".mw-parser-output body .entry{width:10px}", .screen);
    defer reversed_geometry.deinit();
    reversed_geometry.page_style_parent = &global;
    detached.parent = &root;
    try Check.uncertain(a, &reversed_paint, &reversed_geometry, &detached);
    detached.parent = &body;
    try Check.uncertain(a, &reversed_paint, &reversed_geometry, &detached);
    // A complete physical chain can establish a real nonmatch. The observed
    // descendant root cannot be reinserted above its own BODY parent.
    detached.physical_ancestry_complete = true;
    try std.testing.expect((try reversed_paint.resolveTextPaint(a, &detached, "")).weight == null);
    const absent = try reversed_geometry.resolveContainerIn(a, &detached, "");
    try std.testing.expect(!absent.unresolved and absent.style.width == null);
}


test "HSB inherited-font language class predicates keep exact source and unknown font refusal" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator); defer arena.deinit();
    const a = arena.allocator();
    var profile = try parseSourcesForTargetAlloc(a, &.{
        .{ .css = @embedFile("testdata/hsb-italic-caption01/Gadget-LanguagesAndScripts.css"), .base_url = "" },
        .{ .css = @embedFile("testdata/hsb-italic-caption01/Gadget-Palette.css"), .base_url = "" },
        .{ .css = @embedFile("testdata/hsb-italic-caption01/Gadget-Site.css"), .base_url = "" },
        .{ .css = @embedFile("testdata/hsb-italic-caption01/Common.css"), .base_url = "" },
    }, .screen); defer profile.deinit();
    // The actual ordinary first witness names this exact ordered source rule.
    // This view isolates only that three-selector declaration, not the other
    // retained source rules or the whole page's unresolved styles.
    try std.testing.expect(profile.figure_rules.len > 299);
    const ranges = [_][]const u8{ "ja", "ko", "zh" };
    for (profile.figure_rules[297..300], ranges) |rule, range| {
        try std.testing.expectEqualStrings("\n\tfont-family: inherit;\n", rule.css);
        try std.testing.expectEqualStrings(range, rule.selector.language_range.?);
        try std.testing.expect(rule.selector.uncertain and rule.selector.root_predicate_unresolved);
        try std.testing.expectEqual(@as(usize, 1), rule.selector.chain.len);
        try std.testing.expectEqualStrings("Latn", rule.selector.chain[0].classes[0]);
    }
    var view = profile; view.figure_rules = profile.figure_rules[297..300]; view.custom_properties = null;
    var empty = try parseAlloc(a, ""); defer empty.deinit();
    for ([_][]const u8{ "mw-content-ltr mw-parser-output", "mw-content-rtl mw-parser-output" }, [_]bool{ false, true }) |classes, rtl| {
        const root: TextElement = .{ .tag = "div", .classes = classes, .ancestry_complete = true };
        const az: TextElement = .{ .tag = "i", .classes = "Latn mention", .language = "az", .parent = &root };
        const unknown: TextElement = .{ .tag = "i", .classes = "Latn mention", .parent = &root };
        const barrier: TextElement = .{ .tag = "i", .classes = "Latn mention", .language = "", .parent = &root };
        try std.testing.expectEqual(Profile.FigureRootDirectionUse.independent, view.figureRootDirectionUse(&az));
        try std.testing.expectEqualDeep(try empty.resolveFigure(a, &az, 1, rtl), try view.resolveFigure(a, &az, 1, rtl));
        // Independence never proves a possible-match inherited font harmless.
        try std.testing.expect((try view.resolveFigure(a, &unknown, 1, rtl)).unresolved);
        try std.testing.expect((try view.resolveFigure(a, &barrier, 1, rtl)).unresolved);
        for (ranges) |language| {
            const foreign: TextElement = .{ .tag = "i", .classes = "Latn mention", .language = language, .parent = &root };
            try std.testing.expect((try view.resolveFigure(a, &foreign, 1, rtl)).unresolved);
        }
    }
    for ([_][]const u8{
        ".Latn:lang(ja){font-family:serif}", ".Latn:lang(ja){font-family:inherit;color:red}",
        ".Latn:lang(ja){font-family:var(--family)}", ".Latn:lang(ja){font-family:inherit;unknown:x}",
        ".Latn:lang('ja'){font-family:inherit}", ".Latn:lang(ja,ko){font-family:inherit}",
        ".Latn:lang(ja):dir(rtl){font-family:inherit}", ".outer .Latn:lang(ja){font-family:inherit}",
        ".Latn:lang(ja) > i{font-family:inherit}", ".Latn:lang(ja) + i{font-family:inherit}",
        ".mw-content-rtl:lang(ja){font-family:inherit}",
        ".Latn.mw-content-rtl:lang(ja){font-family:inherit}",
        ".mw-content-ltr:lang(ja).Latn{font-family:inherit}",
    }) |css| {
        var strict = try parseAlloc(a, css); defer strict.deinit();
        try std.testing.expectEqual(Profile.FigureRootDirectionUse.unresolved, strict.figureRootDirectionUse(null));
    }
}

test "HSB actual only-child Figure predicate preserves direction independence and unresolved matching" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    const site = @embedFile("testdata/hsb-italic-caption01/Gadget-Site.css");
    try std.testing.expectEqual(@as(usize, 1), std.mem.count(u8, site, "p:has(> span.etymid:only-child)"));
    var profile = try parseSourcesForTargetAlloc(a, &.{
        .{ .css = @embedFile("testdata/hsb-italic-caption01/Gadget-LanguagesAndScripts.css"), .base_url = "" },
        .{ .css = @embedFile("testdata/hsb-italic-caption01/Gadget-Palette.css"), .base_url = "" },
        .{ .css = site, .base_url = "" },
        .{ .css = @embedFile("testdata/hsb-italic-caption01/Common.css"), .base_url = "" },
    }, .screen);
    defer profile.deinit();
    // This is the next actual ordinary witness after the separately qualified
    // inherited-font rules. Keep the full ordered CSS around the queried rule.
    try std.testing.expect(profile.figure_rules.len > 645);
    const rule = profile.figure_rules[645];
    try std.testing.expectEqualStrings("\n\tdisplay: inline;\n", rule.css);
    try std.testing.expect(rule.selector.uncertain and !rule.selector.root_predicate_unresolved);
    try std.testing.expectEqual(@as(usize, 1), rule.selector.chain.len);
    try std.testing.expectEqualStrings("p", rule.selector.chain[0].tag.?);
    var view = profile;
    view.figure_rules = profile.figure_rules[645..646];
    view.custom_properties = null;
    try std.testing.expectEqual(Profile.FigureRootDirectionUse.independent, view.figureRootDirectionUse(null));
    // Root independence grants no :has/only-child match or computed display.
    // A possible actual P subject must still retain the unknown style effect.
    const paragraph: TextElement = .{ .tag = "p" };
    try std.testing.expect((try view.resolveFigure(a, &paragraph, 1, false)).unresolved);
    // The next paid witness is the Parsoid heading-sibling selector. Its
    // META attribute is not a fact about either generated DIV root.
    const meta_negation = ":not(meta[property=\"mw:PageProp/toc\"])";
    try std.testing.expectEqual(@as(usize, 1), std.mem.count(u8, site, meta_negation));
    var builder: Builder = .{ .a = a };
    try std.testing.expect(try builder.invariantRootNegationCompound(meta_negation));
    for ([_][]const u8{
        ":not(META[property=\"mw:PageProp/toc\"])",
        ":not(meta[property])", ":not(meta[property^=\"mw:PageProp/\"])",
        ":not(meta[property=\"mw:PageProp/toc\"]):not(.toc)",
        ":not(span.mw-content-rtl[dir=rtl])", ":not(div.impossible[property])",
    }) |negation| try std.testing.expect(try builder.invariantRootNegationCompound(negation));
    for ([_][]const u8{
        ":not(div[property])", ":not([property])",
        ":not(.mw-content-rtl[property])", ":not(.mw-content-ltr[dir=rtl])",
        ":not(div[class=\"mw-content-rtl\"])", ":not(div[dir=rtl])",
        ":not(meta[property=\"unterminated])", ":not(meta[property=])",
        ":not(meta[property]div)", ":not(meta[property])extra",
        ":not(meta[property],div)", ":not(meta[property] div)",
        ":not(meta[property]:dir(rtl))", ":not(meta[property]:has(div))",
        ":not(meta\\[property])",
    }) |negation| try std.testing.expect(!try builder.invariantRootNegationCompound(negation));
    try std.testing.expect(profile.figure_rules.len > 723);
    const heading_rule = profile.figure_rules[723];
    try std.testing.expectEqualStrings("\n\tborder-top: 1px solid var(--border-color-base, #a2a9b1);\n\tpadding-top: 1em;\n\tmargin-top: 0.2em;\n", heading_rule.css);
    try std.testing.expect(heading_rule.selector.uncertain and !heading_rule.selector.root_predicate_unresolved);
    var heading_view = profile;
    heading_view.figure_rules = profile.figure_rules[723..724];
    heading_view.custom_properties = null;
    try std.testing.expectEqual(Profile.FigureRootDirectionUse.independent, heading_view.figureRootDirectionUse(null));
    // No adjacent-sibling/attribute/not/first-of-type match is granted.
    const root: TextElement = .{ .tag = "div", .classes = "mw-parser-output" };
    const heading: TextElement = .{ .tag = "div", .classes = "mw-heading2", .parent = &root };
    try std.testing.expect((try heading_view.resolveFigure(a, &heading, 1, false)).unresolved);
    const tags = [_][]const u8{ "span", "b", "i", "strong", "em", "a", "p", "br", "small", "sup" };
    var witness: Profile.FigureRootDirectionWitness = .{};
    const full = profile.figureRootDirectionUseWithCompleteClasses(null, "Latn mention", &tags,
        null, false, null, null, &witness);
    if (full == .unresolved) std.debug.print("HSB full CSS next witness reason={s} rule={d} css={s}\n",
        .{ @tagName(witness.reason), witness.rule_index, witness.css });
    try std.testing.expect(full != .unresolved);
    for ([_][]const u8{
        "p:has(> span.etymid:only-child)",
        "p:has(> SPAN.etymid:ONLY-CHILD)",
        "p:has( > span.etymid:only-child )",
        "p:has(> span.etymid:target:only-child)",
        "p:has(> span.etymid:only-child:target)",
        "p:has(> span.mw-content-rtl:only-child)",
        "p:has(> span.mw-content-ltr:only-child)",
    }) |selector| {
        const css = try std.fmt.allocPrint(a, "{s}{{display:inline}}", .{selector});
        var selected = try parseForTargetAlloc(a, css, .screen);
        defer selected.deinit();
        try std.testing.expectEqual(@as(usize, 1), selected.figure_rules.len);
        try std.testing.expect(selected.figure_rules[0].selector.uncertain);
        try std.testing.expect(!selected.figure_rules[0].selector.root_predicate_unresolved);
        try std.testing.expectEqual(Profile.FigureRootDirectionUse.independent, selected.figureRootDirectionUse(null));
        try std.testing.expect((try selected.resolveFigure(a, &paragraph, 1, false)).unresolved);
    }
    for ([_][]const u8{
        "p:has(> div:only-child)", "p:has(> .etymid:only-child)",
        "p:has(> :only-child)", "p:has(> span.etymid:only-child > div)",
        "p:has(> span.etymid:only-child + div)",
        "p:has(> span.etymid:only-child ~ div)",
        "p:has(> span.etymid:only-child, div)",
        "p:has(> span.etymid:only-child:only-child)",
        "p:has(> span.etymid:only-child:target:target)",
        "p:has(> span.etymid:only-child:hover)",
        "p:has(> span.etymid:only-child:dir(rtl))",
        "p:has(> span.etymid:only-child:lang(az))",
        "p:has(> span.etymid:only-child:not(.other))",
        "p:has(> span.etymid:only-child[data-x])",
        "p:has(> span.etymid:only-child::before)",
        "p:has(> span.etymid\\:only-child)",
        "p:has(> span.etymid:only-child >)",
        "p:has(> span.etymid:only-child):dir(rtl)",
        "p:has(> span.etymid:only-child):lang(az)",
    }) |selector| {
        const css = try std.fmt.allocPrint(a, "{s}{{display:inline}}", .{selector});
        var strict = try parseForTargetAlloc(a, css, .screen);
        defer strict.deinit();
        try std.testing.expectEqual(Profile.FigureRootDirectionUse.unresolved, strict.figureRootDirectionUse(null));
    }
}


test "bidi declaration scanner ignores exact German font rule empty trivia and preserves malformed refusals" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator); defer arena.deinit();
    const a = arena.allocator();
    const actual = " font-family: 'Arial Unicode MS', Code2000, 'MPH 2B Damase', 'DejaVu Sans', sans-serif; ";
    for ([_][]const u8{ actual[0 .. actual.len - 1], actual, "", " ; \t\n;\x0c ; ", "/* only trivia */ ;", "font-family:'semi;colon'; ; " }) |css| {
        try std.testing.expect(!try hasBidiDeclaration(a, css));
    }
    for ([_][]const u8{ "direction:rtl; ", "unicode-bidi:isolate; ", "broken", " ; broken ; ", "font-family:serif; dangling", "\\64irection:rtl", "direction:" }) |css| {
        try std.testing.expect(try hasBidiDeclaration(a, css));
    }
    const source = try std.fmt.allocPrint(a, ".a{{{s}}}.b{{{s}}}", .{ actual[0 .. actual.len - 1], actual });
    var profile = try parseAlloc(a, source); defer profile.deinit();
    const first: TextElement = .{ .tag = "span", .classes = "a" };
    const second: TextElement = .{ .tag = "span", .classes = "b" };
    try std.testing.expect(try profile.sourceBidiScopeUnchanged(a, &first, "font-size:1.4em"));
    try std.testing.expect(try profile.sourceBidiScopeUnchanged(a, &second, "font-size:1.4em; \t ; "));
    try std.testing.expect(!try profile.sourceBidiScopeUnchanged(a, &second, " ; broken ; "));
    try std.testing.expect(!try profile.sourceBidiScopeUnchanged(a, &second, "direction:ltr; "));
}

// Each ordinary in-flow owner retains its own padding or background interval.
// Descendants may change script/ink, so the effective leaf background alone
// cannot define the declaring inline's paint band or its horizontal advance.
pub const StaticInlineOwnerPaint = struct {
    padding: types.StyleEdges,
    background: ?[]const u8,
};

// This is a selection hint only. The full parser and cascade below own every
// accepted edge and paint; absence of a hint keeps the ordinary parser route.
pub fn staticInlineOwnerCandidate(css: []const u8) bool {
    return std.ascii.findIgnoreCase(css, "padding") != null or std.ascii.findIgnoreCase(css, "background") != null;
}

pub fn staticInlineOwnerValues(a: std.mem.Allocator, css: []const u8, environment: CustomEnvironment) !?StaticInlineOwnerPaint
{
    if (css.len == 0 or css.len > max_css_bytes or !staticInlineOwnerCandidate(css)) return null;
    // This source issuer admits only explicit padding and solid background;
    // the existing font query resolves a font-size declaration independently.
    // Every other possible matching declaration keeps its original obligation.
    var declarations: std.ArrayList(ObservedFigureDeclaration) = .empty;
    defer declarations.deinit(a);
    try appendObservedFigureDeclarations(a, &declarations, css, .{ .inline_style = true }, false, false, null, 0);
    var own_background = false;
    for (declarations.items) |d| {
        if (d.syntax_unknown or d.rank_unknown or d.uncertain) return null;
        if (inlineBoxKeyword(d.name, &.{ "background", "background-color" })) {
            own_background = true;
            continue;
        }
        if (!inlineBoxKeyword(d.name, &.{ "padding", "padding-left", "padding-right", "padding-top", "padding-bottom", "font-size" })) return null;
    }
    const resolved_edges = try observedFigureEdges(a, declarations.items, environment, true, false, 1, null);
    if (resolved_edges.unresolved or resolved_edges.value == null) return null;
    const padding = observedFigureFixedEdges(resolved_edges.value.?) orelse return null;
    if (padding.left.unit != .px or padding.right.unit != .px or padding.top.value != 0 or padding.bottom.value != 0 or
        (padding.left.value == 0 and padding.right.value == 0 and !own_background)) return null;
    if (!try inlineBoxStaticBackgroundImageAbsent(a, declarations.items, environment)) return null;
    var background: ?[]const u8 = null;
    if (own_background) {
        const paint = try observedFigureColor(a, declarations.items, "background-color", environment, null, null);
        if (paint.unresolved or paint.value == null or paint.value.?.kind != .rgb) return null;
        background = paint.value.?.value;
    }
    return .{ .padding = padding, .background = background };
}

pub fn staticInlineOwnerScope(profile: *const Profile, a: std.mem.Allocator, element: *const TextElement,
    css: []const u8, environment: CustomEnvironment, chain: []const []const u8) !bool
{
    if (!std.ascii.eqlIgnoreCase(element.tag, "span") or !Profile.rubySourceDeclarationChainValid(element, css, chain)) return false;
    const absent = inlineBoxSourceAbsence(element);
    if (!try staticInlineDirectionDefaultsWithAbsenceAlloc(a, profile, chain, absent) or
        !try inlineBoxSourceInheritedDefaultsCarrierIn(profile, a, chain, environment, false, false, absent, null)) return false;
    var current: ?*const Profile = profile;
    var remaining: usize = 16;
    while (current) |sheet| : (current = sheet.page_style_parent) {
        if (remaining == 0) return false;
        remaining -= 1;
        if (!staticInlineOwnerRulesAbsent(sheet, element)) return false;
    }
    return true;
}

// Only a current property-local receipt can refute an otherwise unknown
// selector. A known matching rule still belongs to this node's cascade.
pub fn staticInlineOwnerRulesAbsent(profile: *const Profile, element: *const TextElement) bool {
    if (profile.globally_unresolved or (profile.page_style_parent != null and element.page_style_root == null)) return false;
    const absence = inlineBoxSourceAbsence(element);
    for (profile.container_rules) |rule| {
        switch (rule.selector.matchIn(element, profile.page_style_parent != null)) {
            .no => continue,
            .known => return false,
            .unknown => {
                const facts = absence orelse return false;
                if (!facts.local_box or !inlineBoxInheritedRuleAbsent(profile, rule, facts)) return false;
            },
        }
    }
    return true;
}

fn staticInlineOwnerPaintIn(profile: *const Profile, a: std.mem.Allocator, element: *const TextElement,
    css: []const u8, environment: CustomEnvironment, chain: []const []const u8) !?StaticInlineOwnerPaint
{
    const selected = (try staticInlineOwnerValues(a, css, environment)) orelse return null;
    return if (try staticInlineOwnerScope(profile, a, element, css, environment, chain)) selected else null;
}

test "classifier padding and paint are three independent source-owned inline ranges" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    // A local absence may exclude an article-class chain. Actual matching
    // ancestors and selectors requiring the surrounding HTML retain their CSS.
    var class_sheet = try parseForTargetAlloc(a, ".Arab i{transform:translateX(2px)}", .screen);
    defer class_sheet.deinit();
    var parent_node: TextElement = .{ .tag = "span", .classes = "Arab" };
    var italic_node: TextElement = .{ .tag = "i", .parent = &parent_node, .source_inline_box_ancestor_classes = "mw-parser-output Arab" };
    try std.testing.expect(!staticInlineOwnerRulesAbsent(&class_sheet, &italic_node));
    parent_node.classes = "";
    italic_node.source_inline_box_ancestor_classes = "mw-parser-output";
    try std.testing.expect(staticInlineOwnerRulesAbsent(&class_sheet, &italic_node));
    var outer_sheet = try parseForTargetAlloc(a, "html.Arab i{transform:translateX(2px)}", .screen);
    defer outer_sheet.deinit();
    try std.testing.expect(!staticInlineOwnerRulesAbsent(&outer_sheet, &italic_node));
    var empty = try parseAlloc(a, "");
    defer empty.deinit();
    const element: TextElement = .{ .tag = "span" };
    const outer = "padding-left:15px; font-size:80%";
    const painted = "background:#EDFFFF";
    const separator = "padding-left:4px; padding-right:4px";
    const p = (try staticInlineOwnerPaintIn(&empty, a, &element, outer, .{}, &.{outer})) orelse return error.TestUnexpectedResult;
    try std.testing.expectEqualDeep(types.StyleLength{ .unit = .px, .value = 15 }, p.padding.left);
    try std.testing.expect(p.padding.right.value == 0 and p.background == null);
    const b = (try staticInlineOwnerPaintIn(&empty, a, &element, painted, .{}, &.{ painted, outer })) orelse return error.TestUnexpectedResult;
    try std.testing.expectEqualStrings("#edffff", b.background.?);
    try std.testing.expect(b.padding.left.value == 0 and b.padding.right.value == 0);
    const s = (try staticInlineOwnerPaintIn(&empty, a, &element, separator, .{}, &.{ separator, painted, outer })) orelse return error.TestUnexpectedResult;
    try std.testing.expectEqualDeep(types.StyleLength{ .unit = .px, .value = 4 }, s.padding.left);
    try std.testing.expectEqualDeep(s.padding.left, s.padding.right);
    try std.testing.expect(s.background == null);
    for ([_][]const u8{ "padding:1px", "padding-left:4px;transform:rotate(5deg)", "background:linear-gradient(red,blue)",
        "padding-right:4px;opacity:.5", "background:rgba(255,255,255,.2)", "background:red;position:relative" }) |other| {
        try std.testing.expect(try staticInlineOwnerPaintIn(&empty, a, &element, other, .{}, &.{other}) == null);
    }
    var styled = try parseAlloc(a, "span{display:inline-block}");
    defer styled.deinit();
    try std.testing.expect(try staticInlineOwnerPaintIn(&styled, a, &element, outer, .{}, &.{outer}) == null);
    try std.testing.expect(try staticInlineOwnerPaintIn(&empty, a, &element, outer, .{}, &.{separator}) == null);
}
